window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-1/eaif","titre":"EAIF I","sources":[{"t":"EAIF I — Corps et conscience","q":"qcm/corps-conscience-01.html","f":"fiches/corps-conscience-01.html"},{"t":"EAIF I — Cadre anatomique et physiologique","q":"qcm/massage-01-anatomie.html","f":"fiches/massage-01-anatomie.html"},{"t":"EAIF I — Le toucher et la peau","q":"qcm/massage-02-toucher-peau.html","f":"fiches/massage-02-toucher-peau.html"},{"t":"EAIF I — Modèle physiologique de la thérapie manuelle","q":"qcm/massage-03-therapie-manuelle.html","f":"fiches/massage-03-therapie-manuelle.html"},{"t":"EAIF I — Introduction au massage","q":"qcm/massage-04-introduction.html","f":"fiches/massage-04-introduction.html"},{"t":"EAIF I — Effleurage","q":"qcm/massage-05-effleurage.html","f":"fiches/massage-05-effleurage.html"},{"t":"EAIF I — Pétrissage","q":"qcm/massage-06-petrissage.html","f":"fiches/massage-06-petrissage.html"},{"t":"EAIF I — Tapotement","q":"qcm/massage-07-tapotement.html","f":"fiches/massage-07-tapotement.html"},{"t":"EAIF I — Friction","q":"qcm/massage-08-friction.html","f":"fiches/massage-08-friction.html"},{"t":"EAIF I — Mobilisation articulaire — concepts","q":"qcm/mobart-01-concepts.html","f":"fiches/mobart-01-concepts.html"},{"t":"EAIF I — Mouvements des membres (MS + MI)","q":"qcm/mobart-02-mouvements-membres.html","f":"fiches/mobart-02-mouvements-membres.html"},{"t":"EAIF I — Programme de l'UC","q":"qcm/programme-uc.html","f":"fiches/programme-uc.html"},{"t":"EAIF I — Positionnements et mobilité précoce","q":"qcm/ptam-01-positionnements.html","f":"fiches/ptam-01-positionnements.html"},{"t":"EAIF I — Transferts et biomécanique","q":"qcm/ptam-02-transferts.html","f":"fiches/ptam-02-transferts.html"},{"t":"EAIF I — Aides à la marche et types de marche","q":"qcm/ptam-03-aides-marche.html","f":"fiches/ptam-03-aides-marche.html"},{"t":"EAIF I — Cahier Positions / Mobilité / Transferts","q":"qcm/ptam-04-support-positions.html","f":"fiches/ptam-04-support-positions.html"},{"t":"EAIF I — Manuel des aides à la marche","q":"qcm/ptam-05-support-aides-marche.html","f":"fiches/ptam-05-support-aides-marche.html"}],"questions":[{"q":"Le kinésithérapeute est défini comme :","o":["Un spécialiste des médicaments et de leurs effets","Un spécialiste du corps et un professionnel du contact","Un chirurgien de l'appareil locomoteur et des articulations","Un psychologue spécialisé dans la relation de soin"],"r":1,"e":"Le kinésithérapeute est un SPÉCIALISTE en techniques corporelles ET un professionnel du CONTACT. Il est spécialiste en techniques corporelles.","s":0},{"q":"À quelle semaine de grossesse les premières sensations tactiles apparaissent-elles ?","o":["3e semaine","5e semaine","7e semaine","12e semaine"],"r":2,"e":"À la 7e semaine de grossesse : sensations dans la bouche, mains et pieds (le sommet du crâne reste insensible).","s":0},{"q":"Le toucher INSTRUMENTAL se caractérise par :","o":["Une force faible, un contact large et communicatif","Un geste local, bref, appuyé, mécanique et non impliqué","Une empathie et une compréhension de toute la personne","Un contact toujours douloureux, appuyé et prolongé dans le temps"],"r":1,"e":"Instrumental = LOCAL, BREF, force ÉLEVÉE, mécanique, NON impliqué, correctif.","s":0},{"q":"Le toucher EXPRESSIF se caractérise par :","o":["Un geste mécanique, bref et local, avec une force élevée","Un contact large, maintenu, doux et empathique","Une force maximale, appliquée sur un point précis","Une absence de contact, à distance du corps"],"r":1,"e":"Expressif = LARGE, MAINTIEN du contact, force FAIBLE/moyenne, empathique, communicatif, touche TOUTE la personne. La force est faible à moyenne.","s":0},{"q":"Quelle structure cérébrale est responsable de l'analyse des risques et expériences (origine des émotions) ?","o":["Hippocampe","Amygdale","Hypothalamus","Cervelet"],"r":1,"e":"L'AMYGDALE analyse les risques et expériences — de là naissent les réactions émotionnelles.","s":0},{"q":"L'hippocampe est responsable de :","o":["La faim et la soif, par l'hypothalamus voisin","La mémoire et l'orientation","Les émotions et la peur","Les réflexes et la posture"],"r":1,"e":"L'HIPPOCAMPE = mémoire et orientation. Les maladies de la mémoire (Alzheimer) l'affectent directement.","s":0},{"q":"Le cortex insulaire est important pour :","o":["L'audition seule, sans lien avec les émotions","L'empathie et la mise en émotion des sensations","Le mouvement volontaire des membres","La digestion et la motricité intestinale"],"r":1,"e":"L'INSULA + cortex somatosensoriel droit = EMPATHIE (Caselli, 1997). Module aussi la douleur.","s":0},{"q":"Le modèle des 4 homoncules sensoriels a été proposé par :","o":["Wilder Penfield, en 1950","Antonio Damásio, dans son livre de 1999","Le chercheur John Kaas, en 1987","Maurice Merleau-Ponty, en 1945"],"r":2,"e":"John Kaas (1987) : 4 homoncules sensoriels (longueur musculaire, récepteurs cutanés lents/rapides, sensations articulaires/pression).","s":0},{"q":"Le nouveau modèle somatosensoriel de Damásio (1999) intègre :","o":["Le seul cortex somesthésique primaire, S1","Tronc cérébral, hypothalamus, insula, S2 et S1","Le cervelet seul, et ses noyaux","Aucune structure cérébrale, ni S1 ni S2"],"r":1,"e":"Damásio : 'Soi neural' = noyaux réticulaires du tronc cérébral + hypothalamus + insula + S2 + S1.","s":0},{"q":"La privation de contact chez l'enfant peut entraîner :","o":["Aucun effet notable, l'enfant s'adaptant sans difficulté","Un retard du développement et des infections répétées","Un surdéveloppement intellectuel et moteur","Une hausse des défenses immunitaires"],"r":1,"e":"Privation = retard de développement, infections/accidents plus fréquents, comportements autorégulateurs (privation de berceau). Le retard concerne le développement intellectuel et physique.","s":0},{"q":"La somatognosie est :","o":["Une maladie neurologique du schéma corporel","La capacité à reconnaître les parties du corps","Une technique de relaxation par le toucher","Un type de toucher thérapeutique, large et maintenu"],"r":1,"e":"Somatognosie = capacité à RECONNAÎTRE les parties du corps, essentielle à la stabilité émotionnelle.","s":0},{"q":"Les 3 objectifs de la relaxation selon Titlebaum (1988) sont :","o":["Le sport, l'alimentation et le sommeil","La prévention, le traitement et la gestion du stress","Les médicaments, le repos et l'activité physique adaptée","Le diagnostic, le pronostic et le suivi"],"r":1,"e":"Titlebaum (1988) : préventif (protéger les organes), traitement (HTA, insomnie, asthme...), compétence de gestion du stress.","s":0},{"q":"Ryman (1995) définit la relaxation comme :","o":["Un sommeil profond, sans aucune conscience","Un état de conscience de paix, sans tension ni anxiété","Une absence totale d'activité du corps et de l'esprit","Une méditation guidée par un thérapeute"],"r":1,"e":"Ryman (1995) : état de CONSCIENCE caractérisé par paix et soulagement de la tension, anxiété, peur.","s":0},{"q":"La relaxation cherche :","o":["Le sommeil profond et réparateur de la nuit","L'homéostasie physique et mentale","L'inactivité totale du corps","La fatigue musculaire générale"],"r":1,"e":"Recherche de l'HOMÉOSTASIE physique et mentale, rétablissement de l'équilibre.","s":0},{"q":"La relaxation musculaire progressive a été développée par :","o":["Schultz, en 1932","Jacobson, en 1938","Benson, en 1975","Mitchell, en 1977"],"r":1,"e":"Jacobson (1938) : relaxation musculaire progressive — alterner contraction/relâchement musculaire.","s":0},{"q":"Le training autogène a été développé par :","o":["Edmund Jacobson, en 1938","Schultz et Luthe, en 1969","Laura Mitchell, en 1977","Gerda Alexander, en 1976"],"r":1,"e":"Schultz & Luthe (1969) : training autogène, méthode psychologique.","s":0},{"q":"L'eutonie est une méthode développée par :","o":["Laura Mitchell","Gerda Alexander","Herbert Benson, cardiologue","Edmund Jacobson"],"r":1,"e":"EUTONIE de Gerda Alexander = méthode de rééducation GLOBALE.","s":0},{"q":"L'effet du toucher thérapeutique sur l'axe HPA est :","o":["↑ libération de cortisol","↓ libération de cortisol","Aucun effet","Augmentation du stress"],"r":1,"e":"Le toucher DIMINUE la libération de cortisol via l'axe hypothalamo-hypophyso-surrénalien.","s":0},{"q":"Le système vestibulaire :","o":["Détecte les goûts et les odeurs des aliments","Situe le corps dans l'espace, surtout la tête","Perçoit les couleurs, puis les formes","Contrôle la digestion et le transit"],"r":1,"e":"Système vestibulaire = coordonnées corporelles dans l'espace, particulièrement la POSTURE DE LA TÊTE.","s":0},{"q":"La peau, en tant qu'organe :","o":["Est le plus petit organe du corps humain","Est le plus grand organe, qui traduit les stimuli","N'a aucun récepteur sensitif dans le derme","Ne participe pas au toucher, rôle tenu par les muscles"],"r":1,"e":"La peau = PLUS GRAND organe du corps, transforme stimuli physiques en communicateurs chimiques et états psychologiques. Elle transforme les stimuli physiques en états chimiques et psychologiques.","s":0},{"q":"Les expériences négatives de toucher (abus) nécessitent souvent :","o":["Davantage de contact direct, pour désensibiliser","Des objets qui servent de médiateurs dans la relation","Aucune adaptation particulière, le soin restant identique","L'arrêt de la thérapie, dès le premier signe"],"r":1,"e":"Aversion au toucher → utiliser des OBJETS qui médiatisent la relation pour préserver le travail thérapeutique.","s":0},{"q":"« Là où le corps et l'esprit se rencontrent » décrit :","o":["L'hippocampe, dans le lobe temporal","L'insula, ou cortex insulaire","Le cervelet, sous le lobe occipital du cerveau","L'amygdale, dans le lobe temporal"],"r":1,"e":"L'INSULA est décrite comme « là où le corps et l'esprit se rencontrent ».","s":0},{"q":"Selon Merleau-Ponty (1999), être une conscience c'est :","o":["Penser sans le corps, dans un esprit séparé du monde","Communiquer de l'intérieur avec le monde et autrui","Être seul, retiré du monde et des autres","Refuser le toucher et le contact d'autrui"],"r":1,"e":"Merleau-Ponty : être conscience = COMMUNIQUER intérieurement avec le monde, le corps et les autres (être AVEC eux). Cette communication passe aussi par le corps.","s":0},{"q":"L'effet anxiolytique du toucher thérapeutique passe par :","o":["Le cervelet, qui relâche tous les muscles posturaux","L'hypothalamus antérieur, qui apaise la tension","Le muscle seul, par un effet mécanique direct","L'os, par une vibration transmise au squelette"],"r":1,"e":"Activation de la région HYPOTHALAMIQUE ANTÉRIEURE → réduction de la tension musculaire et de l'anxiété. La tension visée est musculaire, avec l'anxiété.","s":0},{"q":"Une bonne respiration pour amorcer la relaxation est :","o":["Rapide et superficielle, pour activer le corps","Profonde et régulière, sans aucune tension","Bloquée en fin d'inspiration, pour concentrer","Très lente uniquement, quelle qu'en soit l'amplitude"],"r":1,"e":"Respirations PROFONDES et RÉGULIÈRES, SANS tension. Relaxer le corps relaxe automatiquement l'esprit. Ni les muscles ni la bouche ne doivent être tendus.","s":0},{"q":"L'insula est impliquée dans :","o":["La motricité fine des doigts et de la main","L'intéroception, perception du corps interne","La vision des couleurs et des contrastes","L'audition, des sons graves aux aigus"],"r":1,"e":"Insula = aire clé de l'intéroception (rythme cardiaque, faim, douleur, émotions corporelles).","s":0},{"q":"La théorie des marqueurs somatiques de Damasio explique que :","o":["Les décisions sont purement rationnelles","Les états corporels guident nos décisions","Les émotions n'existent pas en biologie","Le corps et le cerveau sont sans lien"],"r":1,"e":"Marqueurs somatiques : associations corps-émotion-mémoire qui orientent rapidement nos choix.","s":0},{"q":"Le système limbique est principalement :","o":["Moteur, pour le mouvement volontaire","Émotionnel et lié à la mémoire","Sensoriel pur, pour la vision et l'audition","Endocrinien, par l'hypophyse"],"r":1,"e":"Système limbique (hippocampe, amygdale, cortex cingulaire) = émotions, mémoire émotionnelle, motivation.","s":0},{"q":"La relaxation active (PNF de Jacobson) procède par :","o":["Un étirement passif de chaque groupe musculaire","Une contraction puis un relâchement de chaque groupe","Un massage profond de chaque groupe musculaire, en séquence","Une hypnose guidée par la voix du thérapeute"],"r":1,"e":"Jacobson : contracter-relâcher chaque groupe musculaire successivement pour apprendre à reconnaître et lâcher la tension.","s":0},{"q":"Le toucher thérapeutique conscient (pleine présence) :","o":["N'a aucun effet mesurable sur le corps","Active le parasympathique et baisse le cortisol","Augmente le stress et la fréquence cardiaque","Provoque une douleur réflexe au contact de la peau"],"r":1,"e":"Toucher attentif → activation parasympathique (vague), ↓ cortisol, libération d'ocytocine, sécurité affective.","s":0},{"q":"Le kinésithérapeute est décrit comme :","o":["Un spécialiste du corps, professionnel du contact","Un technicien du mouvement et de la machine","Un rééducateur fonctionnel des seuls membres","Un soignant polyvalent, sans spécialité propre"],"r":0,"e":"Ses techniques impliquent de toucher et d'être touché, parfois médiatisé par des objets en début de relation. Il est spécialiste des techniques corporelles.","s":0},{"q":"Parmi les stratégies pour parler de soi, le cours cite :","o":["Le souvenir d'enfance et « qui suis-je ? »","Le seul récit de vie, raconté de façon chronologique","Le seul bilan fonctionnel, réalisé par le kiné","L'entretien directif, avec questions fermées"],"r":0,"e":"Elles s'adaptent à l'âge et à l'état clinique. S'y ajoute « qui est-ce que je veux être ? ».","s":0},{"q":"La notion de « corps-sujet » signifie que :","o":["J'agis seul depuis mon corps, dans un espace et un temps","Le corps est un objet, observé de l'extérieur","Le corps est indépendant de l'esprit qui l'habite","Le corps est interchangeable, comme un outil parmi d'autres"],"r":0,"e":"Merleau-Ponty (1999) exprime ce lien : être une conscience, c'est communiquer intérieurement avec le monde, le corps et les autres. La propriété et la capacité d'action sont liées à ce corps.","s":0},{"q":"La voie de signalisation somatosensorielle suit l'ordre :","o":["Moelle, puis tronc cérébral, puis cortex","Cortex, puis tronc cérébral, puis moelle","Tronc cérébral, puis moelle, puis cortex","Moelle, puis cortex, puis tronc cérébral"],"r":0,"e":"Elle aboutit à une carte des dimensions de l'état corporel.","s":0},{"q":"Le système de l'environnement interne et viscéral implique :","o":["Tronc cérébral, hypothalamus et système autonome","Le système vestibulaire, avec l'oreille interne","La peau et ses récepteurs tactiles","Le cortex moteur et la voie pyramidale"],"r":0,"e":"Les trois systèmes de signalisation sont l'interne et viscéral, le vestibulaire et musculo-squelettique, et le tactile. Les signaux de douleur viscérale en font partie.","s":0},{"q":"La perspective psychanalytique du corps étudie :","o":["Le soi corporel, les projections et le symbolisme du corps","Les liens entre sensations et actions, en neurologie motrice","La corporéité et la spatialité, selon la phénoménologie","L'intelligence spatiale, selon la psychologie cognitive"],"r":0,"e":"Les perspectives neurologique, phénoménologique et psychologique complètent ce panorama. Elle étudie aussi les introjections et l'émergence du Soi.","s":0},{"q":"La perspective psychologique du corps étudie :","o":["Les préludes de la pensée et l'intelligence spatiale","Le symbolisme corporel et les introjections du jeune sujet","La corporéité et la spatialité-temporalité","Les sensations et les perceptions élémentaires"],"r":0,"e":"La perspective phénoménologique porte sur la corporéité, la spatialité-temporalité et le positionnement subjectif. Elle étudie aussi le rôle intégrateur gnosique et praxique.","s":0},{"q":"Parmi les stimuli prénataux du toucher, le cours cite :","o":["Les mouvements et pulsations de la mère, et sa respiration","La seule voix maternelle, perçue à travers l'abdomen","La seule lumière, perçue à travers la paroi utérine","Les seuls sons extérieurs, filtrés par le liquide"],"r":0,"e":"La sensation du toucher est la première à devenir fonctionnelle dans la vie embryonnaire. Le péristaltisme et le rythme diaphragmatique en font partie.","s":0},{"q":"À la 7ᵉ semaine de grossesse, les sensations apparaissent :","o":["À la bouche, aux mains et aux pieds","Sur tout le corps, de façon homogène","Au seul visage, autour des yeux","Aux seules mains, en premier"],"r":0,"e":"Cette chronologie illustre l'antériorité du toucher sur les autres sens. Le sommet du crâne reste insensible.","s":0},{"q":"La peau transforme :","o":["Les stimuli physiques en signaux chimiques et psychiques","Les émotions en mouvements musculaires","Les sons en sensations vibratoires sur toute la surface du corps","La lumière en chaleur, par la mélanine"],"r":0,"e":"Un contact grossier ou agressif suscite rejet, mépris, invalidation, réaction défensive et colère.","s":0},{"q":"Les effets proprioceptifs du toucher thérapeutique consistent à :","o":["Stimuler et réguler les émotions et l'intégration du corps","Augmenter la force musculaire des segments touchés","Améliorer l'amplitude articulaire des segments touchés","Réduire l'œdème des segments touchés, par drainage"],"r":0,"e":"Le toucher expressif touche toute la personne, avec empathie et compréhension. Il s'agit de l'intégration somatognostique.","s":0},{"q":"La privation de contact chez l'enfant entraîne :","o":["Un retard de développement et plus de maladies","Une simple timidité, qui disparaît avec l'âge","Un retard moteur isolé, sans autre conséquence","Aucune conséquence durable sur l'enfant"],"r":0,"e":"La privation de berceau induit des comportements autorégulateurs, et la privation peut conduire à une maladie mentale à l'âge adulte. Le retard est intellectuel et physique ; infections et accidents sont aussi plus fréquents.","s":0},{"q":"Chez la personne âgée, la privation de contact entraîne :","o":["Une image corporelle dégradée et un isolement accru","Une amélioration de l'autonomie et de l'humeur","Une stimulation cognitive et une vigilance accrue du sujet âgé","Aucun effet, le besoin de contact disparaissant"],"r":0,"e":"Le cours établit un lien entre manque de contact physique et social et mort prématurée. L'isolement est aggravé par la baisse des autres modalités sensorielles.","s":0},{"q":"En cas de danger, de handicap, d'anxiété ou de maladie, le cours décrit :","o":["Une régression vers les besoins tactiles de l'enfance","Une aversion durable pour tout contact physique","Une indifférence au contact, qu'il soit doux ou appuyé","Une hypersensibilité douloureuse au moindre contact"],"r":0,"e":"Le besoin de contact diminue par ailleurs avec l'âge.","s":0},{"q":"Devant une aversion au toucher liée à des expériences d'abus, il faut :","o":["Utiliser des objets médiateurs","Insister progressivement","Renoncer à toute technique","Augmenter la pression"],"r":0,"e":"Les origines de l'interprétation du toucher tiennent aux expériences antérieures, aux croyances, à la culture et à l'éducation.","s":0},{"q":"La stabilité émotionnelle suppose :","o":["Une somatognosie organisée et une stabilité sensorielle","La seule somatognosie, sans autre condition","La seule stabilité tactile, sans les autres sens du corps","Le seul contrôle cognitif des émotions"],"r":0,"e":"Toutes les émotions utilisent le « théâtre du corps » pour se manifester. La stabilité est sensorielle, proprioceptive, tactile et vestibulaire.","s":0},{"q":"Les cinq voies de stimulation sensorielle citées sont :","o":["Tactile, auditive, visuelle, olfactive et gustative","Tactile, proprioceptive et vestibulaire","Visuelle, auditive et tactile","Tactile, thermique, douloureuse, vibratoire et articulaire"],"r":0,"e":"Le toucher thérapeutique constitue la voie tactile.","s":0},{"q":"Le modèle des 4 homoncules sensoriels de John Kaas (1987) distingue :","o":["Longueur musculaire, récepteurs cutanés et sensations articulaires","Quatre régions corticales, une par lobe cérébral","Quatre modalités émotionnelles, de la joie à la peur, selon le corps","Quatre voies ascendantes, de la moelle vers le cortex"],"r":0,"e":"Il succède au modèle de l'homoncule unique de Wilder Penfield. Les récepteurs cutanés sont lents et rapides ; la pression s'y ajoute.","s":0},{"q":"Le « Soi neural » de Damásio (1999) inclut :","o":["Tronc cérébral, hypothalamus, insula, S2 et S1","Le seul cortex insulaire, sans S1","Le seul système limbique, avec l'amygdale","Le seul homoncule de Penfield, en S1"],"r":0,"e":"Il associe le corps et l'émotion dans un nouveau modèle somatosensoriel. Ce sont les noyaux réticulaires du tronc cérébral.","s":0},{"q":"Le système vestibulaire fournit :","o":["Les coordonnées du corps dans l'espace","La sensibilité tactile de la peau","La douleur viscérale de l'abdomen","La température cutanée du corps"],"r":0,"e":"Il appartient au système vestibulaire et musculo-squelettique, celui de la proprioception.","s":0},{"q":"Quels systèmes sont touchés indirectement lorsqu'on touche la peau ?","o":["Aucun autre système que la peau elle-même","Les systèmes lymphatique, circulatoire et nerveux","Le seul système digestif, par voie réflexe","Le seul système squelettique, par la pression transmise"],"r":1,"e":"Toucher la peau implique d'agir sur les systèmes lymphatique, circulatoire et nerveux qui traversent toutes les couches.","s":1},{"q":"Sur la face antérieure, sous le muscle dans la moitié supérieure du tronc, on trouve :","o":["Les organes abdominaux, le foie et l'estomac","La cage thoracique, les poumons et le cœur","Les vertèbres lombaires et le sacrum","Les reins et les glandes surrénales"],"r":1,"e":"Moitié supérieure antérieure : cage thoracique, poumons, cœur.","s":1},{"q":"À l'arrière du cou, sous la couche musculaire, se trouve :","o":["La trachée et l'œsophage, en profondeur","La colonne vertébrale et la moelle épinière","Le larynx et les cordes vocales, en avant","La thyroïde et les glandes parathyroïdes"],"r":1,"e":"À l'arrière du cou : colonne vertébrale + moelle épinière + racines nerveuses cervicales postéro-latérales.","s":1},{"q":"À l'avant du cou, sous la couche musculaire, on trouve :","o":["Le cerveau, le cervelet et le bulbe","La thyroïde, le larynx et la trachée","La moelle épinière, ses racines et les vertèbres","La cage thoracique, le sternum et les côtes"],"r":1,"e":"Avant du cou : parties supérieures des systèmes digestif et respiratoire (thyroïde, larynx, trachée).","s":1},{"q":"Le visage est une région :","o":["Peu innervée","Hautement innervée","Sans vaisseaux","Sans ganglions"],"r":1,"e":"Région hautement innervée + vaisseaux et ganglions palpables.","s":1},{"q":"Le membre supérieur contient :","o":["Fémur, rotule, tibia, péroné, tarse et phalanges du pied","Omoplate, clavicule, humérus, avant-bras et main","Rotule, fémur, os coxal et sacrum","Os du tarse, métatarse et orteils"],"r":1,"e":"Membre supérieur : omoplate, clavicule, humérus, radius, ulna, os du carpe, phalanges. L'avant-bras comprend radius et ulna, la main le carpe et les phalanges.","s":1},{"q":"Le membre inférieur contient :","o":["Humérus, radius, ulna, carpe et phalanges de la main","Fémur, rotule, tibia, péroné, tarse et phalanges","Clavicule, omoplate, humérus et sternum","Carpe, métacarpe et phalanges des doigts"],"r":1,"e":"Membre inférieur : fémur, rotule, tibia, péroné, tarse, phalanges.","s":1},{"q":"L'ordre des couches anatomiques superficielles → profondes est :","o":["Os, puis muscle, puis peau","Peau, puis muscles, puis os et organes","Muscle, puis peau, puis os et organes","Indifférent, selon la région du corps"],"r":1,"e":"Peau (système tégumentaire) → muscles → os et organes profonds.","s":1},{"q":"Les racines nerveuses cervicales postéro-latérales se prolongent vers :","o":["Les membres inférieurs","Les deux membres supérieurs","Le visage et le cou","Les organes du thorax"],"r":1,"e":"Les racines nerveuses postéro-latérales de la colonne cervicale se prolongent vers les MEMBRES SUPÉRIEURS.","s":1},{"q":"Sur la face postérieure du tronc, la ligne médiane contient :","o":["Le cœur, en profondeur","La colonne vertébrale","Les deux poumons","Le foie et la vésicule biliaire"],"r":1,"e":"Ligne médiane postérieure du tronc = colonne vertébrale.","s":1},{"q":"Sous les muscles de la tête, en suivant la couche, on trouve :","o":["Les organes digestifs, l'estomac, le foie et la rate","Les os du crâne, le cerveau et le tronc cérébral","La trachée, le larynx et la thyroïde","Le cœur, les poumons et le médiastin"],"r":1,"e":"Tête : sous les muscles/aponévroses → os du crâne, cerveau, tronc cérébral.","s":1},{"q":"Quel système n'a PAS de couche dédiée mais traverse toutes les autres ?","o":["Le système squelettique, avec les os","Le circulatoire, avec le lymphatique et le nerveux","Le système tégumentaire, avec la peau et les phanères","Le système musculaire, avec les tendons"],"r":1,"e":"Les systèmes circulatoire, lymphatique et nerveux traversent toutes les couches anatomiques.","s":1},{"q":"L'omoplate fait partie :","o":["Du membre inférieur","Du membre supérieur","Du crâne","Du tronc"],"r":1,"e":"L'omoplate (scapula) fait partie du membre supérieur.","s":1},{"q":"Quel os est unique au membre inférieur dans la liste ?","o":["Humérus","Rotule","Radius","Clavicule"],"r":1,"e":"Rotule = patella, unique au membre inférieur.","s":1},{"q":"L'ulna se trouve :","o":["Au pied, dans le tarse","À l'avant-bras, au membre supérieur","Au crâne, dans la face","Au bassin, dans la ceinture pelvienne"],"r":1,"e":"L'ulna (cubitus) fait partie de l'avant-bras.","s":1},{"q":"Le tarse appartient à :","o":["À l'avant-bras, au membre supérieur","Au poignet, au membre supérieur","Au pied, au membre inférieur","À la main, au membre supérieur"],"r":2,"e":"Os du tarse = arrière-pied (membre inférieur). Le carpe est au poignet.","s":1},{"q":"Connaître les couches anatomiques sert au kiné à :","o":["Rendre le massage plus esthétique pour le patient","Adapter le massage aux structures touchées","Rien de particulier pour la pratique","Refuser les patients trop fragiles"],"r":1,"e":"Connaître les couches permet d'anticiper quelles structures sont touchées par chaque type de pression.","s":1},{"q":"Quelle structure traverse la colonne vertébrale ?","o":["L'œsophage, en avant","La moelle épinière","La trachée, en avant","Le larynx, en haut du cou"],"r":1,"e":"La moelle épinière traverse le canal rachidien à l'intérieur de la colonne vertébrale.","s":1},{"q":"Les ganglions lymphatiques sont palpables :","o":["Uniquement aux pieds, derrière les malléoles","Au visage et aux zones superficielles","Jamais, ils sont toujours trop profonds","Uniquement à la naissance, puis plus du tout"],"r":1,"e":"Au visage et dans d'autres régions superficielles, les ganglions et vaisseaux sont palpables.","s":1},{"q":"La cage thoracique contient :","o":["Reins et estomac","Poumons et cœur","Foie et pancréas","Intestins"],"r":1,"e":"Cage thoracique = poumons et cœur (organes vitaux protégés).","s":1},{"q":"L'humérus est l'os :","o":["De la cuisse","Du bras","Du tibia","De la main"],"r":1,"e":"Humérus = os unique du bras (entre épaule et coude).","s":1},{"q":"L'omoplate (scapula) s'articule avec :","o":["Le sternum directement, par une facette","La clavicule et l'humérus","Les côtes, par de vraies articulations synoviales","Le radius, par la tête radiale"],"r":1,"e":"Scapula : acromio-claviculaire (clavicule) + gléno-humérale (humérus). Elle glisse sur le gril costal. Elle s'articule avec la clavicule par l'acromion et glisse sur le gril costal.","s":1},{"q":"Le triangle des Petit (lombaire) est délimité par :","o":["Trapèze, rhomboïde et bord médial de la scapula","Grand dorsal, oblique externe et crête iliaque","Pectoral, deltoïde et clavicule","Quadriceps, iliopsoas et ligament inguinal"],"r":1,"e":"Triangle des Petit (zone de faiblesse pariétale lombaire) = grand dorsal + oblique externe + crête iliaque.","s":1},{"q":"La région poplitée correspond à :","o":["Face antérieure du genou","Creux derrière le genou","Pli du coude","Aine"],"r":1,"e":"Région poplitée = creux postérieur du genou, contient l'artère poplitée, les nerfs tibial et fibulaire.","s":1},{"q":"Le creux axillaire contient principalement :","o":["Uniquement des muscles, sans vaisseau ni nerf","Le plexus brachial et l'artère axillaire","Le sternum et les cartilages costaux","Aucune structure importante"],"r":1,"e":"Creux axillaire (aisselle) : plexus brachial, artère et veine axillaires, ganglions lymphatiques importants. On y trouve aussi la veine axillaire et des ganglions lymphatiques.","s":1},{"q":"Le ligament inguinal sépare :","o":["Le thorax de l'abdomen","L'abdomen de la cuisse","La tête du cou","Le bras de l'avant-bras"],"r":1,"e":"Ligament inguinal = limite entre paroi abdominale antérieure et région inguino-fémorale (passage des vaisseaux fémoraux).","s":1},{"q":"Le diaphragme :","o":["Est un muscle inspiratoire accessoire","Est le muscle principal de l'inspiration","Est un os plat, entre thorax et abdomen","N'a aucun rôle dans la ventilation"],"r":1,"e":"Diaphragme : muscle inspiratoire principal, dôme musculo-tendineux séparant thorax et abdomen. Il sépare le thorax de l'abdomen.","s":1},{"q":"Sur la face postérieure du tronc, on palpe d'abord :","o":["Le foie, sous les dernières côtes droites","Les apophyses épineuses des vertèbres","Les poumons, entre les côtes","Le rectum, au-dessus du coccyx"],"r":1,"e":"Apophyses épineuses = repères médians palpables, base de la palpation rachidienne.","s":1},{"q":"Quelle artère palper au pli du coude ?","o":["L'artère carotide, ou cervicale","L'artère brachiale, ou humérale","L'artère fémorale, ou crurale","L'artère tibiale postérieure, à la cheville"],"r":1,"e":"Artère brachiale (humérale) palpable au pli du coude, utilisée pour la pression artérielle.","s":1},{"q":"L'artère radiale se palpe :","o":["Au creux du genou, au fond du losange poplité","À la face antérieure du poignet, côté pouce","Dans l'aisselle, contre l'humérus","Au cou, le long de la trachée"],"r":1,"e":"Pouls radial = face antérieure du poignet, côté radial (pouce), repère anatomique de référence.","s":1},{"q":"Connaître les couches anatomiques permet au kiné de :","o":["Faire de l'esthétique sur la peau","Adapter la profondeur, la pression et la direction","Faire des incisions en toute sécurité","Prescrire des médicaments, des examens et des soins adaptés"],"r":1,"e":"Cette connaissance guide le choix de la TECHNIQUE et de la PROFONDEUR pour atteindre la structure cible en toute sécurité.","s":1},{"q":"La couche squelettique et des organes est traversée par :","o":["Les systèmes circulatoire, lymphatique et nerveux","Le seul système circulatoire, sans les autres","Le seul système nerveux, sans les vaisseaux","Aucun autre système, elle est isolée"],"r":0,"e":"Les trois couches sont, de la surface vers la profondeur, tégumentaire, musculaire, puis squelettique et organes.","s":1},{"q":"Toucher la peau revient à agir indirectement sur :","o":["Les systèmes lymphatique, circulatoire et nerveux","La seule peau, sans effet sur les autres systèmes","Le seul muscle, situé juste sous la peau","Le seul système nerveux, par les récepteurs"],"r":0,"e":"C'est le principe anatomique qui fonde l'effet systémique du toucher. Ces systèmes traversent toutes les couches.","s":1},{"q":"Sous la couche musculaire, la moitié inférieure de la face antérieure correspond :","o":["Aux organes internes et abdominaux","À la cage thoracique et au diaphragme","Aux poumons et au cœur","À la colonne vertébrale"],"r":0,"e":"La moitié supérieure correspond à la cage thoracique, aux poumons et au cœur, en face antérieure comme postérieure.","s":1},{"q":"La ligne médiane postérieure correspond, sous les muscles :","o":["À la colonne vertébrale","Aux organes abdominaux","Aux poumons","Au diaphragme"],"r":0,"e":"En arrière du cou, on trouve la colonne, la moelle épinière et les racines nerveuses cervicales postéro-latérales destinées aux membres supérieurs.","s":1},{"q":"Sous les muscles de la partie antérieure du cou se trouvent :","o":["La thyroïde, le larynx et la trachée","La colonne cervicale, avec la moelle","Les racines nerveuses, les vertèbres et la moelle","L'œsophage seul, sans la trachée"],"r":0,"e":"Ce sont les parties supérieures des systèmes digestif et respiratoire.","s":1},{"q":"Le visage se caractérise, sous la couche musculaire, par :","o":["Une région très innervée, riche en vaisseaux et ganglions","Une faible innervation, avec peu de vaisseaux et de ganglions","Une absence de vaisseaux et de ganglions superficiels","Des os épais, sans innervation particulière"],"r":0,"e":"Les os du crâne et du visage en constituent le plan profond. Les ganglions lymphatiques y sont palpables.","s":1},{"q":"Sous les muscles et aponévroses de la tête se trouvent :","o":["Les os du crâne, le cerveau et le tronc cérébral","Le seul crâne, sans le contenu encéphalique","Le seul cerveau, sans les os ni le tronc cérébral","Les seules méninges, autour du cerveau"],"r":0,"e":"Cette connaissance des plans conditionne la prudence des techniques appliquées à la tête.","s":1},{"q":"Parmi les os du membre supérieur cités figurent :","o":["L'omoplate et la clavicule","Le fémur et la rotule","Le tibia et le péroné de la jambe","Le tarse et le métatarse"],"r":0,"e":"Humérus, radius, ulna, os du carpe et phalanges complètent la liste.","s":1},{"q":"Parmi les os du membre inférieur cités figurent :","o":["Le fémur, la rotule, le tibia et le péroné","L'humérus, le radius, l'ulna et le carpe","L'omoplate, la clavicule et le sternum","La clavicule, l'humérus et les phalanges"],"r":0,"e":"Chaque massage traverse mécaniquement peau, muscle puis os ou organe. Les os du tarse et les phalanges en font aussi partie.","s":1},{"q":"La couche tégumentaire comprend :","o":["L'épiderme, le derme et l'hypoderme","L'épiderme seul, sans le derme","Le derme seul, sans l'épiderme","La peau, le muscle et le fascia"],"r":0,"e":"C'est la couche la plus superficielle des trois plans tissulaires et organiques.","s":1},{"q":"La couche musculaire est constituée de :","o":["Des muscles striés squelettiques","Des muscles lisses viscéraux","Du muscle cardiaque et des muscles lisses","Du tissu conjonctif seul"],"r":0,"e":"Elle occupe la position intermédiaire entre le tégument et le plan osseux et viscéral.","s":1},{"q":"Le principe à retenir du cadre anatomique du massage est que :","o":["Chaque massage agit aussi sur vaisseaux et nerfs","Seul le plan directement touché est concerné","L'effet reste superficiel, limité à l'épiderme","Le massage n'atteint que la peau et le muscle"],"r":0,"e":"C'est ce qui explique les effets à distance et globaux de la thérapie manuelle. Il traverse peau, muscle et os ou organe, et touche les vaisseaux et nerfs de toutes les couches.","s":1},{"q":"Le toucher est-il essentiel en physiothérapie ?","o":["Non, optionnel","Oui, c'est essentiel","Parfois","Seulement en sport"],"r":1,"e":"Le toucher est essentiel en physiothérapie — il met en contact direct avec le patient (espace personnel).","s":2},{"q":"La peau et le SNC partagent :","o":["Aucune origine commune, l'une mésodermique","La même origine embryonnaire, l'ectoderme","Le même nom latin, dérivé du grec","La même fonction de protection"],"r":1,"e":"Peau et SNC = MÊME ORIGINE EMBRYONNAIRE (ectoderme).","s":2},{"q":"3 cm de diamètre de peau contiennent environ :","o":["Une centaine de cellules et 1 seule glande","Plus de 3 millions de cellules et des glandes","Aucune structure nerveuse ni vasculaire","Uniquement des poils et leurs follicules"],"r":1,"e":"Densité exceptionnelle : >3M cellules, 100-340 glandes sudoripares, 50 terminaisons nerveuses, 90 cm vaisseaux. On y trouve aussi 100 à 340 glandes sudoripares, 50 terminaisons nerveuses et 90 cm de vaisseaux.","s":2},{"q":"La couche cornée de l'épiderme :","o":["Est la plus profonde, au contact du derme","Est superficielle, riche en kératine, première défense","Est invisible, car située sous le derme","Produit la mélanine, qui colore toute la peau en surface"],"r":1,"e":"Couche CORNÉE : superficielle, 20-30 couches, kératine, défensines = 1ère défense immunitaire. Elle compte 20 à 30 couches ; ses défensines assurent la défense immunitaire.","s":2},{"q":"La couche basale de l'épiderme :","o":["Ne se divise pas et ne contient aucun mélanocyte","Se divise activement et contient des mélanocytes","Est cornée, faite de cellules mortes aplaties","Est faite de cellules sans noyau, mortes et kératinisées"],"r":1,"e":"Couche basale = cellules mitotiquement actives (produisent les kératinocytes), contient les mélanocytes. Elle se connecte au derme.","s":2},{"q":"La couche LUCIDE est :","o":["Présente partout, sur toute la surface du corps","Présente seulement sur les paumes et les plantes","Présente seulement sur le visage et le cou","Inexistante chez l'adulte, sauf aux mains"],"r":1,"e":"Couche lucide = uniquement sur peau ÉPAISSE (paumes, plantes), fine et transparente. C'est la peau épaisse.","s":2},{"q":"Le derme PAPILLAIRE :","o":["Est profond, dense et riche en collagène","Est superficiel et lâche, sous l'épiderme","Est dépourvu de vaisseaux et de nerfs","Est dépourvu de cellules, fibreux"],"r":1,"e":"Papillaire = couche dermique SUPERFICIELLE, en contact avec l'épiderme, conjonctif LÂCHE.","s":2},{"q":"Le derme RÉTICULAIRE :","o":["Plus fin, lâche et très cellulaire","Plus épais, dense et riche en collagène","Sans collagène, fait de graisse seule","Superficiel, au contact direct de l'épiderme"],"r":1,"e":"Réticulaire = couche dermique PROFONDE, dense, riche en collagène.","s":2},{"q":"L'hypoderme est aussi appelé :","o":["Épiderme","Fascia sous-cutané","Derme superficiel","Membrane basale"],"r":1,"e":"Hypoderme = FASCIA SOUS-CUTANÉ, couche la plus profonde de la peau, contient lobules adipeux.","s":2},{"q":"L'homéostasie est :","o":["Une maladie du métabolisme cellulaire","Le maintien de l'équilibre physiologique du corps","Une opération chirurgicale de réparation tissulaire","Un récepteur sensitif de la peau"],"r":1,"e":"Homéostasie = équilibre et conservation des éléments physiologiques grâce à des mécanismes de régulation.","s":2},{"q":"Les mécanorécepteurs détectent :","o":["La température cutanée","Le toucher et la pression","La douleur seule","Le goût et l'odorat"],"r":1,"e":"Mécanorécepteurs = toucher + pression.","s":2},{"q":"Les nocicepteurs détectent :","o":["Les couleurs et les contrastes lumineux","La douleur mécanique, thermique ou chimique","Les sons graves et aigus, par vibration","Les saveurs sucrées et salées, en surface"],"r":1,"e":"Nocicepteurs = récepteurs de la DOULEUR (mécanique = pression excessive, thermique = T°C extrêmes, chimique = substances).","s":2},{"q":"Les corpuscules de PACINI détectent :","o":["La chaleur lente et prolongée","Les stimuli de haute fréquence, comme la vibration","Aucun stimulus mécanique, seulement la chaleur intense","La douleur, par des terminaisons libres"],"r":1,"e":"Pacini = HAUTE fréquence (vibration, étirement, pression). Meissner = vibration basse fréquence rapide. Ils détectent vibration, étirement et pression.","s":2},{"q":"Les corpuscules de RUFFINI :","o":["Sont, de façon officielle, les thermorécepteurs de la peau","Agissent lentement, sur l'étirement et la pression","Détectent les vibrations rapides","N'existent pas chez l'être humain adulte"],"r":1,"e":"Ruffini = action LENTE, étirement et pression PROFONDE, perception de chaleur (sans être classés thermorécepteurs). Ils perçoivent aussi la chaleur.","s":2},{"q":"Les disques de MERKEL ont pour fonction :","o":["La nociception, par des terminaisons libres","Le tact et la pression superficielle","La vibration de haute fréquence","L'étirement de la peau profonde"],"r":1,"e":"Disques de Merkel = sensibilité tactile + pression SUPERFICIELLE.","s":2},{"q":"Les corpuscules de MEISSNER :","o":["La pression profonde, dans l'hypoderme","Le toucher discriminatif et la vibration basse fréquence","La douleur, dans l'épiderme","La chaleur intense, perçue dans les couches profondes du derme"],"r":1,"e":"Meissner = toucher DISCRIMINATIF + vibration rapide basse fréquence dans les papilles dermiques. Ils siègent dans les papilles dermiques.","s":2},{"q":"Les terminaisons nerveuses LIBRES transmettent :","o":["Le toucher discriminatif fin","La douleur et la température","Les vibrations de haute fréquence","La pression profonde et lente"],"r":1,"e":"Terminaisons libres = NOCICEPTION + THERMIQUE.","s":2},{"q":"Une fonction immunitaire de la peau :","o":["Aucune, la peau n'ayant qu'un rôle mécanique","Une kératine imperméable et des antimicrobiens","Le refroidissement du sang qui circule dans le derme","La production d'insuline par le derme"],"r":1,"e":"Kératine imperméabilise + substances inhibant la croissance microbienne.","s":2},{"q":"La peau participe à la synthèse :","o":["De vitamine B12","De vitamine D","Du calcium","De l'oxygène"],"r":1,"e":"La peau participe à la synthèse de la VITAMINE D (sous l'effet du soleil).","s":2},{"q":"Le toucher dans l'enfance a une dimension :","o":["Uniquement physique, sans effet psychique","Physique, psychologique et aussi émotionnelle","Inutile, sans aucun effet durable","Dangereuse, à éviter au berceau"],"r":1,"e":"Toucher dès le berceau = physique (limites du corps), psychologique (image interne), émotionnel (sentiments).","s":2},{"q":"Les informations transmises par les récepteurs incluent :","o":["L'intensité seule, sans autre paramètre","L'intensité, la durée, la position et la direction","Aucune information utile au cerveau","La couleur et la forme de l'objet touché, en détail"],"r":1,"e":"Récepteurs transmettent : INTENSITÉ, DURÉE, POSITION, DIRECTION du stimulus.","s":2},{"q":"Le kinésithérapeute évalue, planifie, intervient par :","o":["L'olfaction et le goût","L'observation et le toucher","L'audition et la palpation osseuse seule","La radiologie et l'échographie"],"r":1,"e":"Le kiné évalue, planifie et intervient par l'OBSERVATION et le TOUCHER.","s":2},{"q":"Quelle couche dermique est plus riche en collagène ?","o":["Papillaire","Réticulaire","Aucune","Cornée"],"r":1,"e":"Réticulaire = couche profonde, plus épaisse, DENSE, riche en fibres de collagène.","s":2},{"q":"Le toucher du kiné doit être :","o":["Brutal et rapide, pour gagner du temps","Respectueux, agréable, rassurant et confiant","Hésitant, pour ne pas gêner le patient","Distrait, pour que le patient se détende"],"r":1,"e":"Le toucher doit démontrer RESPECT, INSPIRER CONFIANCE, être AGRÉABLE et RASSURANT. Il doit inspirer confiance.","s":2},{"q":"L'épiderme se renouvelle environ tous les :","o":["3 jours","7 jours","28 jours","6 mois"],"r":2,"e":"Cycle de renouvellement de l'épiderme : ≈ 28 jours (de la couche basale à la desquamation cornée).","s":2},{"q":"Les corpuscules de Pacini répondent surtout à :","o":["Au tact léger et superficiel","Aux vibrations et à la pression profonde","À l'étirement lent de la peau et du derme","À la chaleur et au froid"],"r":1,"e":"Pacini = mécanorécepteur profond (hypoderme), sensible aux vibrations et à la pression brève.","s":2},{"q":"Les corpuscules de Ruffini détectent :","o":["La douleur thermique","L'étirement cutané continu","Vibrations rapides","Le chatouillement"],"r":1,"e":"Ruffini = étirement cutané et adaptation lente (info posturale).","s":2},{"q":"Les terminaisons libres dans l'épiderme codent :","o":["La pression seule, sans autre modalité","La douleur, le chaud et le froid","Les vibrations, rapides et lentes, du derme","La position articulaire, au repos"],"r":1,"e":"Terminaisons nerveuses libres = douleur (nociception), thermoception (chaud/froid).","s":2},{"q":"La discrimination tactile (deux points) est meilleure :","o":["Au dos, entre les omoplates","Sur la pulpe des doigts et la langue","Sur la face antérieure de la cuisse","Sur le mollet et le dos du pied, en bas"],"r":1,"e":"Densité maximale de récepteurs = pulpe digitale + langue → discrimination très fine (1-2 mm).","s":2},{"q":"La sudation eccrine sert principalement à :","o":["L'odeur corporelle, sous les aisselles","La thermorégulation, par évaporation","La protection mécanique de la peau","La pigmentation de la peau exposée au soleil"],"r":1,"e":"Glandes eccrines = sueur aqueuse, étalée sur tout le corps, rôle de thermorégulation par évaporation.","s":2},{"q":"Les glandes sébacées produisent :","o":["De la sueur, qui rafraîchit la peau","Du sébum, qui lubrifie la peau","Du mucus, qui humidifie la peau","Du collagène, qui renforce la peau"],"r":1,"e":"Glandes sébacées → sébum (mélange de lipides) qui imperméabilise et assouplit la peau. Le sébum lubrifie aussi les poils.","s":2},{"q":"Le toucher affectif (caresse lente) est véhiculé par :","o":["Des fibres A bêta, rapides et myélinisées","Des fibres C tactiles, à conduction lente","Des fibres A alpha, motrices","Des fibres A delta, thermiques"],"r":1,"e":"CT-afferents : fibres C non-myélinisées spécialisées dans le toucher affectif/social agréable.","s":2},{"q":"L'hyposensibilité cutanée :","o":["Augmente le risque de blessures non perçues","Protège la peau, qui devient moins sensible aux plaies","N'a aucune conséquence sur la peau","Améliore la cicatrisation des plaies"],"r":0,"e":"Baisse de sensibilité = absence d'alarme → escarres, brûlures, plaies non détectées (diabète, neuropathies). Escarres et brûlures passent alors inaperçues.","s":2},{"q":"Pour un toucher thérapeutique efficace, le kiné doit :","o":["Aller toujours très vite, pour ne pas lasser","Adapter pression, rythme et intention à l'objectif","Toujours appuyer fort, quelle que soit la zone traitée","Ne pas regarder le patient pendant la séance"],"r":1,"e":"Toucher de qualité = pression adaptée + rythme cohérent + intention claire + communication verbale et non-verbale.","s":2},{"q":"En touchant, le kinésithérapeute doit savoir :","o":["Comment toucher, ce qu'il touche et ses effets","Comment toucher, sans se soucier des effets","Ce qu'il touche, sans la manière","La durée du contact, et seulement elle"],"r":0,"e":"Il entre dans l'espace personnel du patient : le toucher doit démontrer respect, inspirer confiance et être agréable et rassurant.","s":2},{"q":"La peau et le système nerveux central partagent :","o":["La même origine embryonnaire, l'ectoderme","Une origine commune, le mésoderme de l'embryon","Une origine commune, l'endoderme","Aucune origine commune, chacune distincte"],"r":0,"e":"Toucher la peau revient donc à toucher l'extension du cerveau.","s":2},{"q":"Trois centimètres de diamètre de peau contiennent :","o":["Plus de 3 millions de cellules et 100 à 340 glandes","Environ 1 million de cellules et 10 glandes","Environ 10 terminaisons nerveuses et 1 glande","Environ 10 cm de vaisseaux et 2 terminaisons nerveuses"],"r":0,"e":"La peau est le plus grand organe du corps et permet l'homéostasie entre milieu interne et externe. On y compte aussi 50 terminaisons nerveuses et 90 cm de vaisseaux.","s":2},{"q":"La couche cornée comprend :","o":["20 à 30 couches de cellules anucléées riches en kératine","3 à 5 couches de cellules granuleuses à kératohyaline","8 à 10 couches de cellules polyédriques et dendritiques","2 à 3 couches de cellules fines et transparentes"],"r":0,"e":"Elle constitue la première ligne de défense immunitaire, par les défensines. Ces cellules sont squameuses.","s":2},{"q":"La couche lucide comprend :","o":["2 à 3 couches fines, sur les paumes et les plantes","20 à 30 couches, sur toute la surface du corps","8 à 10 couches, sur le visage et le cou","5 couches épaisses, sur le dos et les fesses du sujet"],"r":0,"e":"Elle constitue un mécanisme de défense supplémentaire dans la peau épaisse. Elles sont transparentes.","s":2},{"q":"La couche granuleuse assure :","o":["La cohésion cellulaire et une barrière imperméable","La production de kératinocytes, par des mitoses actives","La défense immunitaire, par les défensines","La connexion au derme, par les hémidesmosomes"],"r":0,"e":"Elle comprend 3 à 5 couches, riches en kératohyaline et granules lamellaires. La barrière vient des phospholipides.","s":2},{"q":"La couche épineuse comprend :","o":["8 à 10 couches de cellules polyédriques et dendritiques","2 à 3 couches de cellules fines et transparentes du derme","20 couches de cellules anucléées et kératinisées","Une seule couche de cellules cubiques basales"],"r":0,"e":"Elle assure la production de kératine et une fonction immunologique.","s":2},{"q":"La couche basale se caractérise par :","o":["Des cellules en mitose active et des mélanocytes","Des cellules anucléées, mortes et kératinisées","Des cellules squameuses, aplaties et superficielles","L'absence de mitose et de mélanocytes, sur une seule couche"],"r":0,"e":"Elle produit les kératinocytes et assure la connexion au derme par les hémidesmosomes. Les cellules sont cubiques ou cylindriques.","s":2},{"q":"Le derme est relié à l'épiderme par :","o":["La membrane basale","Les hémidesmosomes seuls","Le tissu conjonctif lâche","Les follicules pileux"],"r":0,"e":"Il comprend glandes sudoripares, follicules pileux, muscles, neurones sensoriels et vaisseaux.","s":2},{"q":"Le derme réticulaire se caractérise par :","o":["Un tissu dense riche en collagène, épais et peu cellulaire","Un tissu conjonctif lâche, fin et très cellulaire","Une grande finesse, avec un tissu lâche situé sous l'épiderme","Une richesse cellulaire, avec peu de fibres de collagène"],"r":0,"e":"Le derme papillaire, superficiel, est plus fin et fait de tissu conjonctif lâche.","s":2},{"q":"L'hypoderme, ou fascia sous-cutané, contient :","o":["Des lobules adipeux, des neurones et des vaisseaux","Uniquement de la graisse, sans vaisseau ni nerf","Uniquement des vaisseaux, sans graisse ni nerf sensitif","Des glandes sudoripares très abondantes"],"r":0,"e":"C'est la couche la plus profonde de la peau. Les neurones sont sensoriels ; on y trouve de rares follicules pileux.","s":2},{"q":"La fonction immunitaire de la peau repose sur :","o":["La kératine imperméable et des substances antimicrobiennes","La seule kératine, sans autre substance","La seule thermorégulation par la sueur","Les seuls mélanocytes, qui détruisent les microbes de surface"],"r":0,"e":"Protection, thermorégulation et excrétion des déchets métaboliques complètent ses fonctions.","s":2},{"q":"La protection cutanée s'exerce contre des agents :","o":["Physiques, chimiques, mécaniques et biologiques","Physiques seulement, comme le froid","Chimiques seulement, comme les acides","Biologiques seulement, comme les bactéries et les virus"],"r":0,"e":"C'est la première des fonctions de la peau citées.","s":2},{"q":"La densité fonctionnelle de la peau illustre :","o":["Qu'elle est le plus grand organe et sert l'homéostasie","Sa grande fragilité face à toutes les agressions extérieures","Son épaisseur, la plus forte de tous les organes","Sa vascularisation faible, par rapport au muscle"],"r":0,"e":"Sa richesse en terminaisons nerveuses fonde l'efficacité du toucher thérapeutique. Elle assure l'homéostasie entre milieu interne et externe.","s":2},{"q":"La thérapie manuelle agit :","o":["Sur le seul tissu local, sans effet à distance","Localement, mais aussi sur le plan nerveux et psychique","Uniquement sur le moral, sans effet sur les tissus","Sans aucun effet mesurable, ni local ni général"],"r":1,"e":"La thérapie manuelle a des effets LOCAUX + NEUROLOGIQUES + PHYSIOLOGIQUES + PSYCHOLOGIQUES. Il s'y ajoute un effet physiologique.","s":3},{"q":"Au niveau neurologique, le toucher peut :","o":["Augmenter la douleur, puis la contracture du patient","Stimuler, désensibiliser et traiter la douleur","N'avoir aucun effet sur le système nerveux","Provoquer des lésions nerveuses, surtout périphériques"],"r":1,"e":"Le toucher : stimule/désensibilise, traite la douleur, rééduque posture/mouvement, fournit info sensorielle, intègre schéma corporel. Il rééduque aussi la posture et le mouvement.","s":3},{"q":"Les émotions sont associées à des :","o":["Aucune réponse corporelle, ni tonique ni douloureuse","Des réponses somatiques, comme le tonus ou la douleur","Des réponses purement mentales","Des mouvements involontaires, extrêmes et soudains"],"r":1,"e":"Les émotions provoquent des RÉPONSES SOMATIQUES : modifications du tonus musculaire, variations de la tolérance à la douleur. Le tonus musculaire et la tolérance à la douleur varient.","s":3},{"q":"L'étirement (en thérapie manuelle) modifie le tissu en :","o":["En le compactant, par expulsion des fluides","En le rendant plus étroit et dense, par le collagène","En augmentant le flux des fluides, sans remodelage","En le détruisant, par rupture des fibres"],"r":1,"e":"Étirement = remodelage par agrégation du collagène dans le sens des forces → tissu plus étroit et plus dense (peu d'effet sur les fluides). Le collagène s'agrège dans le sens des forces.","s":3},{"q":"La compression a pour effet principal :","o":["Étirer les tissus dans le sens des fibres","Rapprocher les fibres et faciliter le flux des fluides","Couper l'apport sanguin pour mieux détendre le muscle traité","Détendre le muscle sans aucun effet sur les fluides"],"r":1,"e":"Compression = raccourcissement fibres + ↑ pression interne → FACILITE la circulation des fluides. La pression interne augmente.","s":3},{"q":"La rotation s'applique surtout aux :","o":["Muscles superficiels","Structures articulaires","Os","Peau"],"r":1,"e":"La rotation combine compression + étirement progressif → généralement appliquée aux structures ARTICULAIRES.","s":3},{"q":"La viscoplasticité est :","o":["Une technique de massage parmi d'autres","Une caractéristique de tous les tissus mous","Une notion inutile en thérapie manuelle","Un muscle profond de la paroi abdominale, très tonique"],"r":1,"e":"Viscoplasticité = caractéristique de TOUS les tissus mous. Dépend de la synthèse protéique et du nombre de liaisons transversales (densité). Elle dépend de la synthèse protéique et des liaisons transversales.","s":3},{"q":"Une force IDENTIQUE sur une zone PETITE produit :","o":["Une pression moindre, car la force se disperse","Une pression plus forte, par concentration","La même pression que sur une grande zone","Aucun effet sur les tissus sous-jacents"],"r":1,"e":"Force concentrée sur petite zone = pression plus IMPORTANTE. Force dispersée sur grande zone = pression MOINDRE.","s":3},{"q":"Pourquoi les vertèbres lombaires sont-elles plus grandes que les cervicales ?","o":["Par hasard, sans lien avec leur fonction","Pour porter plus de poids, par adaptation","Pour l'esthétique de la silhouette, en bas du dos","Pour permettre plus de mouvement"],"r":1,"e":"Les structures s'adaptent aux CHARGES qu'elles supportent — les lombaires sont plus larges pour supporter plus de poids.","s":3},{"q":"La thérapie manuelle modifie les propriétés tissulaires :","o":["Aucune propriété, l'effet restant subjectif","La flexibilité, la viscoplasticité, la force et les fluides","La couleur et la texture de la peau, en surface et en profondeur","La forme uniquement, sans effet sur la fonction"],"r":1,"e":"Modifications : flexibilité, viscoplasticité, force + structurelles/physiologiques + dynamique des fluides → réparation tissulaire. Les propriétés structurelles et physiologiques changent aussi.","s":3},{"q":"L'étirement a-t-il un grand effet sur le flux des fluides ?","o":["Oui, c'est son effet le plus important","Non, il influence peu le flux des fluides","Oui, c'est même son seul effet connu","On ne le sait pas encore"],"r":1,"e":"Étirement = remodelage du collagène mais PEU d'effet sur le flux des fluides. C'est la compression qui le facilite.","s":3},{"q":"La flexibilité est :","o":["Un seul exercice, répété sur un muscle précis","Un travail global sur la longueur des fibres","Une caractéristique propre aux tissus mous","Une douleur ressentie en fin d'étirement"],"r":1,"e":"FLEXIBILITÉ = travail global. ÉTIREMENT = technique spécifique. VISCOPLASTICITÉ = caractéristique tissulaire. Elle inclut différentes techniques.","s":3},{"q":"L'étirement est une technique :","o":["Globale, sur l'ensemble des groupes musculaires","Spécifique, sur un muscle et avec un timing","Aléatoire, selon le ressenti du moment","Sans objectif clinique défini"],"r":1,"e":"L'étirement est une technique CIBLÉE sur un groupe/muscle spécifique, avec timing précis.","s":3},{"q":"Les mains du kiné influencent des processus neurologiques :","o":["Uniquement locaux, sous la main","Locaux, à distance ou globaux","Aucun, l'effet étant mécanique","Seulement vasculaires, par le flux sanguin"],"r":1,"e":"Les mains peuvent influencer des processus LOCAUX, À DISTANCE ou GLOBAUX (intégration corporelle).","s":3},{"q":"Le toucher fournit des informations :","o":["Visuelles, transmises par la peau","Sensorielles, utiles au schéma corporel","Auditives, transmises par vibration","Olfactives, transmises par la sueur"],"r":1,"e":"Le toucher fournit des informations SENSORIELLES, contribue à la proprioception et à l'intégration du SCHÉMA CORPOREL. Elles contribuent à la proprioception.","s":3},{"q":"La compression facilite :","o":["L'étirement du collagène","La circulation des fluides","La sortie du sang","Rien"],"r":1,"e":"Compression = raccourcissement + ↑ pression interne tissulaire → FACILITE LA CIRCULATION DES FLUIDES.","s":3},{"q":"La torsion est un type de :","o":["Une modification biomécanique combinée","Une absence totale de force sur le tissu","Une force appliquée en surface seule","Un étirement pur, dans un seul plan de l'espace"],"r":0,"e":"La torsion = mouvement combiné, souvent associé à la compression.","s":3},{"q":"En cas de lésion, la thérapie manuelle aide à :","o":["Aggraver la lésion pour relancer l'inflammation","Rétablir les propriétés structurelles et fonctionnelles","Bloquer toute réparation, pour bien protéger la zone lésée","Inhiber la cicatrisation, pour éviter l'adhérence"],"r":1,"e":"Objectif clinique = rétablir les propriétés STRUCTURELLES et FONCTIONNELLES des tissus pour la réparation.","s":3},{"q":"Quelle technique combine compression et étirement progressif ?","o":["Étirement seul","Rotation","Friction","Tapotement"],"r":1,"e":"La ROTATION combine compression de la structure + étirement progressif dans l'axe de rotation.","s":3},{"q":"Les forces appliquées se propagent :","o":["De façon aléatoire, dans toutes les directions","À travers les couches, dans le sens de la force","Dans le sens opposé à la force appliquée, vers la surface","Sans se propager, en restant sous la main"],"r":1,"e":"Les forces se propagent à travers les couches DANS LE SENS de l'application de la force.","s":3},{"q":"Les effets antalgiques de la thérapie manuelle passent par :","o":["La théorie du portillon et la libération d'endorphines","La paralysie des nerfs sensitifs de la zone traitée","Le saignement local, qui évacue la douleur des tissus","La déshydratation des tissus enflammés"],"r":0,"e":"Antalgie par gate control (stimulation Aβ qui bloque les nociceptifs C/Aδ) + libération d'opioïdes endogènes.","s":3},{"q":"Sur le système circulatoire, le massage favorise :","o":["Une vasoconstriction généralisée du réseau cutané","Une vasodilatation locale et le retour veino-lymphatique","Une chute brutale de la pression artérielle","Une hémorragie locale, par rupture des capillaires du derme"],"r":1,"e":"Massage = vasodilatation cutanée locale + drainage veineux et lymphatique.","s":3},{"q":"Sur le tonus musculaire, un massage profond et lent tend à :","o":["Augmenter le tonus, par effet stimulant","Diminuer le tonus, par effet relaxant","Provoquer des crampes, par fatigue musculaire","N'avoir aucun effet sur le tonus"],"r":1,"e":"Massage profond/lent → effet inhibiteur sur les motoneurones, ↓ tonus, ↑ extensibilité.","s":3},{"q":"L'effet psychologique principal du toucher thérapeutique est :","o":["L'agressivité, par la gêne du contact","La détente, moins d'anxiété et plus de bien-être","La confusion mentale, par excès de sensations reçues","Aucun effet, le toucher restant mécanique"],"r":1,"e":"Toucher de qualité → activation parasympathique, libération d'ocytocine, ↓ anxiété, sentiment de soin.","s":3},{"q":"Une contre-indication majeure du massage est :","o":["Un patient au repos, allongé depuis peu de temps sur la table","Une thrombose veineuse profonde ou une phlébite","Une fatigue passagère, après une journée","Une cicatrice ancienne, bien consolidée"],"r":1,"e":"CI absolues : TVP/phlébite (risque d'embolie), infections actives, plaies ouvertes, tumeurs malignes locales, fractures non consolidées. Le risque est l'embolie.","s":3},{"q":"Avant tout massage, le kiné doit :","o":["Sauter l'anamnèse, pour gagner du temps","Interroger, évaluer la zone et chercher les risques","Masser immédiatement, sans examen préalable","Donner un médicament antalgique, puis masser la zone"],"r":1,"e":"Bilan préalable = sécurité + adaptation : anamnèse, observation, palpation, recherche de CI. On recherche notamment les contre-indications.","s":3},{"q":"La position du kiné pour masser doit :","o":["Forcer le dos, pour appuyer plus fort","Être ergonomique, dos droit, poids du corps","Être assis au sol, à côté de la table","Tenir sur une jambe, pour plus de mobilité"],"r":1,"e":"Ergonomie kiné = prévention TMS : appui solide, dos neutre, utilisation du poids corporel plutôt que la force des bras. Les pieds sont écartés.","s":3},{"q":"La durée standard d'une séance de massage thérapeutique est généralement de :","o":["Environ 3 minutes, pour une zone limitée","Environ 20 à 30 minutes, selon la zone","Environ 3 heures, pour tout le corps","Environ 2 jours, en plusieurs séances"],"r":1,"e":"Séances typiques : 20-30 min ciblées sur une région. Plus long = risque de fatigue tissulaire et du kiné.","s":3},{"q":"Le rythme du massage doit être :","o":["Aléatoire, sans lien avec l'objectif","Régulier et adapté à l'objectif recherché","Toujours très rapide, pour stimuler","Toujours saccadé, pour surprendre"],"r":1,"e":"Lent et continu → relaxation, parasympathique. Rythmé/dynamique → stimulation, ↑ vigilance et trophicité. Lent pour relaxer, plus rapide pour stimuler.","s":3},{"q":"L'évaluation après séance comprend :","o":["Rien, la séance se suffisant à elle-même","Le ressenti, la mobilité et la douleur du patient","Un examen sanguin, pour mesurer l'inflammation générale","Une biopsie des tissus massés"],"r":1,"e":"Réévaluation post-séance = subjectif (ressenti, EVA) + objectif (mobilité, palpation) pour ajuster les séances suivantes. La douleur se note sur l'EVA.","s":3},{"q":"La thérapie manuelle, bien que liée au contact manuel local, a aussi des effets :","o":["Locaux, neurologiques, physiologiques et psychologiques","Uniquement tissulaires, sans effet à distance","Uniquement locaux, limités à la zone touchée par la main","Uniquement mécaniques, sans effet nerveux"],"r":0,"e":"C'est ce qui fonde son modèle physiologique.","s":3},{"q":"Parmi les effets de l'organisation neurologique, le cours cite :","o":["La proprioception et l'intégration du schéma corporel","La seule antalgie, par la théorie du portillon","La seule stimulation sensorielle de la peau traitée","Le seul traitement postural du patient"],"r":0,"e":"S'y ajoutent l'orientation sur les lésions nerveuses centrales, les déficits post-lésionnels, la rééducation de la posture et du mouvement et la désensibilisation.","s":3},{"q":"L'organisation psychophysiologique rappelle que :","o":["Les émotions s'accompagnent de réponses somatiques","Les émotions sont indépendantes du corps","Le toucher n'a aucun effet sur les émotions","La douleur reste un phénomène purement physique"],"r":0,"e":"Dans la plupart des cas cliniques, la stimulation par le toucher réduit ou annule les symptômes. Le tonus et la tolérance à la douleur en sont des exemples.","s":3},{"q":"L'organisation tissulaire concerne :","o":["Peau, muscles, tendons, capsule, ligaments et vaisseaux","La seule peau, avec l'épiderme et le derme","Les seuls muscles, avec leurs tendons et aponévroses","Les seules articulations, avec leurs capsules"],"r":0,"e":"Les forces mécaniques y modifient propriétés physiques, structure et dynamique des fluides. Tous les tissus des différentes couches sont concernés, systèmes vasculaire et lymphatique compris.","s":3},{"q":"Les transformations locales de la dynamique des fluides concernent :","o":["Le sang, la lymphe et les liquides des tissus","Le seul sang, dans les capillaires","La seule lymphe, dans les vaisseaux","Le seul liquide synovial, dans les articulations voisines"],"r":0,"e":"Elles participent aux processus de réparation tissulaire post-lésionnelle. Les liquides extracellulaires et synoviaux sont concernés.","s":3},{"q":"La flexibilité se définit comme :","o":["Un travail global sur la longueur des fibres musculaires","Une technique spécifique, ciblée sur un seul muscle","Une caractéristique des tissus mous, liée à leur collagène","Une propriété du collagène, mesurée en laboratoire"],"r":0,"e":"L'étirement est une technique spécifique, avec timing précis, qui travaille la flexibilité. Elle inclut diverses techniques.","s":3},{"q":"La viscoplasticité :","o":["Est commune à tous les tissus mous, selon leur densité","Concerne les seuls muscles striés, avec leurs tendons","Est une technique de massage profond","Est propre au tendon et à l'aponévrose"],"r":0,"e":"Elle définit la densité tissulaire. La densité dépend de la synthèse protéique et des liaisons transversales.","s":3},{"q":"Parmi les types de contraintes biomécaniques, le cours cite :","o":["Absence de charge, tension, compression et torsion","La seule compression, appliquée perpendiculairement aux fibres","La seule traction, appliquée dans l'axe des fibres","La seule torsion, appliquée autour de l'axe du membre"],"r":0,"e":"Chacune produit des modifications tissulaires spécifiques. S'y ajoutent la tension latérale, la contrainte bidirectionnelle et la combinaison compression-torsion.","s":3},{"q":"L'objectif clinique des techniques manuelles est :","o":["Rétablir la structure et la fonction des tissus","Soulager la douleur, sans viser le tissu lui-même","Détendre le patient, sans effet sur les tissus","Augmenter la force du muscle traité"],"r":0,"e":"Les techniques se classent selon les modifications qu'elles provoquent.","s":3},{"q":"L'étirement, comme modification produite par les techniques, exerce une force :","o":["Dans le sens longitudinal","Dans le sens transversal","En compression","En rotation"],"r":0,"e":"Il est utilisé pour étirer des tissus raccourcis.","s":3},{"q":"Le remodelage des forces de tension lors de l'étirement entraîne :","o":["Une agrégation du collagène, qui rend le tissu étroit et dense","Une dispersion du collagène, qui rend le tissu large et lâche","Un relâchement du tissu, qui devient plus souple et plus épais","Un épaississement désorganisé, sans orientation des fibres"],"r":0,"e":"L'étirement a par ailleurs peu d'influence sur le flux des fluides. L'agrégation se fait dans le sens des forces.","s":3},{"q":"La compression, parmi les modifications produites :","o":["Rapproche les fibres, élève la pression et aide les fluides","Allonge les fibres, baisse la pression et freine les fluides","Diminue la pression interne, sans effet sur les fibres","Bloque la circulation des fluides dans le tissu"],"r":0,"e":"C'est ce qui la distingue de l'étirement, peu actif sur les fluides. Il s'agit de la pression interne tissulaire.","s":3},{"q":"La rotation est décrite comme produisant :","o":["Un effet mécanique complexe","Un effet purement longitudinal","Un effet purement compressif","Aucun effet"],"r":0,"e":"Elle figure parmi les cinq grandes modifications produites par les techniques manuelles.","s":3},{"q":"Les forces mécaniques modifient les propriétés physiques et mécaniques suivantes :","o":["Flexibilité, viscoplasticité et force","Température, pH et osmolarité","Densité osseuse, calcium et phosphore","Conduction nerveuse, vitesse et seuil d'excitation"],"r":0,"e":"Elles entraînent aussi des modifications structurelles et physiologiques.","s":3},{"q":"Les mains du kinésithérapeute, bien que placées sur une zone précise, influencent des processus neurologiques :","o":["Locaux, à distance ou bien globaux","Locaux, et jamais à distance","Globaux, et jamais locaux","Réflexes, et jamais conscients"],"r":0,"e":"C'est le fondement de l'organisation neurologique de la thérapie manuelle.","s":3},{"q":"Parmi les applications neurologiques de la thérapie manuelle, le cours cite :","o":["Le traitement de la douleur et la stimulation sensorielle","La seule antalgie, par l'effet placebo du simple contact manuel","La seule stimulation, sans désensibilisation","La seule rééducation motrice, sans antalgie"],"r":0,"e":"Elle fournit aussi des informations sensorielles par le toucher. La désensibilisation en fait aussi partie.","s":3},{"q":"L'étirement se distingue de la flexibilité par :","o":["Son caractère spécifique, ciblé, avec un timing précis","Son caractère global, sur tous les muscles","Son absence de technique, au profit du ressenti","Sa durée, toujours supérieure à dix minutes par muscle"],"r":0,"e":"L'étirement est donc un outil au service de la flexibilité.","s":3},{"q":"La densité tissulaire est définie par :","o":["La synthèse protéique et le nombre de liaisons transversales","La seule teneur en eau du tissu, mesurée au repos et à l'effort","La seule vascularisation du tissu concerné","L'épaisseur du tissu, mesurée à l'échographie"],"r":0,"e":"Ces deux paramètres déterminent la viscoplasticité, caractéristique de tous les tissus mous.","s":3},{"q":"L'état neutre, parmi les contraintes biomécaniques, correspond à :","o":["L'absence de charge","Une compression légère","Une tension minimale","Une torsion nulle avec compression"],"r":0,"e":"C'est le point de départ à partir duquel s'appliquent les autres contraintes.","s":3},{"q":"Le toucher, dans l'organisation psychophysiologique, provoque :","o":["Des stimuli puissants","Des effets négligeables","Des effets uniquement locaux","Des effets uniquement mécaniques"],"r":0,"e":"C'est ce qui explique la réduction ou l'annulation des symptômes dans la plupart des cas cliniques.","s":3},{"q":"Le massage est utilisé depuis :","o":["Le XIXᵉ siècle, en Suède","L'an 2698 avant J.-C., en Chine","L'an 1900, avec les premières écoles de kinésithérapie","L'an 1950, aux États-Unis"],"r":1,"e":"Mention écrite la plus ancienne en Chine en 2698 av. J.-C.","s":4},{"q":"Pourquoi les termes effleurage, pétrissage, tapotement sont-ils français ?","o":["Ils ont été inventés en France, au XVIIIᵉ siècle","Des missionnaires français les ont rapportés de Chine","Ils proviennent d'une erreur de traduction de l'anglais du XIXᵉ","Ils ont été choisis au hasard par les écoles"],"r":1,"e":"Beck (1999) : réintroduits en Europe au XIXe par les missionnaires FRANÇAIS revenus de Chine → terminologie française. C'était au XIXᵉ siècle, lors de leur retour en Europe.","s":4},{"q":"Qui a prouvé scientifiquement les effets du massage dans les années 80-90 ?","o":["Hippocrate et ses disciples","Tiffany Field et son équipe","Wilder Penfield et son équipe","Antonio Damásio et ses élèves"],"r":1,"e":"Tiffany Field (années 80-90) = études prouvant les effets du massage.","s":4},{"q":"Les principaux promoteurs européens du massage moderne sont :","o":["Les Français, avec les missionnaires","Les Scandinaves, au Danemark et en Suède","Les Italiens, autour de Rome","Les Espagnols, autour de Madrid"],"r":1,"e":"Principaux promoteurs européens = SCANDINAVES.","s":4},{"q":"La direction recommandée du massage est :","o":["Centrifuge, du proximal vers le distal","Centripète, du distal vers le proximal","Aléatoire, selon les préférences du kiné","Latérale, de dedans en dehors"],"r":1,"e":"Direction CENTRIPÈTE (distal → proximal) pour favoriser le RETOUR VEINEUX. Elle favorise le retour veineux.","s":4},{"q":"La durée d'une mobilisation tissulaire LOCALE thérapeutique est :","o":["1-2 min","5-15 min","30-60 min","2 heures"],"r":1,"e":"Mobilisation locale thérapeutique = 5 à 15 minutes.","s":4},{"q":"La durée d'une mobilisation de RELAXATION est :","o":["De 1 à 2 minutes seulement","De 5 à 10 minutes seulement","De 30 à 45, voire 60 minutes","De 2 à 3 heures, sans pause"],"r":2,"e":"Mobilisation de relaxation = 30 à 45/60 minutes.","s":4},{"q":"La pression à appliquer est :","o":["Maximale, pour un effet plus profond","Modérée, selon la littérature","Nulle, pour un effet relaxant","Très faible, dans tous les cas"],"r":1,"e":"La littérature recommande une PRESSION MODÉRÉE pour produire des effets.","s":4},{"q":"Concernant le kinésithérapeute, il doit :","o":["Avoir les ongles longs, pour mieux masser en profondeur","Avoir les mains soignées, les ongles courts et propres","Porter ses bagues, pour ne pas les perdre","Avoir les mains froides, pour tonifier"],"r":1,"e":"Mains soignées, ongles PROPRES et COUPÉS, hygiène irréprochable.","s":4},{"q":"Les 3 types d'effets physiologiques du massage sont :","o":["Mécaniques, sans aucun autre effet","Mécaniques, réflexes et psychologiques","Magiques, énergétiques et spirituels","Physiques, chimiques et thermiques, uniquement"],"r":1,"e":"3 effets : MÉCANIQUES, RÉFLEXES/NEURAUX, PSYCHOLOGIQUES.","s":4},{"q":"Le massage selon Holey & Cook (1999) est :","o":["Une chirurgie des tissus mous, sous anesthésie","Une manipulation des tissus mous par un professionnel","Un sport de contact, pratiqué en compétition","Une injection de produits dans les tissus mous du patient"],"r":1,"e":"Holey & Cook (1999) : manipulation des tissus mous par professionnel qualifié dans cadre holistique. Elle s'inscrit dans une intervention holistique.","s":4},{"q":"Le massage peut s'utiliser :","o":["Seul, jamais associé à une autre technique","Seul ou associé à d'autres techniques du plan","Jamais seul, ni avec d'autres techniques, sans prescription","Sans plan d'intervention, au gré des séances"],"r":1,"e":"Andrade & Clifford (2008) : seul OU en association avec d'autres techniques du plan d'intervention.","s":4},{"q":"Quel cadre légal définit l'acte du kinésithérapeute ?","o":["Le décret-loi n° 564/99, article 6","La loi du sport de 1998, article 2","Le Code civil, article 1240","Aucun texte légal spécifique"],"r":0,"e":"Décret-loi 564/99 + Article 6 — Acte du kinésithérapeute.","s":4},{"q":"L'acte du kinésithérapeute concerne :","o":["Uniquement les os et les articulations","Le système locomoteur et la fonctionnalité de la personne","Uniquement la peau et les tissus sous-cutanés du patient traité","Uniquement le cerveau et la moelle épinière"],"r":1,"e":"Système locomoteur + fonctionnalité, dimensions physique, mentale, sociale. Dans ses dimensions physique, mentale et sociale.","s":4},{"q":"Le processus de physiothérapie comprend :","o":["Une seule étape, l'intervention","Examen, diagnostic, plan, intervention et évaluation","Aucune étape définie, selon le cas","La seule prescription du médecin, puis l'exécution"],"r":1,"e":"6 étapes : examen → diagnostic → pronostic/plan → intervention → évaluation résultats → conclusion. Le pronostic et la conclusion complètent les six étapes.","s":4},{"q":"La position du kiné doit être :","o":["Inconfortable, pour rester vigilant","Confortable, rythme continu, mains ajustées","Tendue, pour mieux appuyer sur les tissus","Variable, sans règle particulière"],"r":1,"e":"Position CONFORTABLE, technique correcte, rythme CONTINU, mains AJUSTÉES à la surface.","s":4},{"q":"L'huile/crème sert à :","o":["Hydrater la peau, sans autre rôle","Faire glisser les mains sur la peau","Désinfecter la peau","Refroidir la peau après l'effort"],"r":1,"e":"Huile/crème = favorise le glissement, choisie selon objectifs et type de peau. Elle se choisit selon les objectifs et le type de peau.","s":4},{"q":"La fréquence d'une mobilisation tissulaire est déterminée par :","o":["Le hasard des disponibilités","Le raisonnement clinique du kiné","La seule demande du patient","Aucun critère particulier"],"r":1,"e":"Fréquence = nombre de répétitions sur une période donnée, déterminée par le RAISONNEMENT CLINIQUE.","s":4},{"q":"Le kinésithérapeute peut intervenir dans :","o":["Aucun domaine spécialisé de la santé","Tous les domaines de la santé, sans limite","Le seul domaine du sport de haut niveau","La seule pédiatrie, chez les nourrissons"],"r":1,"e":"Tous les domaines : musculo-squelettique, neuro, cardio, respi, oncologie, tégumentaire, mental, femmes, bébés, sportifs, etc. Musculo-squelettique, neurologie, cardiologie, respiratoire, santé mentale, etc.","s":4},{"q":"L'acte du kinésithérapeute peut être réalisé :","o":["Uniquement en présentiel, au cabinet","En présentiel ou en télésanté","Sans patient, sur simple dossier médical transmis","Par téléphone uniquement, sans examen"],"r":1,"e":"En présentiel mais aussi en télésanté.","s":4},{"q":"Le bilan kiné comporte 3 phases principales :","o":["Anamnèse, examen physique et plan de traitement","Diagnostic médical, imagerie et prescription","Prescription, exécution et facturation de la séance","Chirurgie, rééducation et suivi à domicile"],"r":0,"e":"3 phases : anamnèse (subjectif) → examen physique (objectif) → bilan-diagnostic kiné et plan d'intervention. Le bilan-diagnostic kiné précède le plan d'intervention.","s":4},{"q":"L'anamnèse comprend :","o":["La seule douleur, cotée sur une échelle","Les antécédents, l'histoire, la douleur et la gêne","Le seul poids, avec la taille et l'indice de masse","Aucune information, l'examen suffisant"],"r":1,"e":"Anamnèse complète : ATCD, début/évolution, intensité douloureuse, contexte, retentissement quotidien. La douleur se cote sur l'EVA ; la gêne est le retentissement fonctionnel.","s":4},{"q":"Le consentement éclairé du patient avant un massage est :","o":["Facultatif, si le patient est adulte","Obligatoire, après une explication claire","Verbal uniquement, sans explication","Réservé aux mineurs, par leurs parents ou tuteurs"],"r":1,"e":"Le patient doit recevoir une information claire (technique, bénéfices, risques, alternatives) et donner son accord.","s":4},{"q":"Le secret professionnel s'applique :","o":["Seulement aux échanges avec les collègues du même cabinet","À toutes les informations recueillies sur le patient","Seulement aux patients mineurs et à leurs parents","Aux salaires et aux honoraires du kiné"],"r":1,"e":"Secret professionnel = obligation légale et déontologique pour TOUTES les informations sur le patient.","s":4},{"q":"L'hygiène avant chaque séance :","o":["N'est pas obligatoire en massage","Mains lavées, ongles courts, table et linge propres","Seulement si le patient la demande","Une fois par jour, en début de matinée, avant le premier patient"],"r":1,"e":"Hygiène = base de la sécurité patient : mains lavées entre chaque patient, ongles courts, matériel propre.","s":4},{"q":"L'huile de massage sert à :","o":["Augmenter la friction, pour chauffer la peau","Réduire la friction et faciliter le glissement","Soigner la peau, comme une crème médicamenteuse","Aromatiser la salle, par diffusion"],"r":1,"e":"Huile = lubrifiant qui réduit la friction cutanée et permet des manœuvres prolongées sans irritation. Elle permet des manœuvres prolongées, comme l'effleurage ou le pétrissage.","s":4},{"q":"L'objectif principal d'un massage en récupération sportive est :","o":["Augmenter la fatigue, pour habituer le muscle","Favoriser la récupération, par le drainage et la détente","Augmenter la performance immédiate, avant l'effort suivant","Échauffer le muscle avant la compétition"],"r":1,"e":"Massage de récup post-effort : drainage des métabolites, ↓ tension musculaire, ↓ DOMS, détente. Il diminue la tension et les douleurs.","s":4},{"q":"Un massage pré-compétition est plutôt :","o":["Profond et long, pour relâcher","Court, dynamique et stimulant","Sédatif, pour endormir le muscle","Inutile, car il fatigue le sportif avant l'effort"],"r":1,"e":"Pré-compétition = stimulation : pétrissage rapide, percussions légères → ↑ vigilance, ↑ trophicité, sans fatiguer.","s":4},{"q":"Lors du massage, la communication avec le patient :","o":["Est inutile, le kiné sachant toujours ce qu'il fait","Est essentielle pour adapter pression et rythme","Doit être permanente, sans aucune pause","Doit être absente, pour la détente"],"r":1,"e":"Échange régulier sur la pression, la douleur, le ressenti → ajustement de la technique en temps réel.","s":4},{"q":"Documenter la séance permet de :","o":["Rien d'utile pour le patient","Tracer l'évolution et ajuster le plan de soins","Facturer davantage de séances","Faire de la publicité pour le cabinet, auprès des médecins"],"r":1,"e":"Compte-rendu = traçabilité légale + suivi de l'évolution + ajustement de la prise en charge sur la durée. C'est aussi une obligation de traçabilité.","s":4},{"q":"Selon le Décret-loi n° 564/99, le kinésithérapeute se concentre sur :","o":["L'analyse du mouvement et de la posture","La seule rééducation, après une blessure","Le seul traitement de la douleur, aiguë ou chronique","La seule prévention des troubles"],"r":0,"e":"Il utilise des modalités éducatives et thérapeutiques spécifiques : mouvement, thérapies manipulatives, moyens physiques et naturels. Il se base sur la structure et la fonction du corps.","s":4},{"q":"L'acte du kinésithérapeute selon l'article 6 s'exerce :","o":["Dans les dimensions physique, mentale et sociale","Dans la seule dimension physique, chez l'adulte","Chez l'adulte uniquement, en dimension physique","En milieu hospitalier, sur prescription"],"r":0,"e":"Il porte sur les structures anatomiques et les fonctions physiologiques du système locomoteur. Elle concerne tous les âges.","s":4},{"q":"Parmi les systèmes sur lesquels intervient le kinésithérapeute, le cours cite :","o":["Les systèmes cardiovasculaire, nerveux et bien d'autres","Le seul musculo-squelettique, sans aucun autre système","Les seuls systèmes locomoteur et respiratoire","Le seul système nerveux, central et périphérique"],"r":0,"e":"Son champ dépasse donc largement le système locomoteur. Le cours cite aussi les systèmes cognitif, immunitaire, métabolique, musculo-squelettique, respiratoire, tégumentaire, urinaire et reproducteur.","s":4},{"q":"L'acte du kinésithérapeute se concrétise :","o":["Par le processus de physiothérapie, sur place ou à distance","En présentiel uniquement, au cabinet ou au domicile du patient","En télésanté uniquement, par visioconférence","Par la seule prescription médicale"],"r":0,"e":"Il intervient en kinésiopathologie et pathokinésiologie, prévention, optimisation et promotion du mouvement fonctionnel. La distance correspond à la télésanté.","s":4},{"q":"Le diagnostic physiothérapeutique porte sur :","o":["Les altérations, les limitations et les restrictions","La seule lésion anatomique, vue à l'imagerie médicale","La seule douleur, cotée à l'EVA","Le seul bilan articulaire, au goniomètre"],"r":0,"e":"Il suit l'examen et l'évaluation, première étape du processus. Il s'agit des limitations d'activité et des restrictions de participation.","s":4},{"q":"L'intervention du kinésithérapeute comprend :","o":["Éducation, mouvement, thérapies manuelle et physique","La seule thérapie manuelle, avec ou sans manipulation","Le seul exercice thérapeutique, actif ou passif","La seule éducation du patient et de son entourage proche"],"r":0,"e":"Elle constitue la quatrième étape du processus de physiothérapie. La thérapie manuelle inclut la manipulation ; les ressources technologiques s'y ajoutent.","s":4},{"q":"Le pronostic et le plan d'intervention se définissent :","o":["Avec le patient et sa famille, selon ses besoins et objectifs","Par le seul kinésithérapeute, selon sa propre expérience clinique","Par le médecin prescripteur, sans le patient","Par l'établissement, selon son règlement"],"r":0,"e":"L'évaluation des résultats suit, avec réévaluation pendant et après l'intervention.","s":4},{"q":"Parmi les domaines d'intervention, le cours cite :","o":["La santé au travail, le bien-être et la santé animale","Les seuls domaines cliniques hospitaliers, en soins aigus","Le seul musculo-squelettique, en libéral","La seule rééducation neurologique"],"r":0,"e":"S'y ajoutent les domaines oncologique, tégumentaire, la fin de vie et la santé mentale. La santé communautaire en fait aussi partie.","s":4},{"q":"Parmi les populations citées dans les domaines d'intervention figurent :","o":["Femmes, bébés, enfants, adolescents, âgés et sportifs","Les seuls adultes actifs, âgés de vingt à soixante ans","Les seuls sportifs, amateurs ou professionnels","Les seules personnes âgées, en institution"],"r":0,"e":"Cette diversité traduit l'étendue du champ professionnel. Il s'agit des personnes âgées.","s":4},{"q":"Parmi les contextes de pratique, le cours cite :","o":["Entreprises, sport, arts, recherche et projets sociaux","Les seuls hôpitaux publics et privés","Les seules cliniques privées, en ville comme à la campagne","Le seul exercice libéral, en cabinet"],"r":0,"e":"Établissements de santé, institutions locales, services d'aide et établissements d'enseignement complètent la liste. Les projets sont communautaires, sociaux et politiques.","s":4},{"q":"La définition de Holey & Cook (1999) situe le massage :","o":["Dans une démarche holistique, par un professionnel qualifié","Comme une technique isolée, sans autre soin","Comme un simple soin de confort, sans visée thérapeutique","Comme une pratique non thérapeutique, de bien-être"],"r":0,"e":"Kumar, Beaton & Hughes (2013) le définissent comme la manipulation de tissus mous à des fins thérapeutiques.","s":4},{"q":"Le massage s'inscrit dans :","o":["Les thérapies manipulatives, après raisonnement clinique","Les thérapies physiques, comme l'électrothérapie","Les moyens naturels, comme l'eau ou la chaleur","L'éducation thérapeutique, comme un conseil donné au patient"],"r":0,"e":"Il est utilisable dans tous les domaines et niveaux d'intervention.","s":4},{"q":"Les niveaux d'intervention où le massage est utilisable sont :","o":["Promotion, prévention, thérapie, habilitation et rééducation","La seule thérapie, après le diagnostic médical établi","La seule prévention, avant l'apparition de toute lésion","La seule rééducation, après une chirurgie ou une fracture"],"r":0,"e":"Cette polyvalence découle de son statut de modalité thérapeutique choisie par raisonnement clinique.","s":4},{"q":"La première mention écrite du massage remonte à :","o":["L'an 2698 avant J.-C., en Chine","L'an 1850, en Suède, avec Ling","L'an 400 avant J.-C., en Grèce antique","L'an 1200, en Europe médiévale"],"r":0,"e":"Au fil des siècles, il a servi à promouvoir la santé et prévenir les maladies par toucher, frictions et pétrissage.","s":4},{"q":"Les auteurs cités pour l'histoire du massage sont :","o":["Field, en 1998, et Schneider, en 1996","Holey et Cook, en 1999","Kumar et Beaton, en 2013","Sackett, en 1996, et Kumar, en 2013, ensemble"],"r":0,"e":"Holey & Cook (1999) et Kumar, Beaton & Hughes (2013) sont cités pour les définitions.","s":4},{"q":"L'examen et l'évaluation, première étape du processus, comprennent :","o":["Observation, entretien, examen manuel, tests et mesures","Le seul entretien avec le patient et sa famille","Le seul examen manuel, sans entretien préalable","Les seuls tests standardisés, sans aucun examen manuel"],"r":0,"e":"Ils fondent ensuite le diagnostic physiothérapeutique. Les examens complémentaires en font partie.","s":4},{"q":"Parmi les finalités de l'acte du kinésithérapeute, le cours cite :","o":["Prévention, rééducation, réadaptation et soins palliatifs","La seule rééducation, après une blessure ou une opération","La seule prévention des troubles musculo-squelettiques","Le seul traitement de la douleur aiguë ou chronique"],"r":0,"e":"Les soins palliatifs figurent explicitement dans ce champ. Promotion de la santé, réduction des risques, maintien et récupération s'y ajoutent.","s":4},{"q":"La kinésiopathologie et la pathokinésiologie désignent :","o":["Deux cadres d'intervention du kinésithérapeute","Deux pathologies du mouvement, rares","Deux techniques de massage profond","Deux diagnostics médicaux, posés par le médecin traitant"],"r":0,"e":"Ils encadrent l'intervention sur le mouvement fonctionnel et la douleur.","s":4},{"q":"Le processus de physiothérapie se conclut par :","o":["La conclusion, après évaluation des résultats","L'intervention, sans évaluation finale","Le diagnostic, posé en fin de prise en charge","Le pronostic, établi seulement à la toute fin du suivi"],"r":0,"e":"La réévaluation a lieu pendant et après l'intervention. Une modification éventuelle précède la conclusion.","s":4},{"q":"Les modalités citées dans la définition du kinésithérapeute sont :","o":["Le mouvement, les manipulations, les moyens physiques","Les seuls exercices, actifs ou passifs","Les seuls moyens physiques, comme la chaleur et le froid","Les seules manipulations vertébrales"],"r":0,"e":"Elles servent à promouvoir la santé, prévenir les maladies et handicaps, et traiter, habiliter ou réhabiliter. Les moyens naturels en font aussi partie.","s":4},{"q":"L'effleurage vient du mot français signifiant :","o":["Frapper","Glisser","Pétrir","Tourner"],"r":1,"e":"Effleurer = GLISSER en français. Technique de glissement lent et rythmique.","s":5},{"q":"L'effleurage se réalise généralement :","o":["Au milieu de la séance, entre deux pétrissages","Au début et à la fin, ou entre différentes techniques","Jamais seul, toujours après une friction profonde de la zone","Uniquement seul, sans autre technique associée"],"r":1,"e":"Utilisé au début, à la fin, ou entre différentes techniques de massage/thérapie manuelle.","s":5},{"q":"La pression de l'effleurage est :","o":["Maximale, sur les tissus profonds","Légère, sur les tissus superficiels","Profonde, sur les plans musculaires","Variable, selon l'humeur du kiné et du patient"],"r":1,"e":"Pression LÉGÈRE au niveau des tissus SUPERFICIELS.","s":5},{"q":"Le sens de progression de l'effleurage est :","o":["Du proximal vers le distal","Du distal vers le proximal","Aléatoire, selon la zone et la position","Latéral, de dedans en dehors"],"r":1,"e":"DISTAL → PROXIMAL (sens de la circulation lymphatique et sanguine, retour veineux).","s":5},{"q":"Un objectif thérapeutique de l'effleurage est :","o":["Renforcer le muscle sous-jacent, en force","Favoriser le retour veineux et lymphatique","Augmenter la douleur locale","Bloquer le flux sanguin pour relâcher"],"r":1,"e":"Effleurage : retour veineux/lymphatique, échanges tissulaires, ↑ apport sanguin, élimination irritants chimiques, relâche les fibres musculaires. Il aide aussi à éliminer les irritants chimiques.","s":5},{"q":"L'effleurage est CONTRE-INDIQUÉ en cas de :","o":["Une peau saine et souple","Une insuffisance cardiaque avec œdème des jambes","Un membre bien détendu après une séance de pétrissage","Aucune raison particulière"],"r":1,"e":"CI : solutions de continuité, varices, œdèmes importants, hyperesthésie, zones poilues, ICC avec œdème MI. L'insuffisance cardiaque est congestive.","s":5},{"q":"Une indication de l'effleurage est :","o":["Fracture aiguë","Œdème veineux chronique","Plaie ouverte","Hémorragie active"],"r":1,"e":"Indication : troubles circulatoires comme l'œdème veineux chronique.","s":5},{"q":"Pendant l'effleurage, la pression :","o":["Augmente progressivement au fil du geste","Reste uniforme tout au long du mouvement","Diminue progressivement jusqu'à disparaître","Varie selon l'humeur du patient"],"r":1,"e":"Pression MAINTENUE UNIFORME pendant tout le mouvement.","s":5},{"q":"Le rythme de l'effleurage est :","o":["Rapide et saccadé","Lent et rythmé","Aléatoire","Très lent uniquement"],"r":1,"e":"Mouvement LENT ET RYTHMÉ pour favoriser le retour des fluides.","s":5},{"q":"Quelle modalité d'effleurage utilise un mouvement circulaire ?","o":["Deux mains","Montre / Horloge","Pouces","Phalanges"],"r":1,"e":"Modalité MONTRE/HORLOGE = mouvements circulaires.","s":5},{"q":"L'effleurage 'main après main' signifie :","o":["Les deux mains travaillent ensemble","Les deux mains alternent en continu","Une seule main travaille à la fois","Les mains restent fixes sur la peau"],"r":1,"e":"Main après main = alternance continue des mains.","s":5},{"q":"L'effleurage agit sur :","o":["La peau seule, sans les plans profonds","La peau, les muscles, les vaisseaux et les nerfs","Les os seuls, par une pression transmise à travers la peau","Les nerfs seuls, par stimulation sensitive"],"r":1,"e":"Agit sur tous les tissus : peau, sous-cutanés, muscles, aponévroses, vaisseaux, nerfs. Les tissus sous-cutanés et les aponévroses en font partie.","s":5},{"q":"Au membre supérieur, une zone particulière pour l'effleurage est :","o":["Le pubis et le pli de l'aine","Le deltoïde et la région thénar","La rotule et le creux poplité du genou","Le tarse et la plante du pied"],"r":1,"e":"Particularités du MS : deltoïde, région thénar.","s":5},{"q":"Au membre inférieur, une zone particulière pour l'effleurage est :","o":["L'omoplate, la clavicule et la région thénar de la main","Le fascia lata, les jumeaux et le fascia plantaire","La clavicule, le deltoïde et le biceps","Le crâne, la nuque et les trapèzes"],"r":1,"e":"MI : tenseur du fascia lata, jumeaux, fascia plantaire. Il s'agit du tenseur du fascia lata.","s":5},{"q":"Le mouvement de l'effleurage est :","o":["Discontinu, les mains quittant la peau","Continu, les mains revenant au point de départ","Saccadé, les mains frappant la peau par petits coups","Aléatoire, les mains changeant sans cesse de zone"],"r":1,"e":"Mouvement CONTINU, les mains reviennent toujours au point de départ.","s":5},{"q":"L'effleurage peut être combiné à une autre stratégie pour gagner en souplesse :","o":["Un repos total entre les séances","Une résistance excentrique, selon Forman en 2014","Un étirement passif uniquement, maintenu 30 secondes","Aucune autre stratégie associée"],"r":1,"e":"Massage profond + résistance EXCENTRIQUE = gain de souplesse plus important (Forman et al., 2014).","s":5},{"q":"Sur quelle phase d'une lésion l'effleurage est-il indiqué ?","o":["La phase aiguë, au pic de l'inflammation","La phase subaiguë, pour résorber l'exsudat","La phase chronique seulement, après six mois d'évolution","Toutes les phases, sans distinction"],"r":1,"e":"Lésions tissus mous en phase SUBAIGUË : favorise l'absorption de l'exsudat inflammatoire.","s":5},{"q":"L'effleurage peut servir de :","o":["Transition entre techniques, seulement","Préparation des tissus, et rien d'autre ensuite","Préparation et transition entre techniques","Ni préparation ni transition"],"r":2,"e":"Effleurage = préparer + faire la continuité entre les différentes techniques.","s":5},{"q":"Les zones d'HYPERESTHÉSIE sont :","o":["Indiquées","Contre-indiquées","Recommandées","Sans effet"],"r":1,"e":"Zones d'hyperesthésie = CONTRE-INDIQUÉES (douleur amplifiée).","s":5},{"q":"Les zones très POILUES sont :","o":["Idéales, pour un meilleur glissement","Contre-indiquées, par risque d'irritation","Sans contre-indication, avec un peu plus d'huile","Recommandées, pour stimuler les follicules"],"r":1,"e":"Zones trop poilues = contre-indication relative (irritation du frottement).","s":5},{"q":"L'effleurage est habituellement la 1ʳᵉ technique d'une séance car :","o":["Il dure le plus longtemps de toutes les techniques","Il prépare les tissus et installe le contact","Il est le plus intense de tous les gestes","Il échauffe les os et les articulations"],"r":1,"e":"Effleurage = mise en contact, prise de température et de tonus, préparation pour techniques plus profondes.","s":5},{"q":"L'effleurage profond favorise principalement :","o":["L'inflammation locale, pour cicatriser","Le retour veineux et lymphatique","La contraction musculaire réflexe","La sudation de la peau traitée"],"r":1,"e":"Pression profonde et lente du distal vers le proximal = drainage veineux/lymphatique. Le geste va du distal vers le proximal.","s":5},{"q":"La main du kiné en effleurage doit :","o":["Rester rigide, doigts tendus et serrés","Épouser la zone, en contact total","Glisser du bout des doigts","Décoller à chaque geste, puis revenir"],"r":1,"e":"Main moulée à la zone = contact maximal, distribution homogène de la pression.","s":5},{"q":"L'effleurage superficiel a un effet :","o":["Sympathique, donc stimulant et excitant","Parasympathique, donc apaisant","Ostéogénique, sur l'os sous-jacent","Glycogénolytique, sur le muscle"],"r":1,"e":"Manœuvres superficielles lentes → activation parasympathique, ↓ vigilance douloureuse, relaxation. Il est aussi désensibilisant.","s":5},{"q":"Une contre-indication de l'effleurage est :","o":["Un stress passager, avant un examen important","Une plaie, une infection ou une brûlure","Une fatigue générale, en fin de journée","Une insomnie, depuis quelques nuits"],"r":1,"e":"Pas d'effleurage sur lésion cutanée active : risque infectieux et douloureux. La brûlure est récente, l'infection cutanée.","s":5},{"q":"L'effleurage palmaire utilise :","o":["Le bout des doigts, en pinceau léger","La paume et le talon de la main","Le coude et l'avant-bras","Le bord des ongles, en griffe"],"r":1,"e":"Effleurage palmaire = paume complète + talon, ↑ surface de contact, pression douce et large.","s":5},{"q":"L'effleurage en \"peignant\" (digital) sert à :","o":["Un travail global, sur les grandes surfaces","Un travail fin sur les petites zones, comme les mains","Un échauffement du dos avant une séance de pétrissage profond","Un drainage du rachis, de bas en haut"],"r":1,"e":"Effleurage digital = précis, adapté aux petites zones (extrémités, espaces inter-tendineux). Il convient au visage, aux mains et aux espaces inter-osseux.","s":5},{"q":"Le rythme idéal d'un effleurage de drainage est :","o":["Très rapide, saccadé","Lent, régulier et continu","Aléatoire, irrégulier","Rapide, sans pression"],"r":1,"e":"Drainage = lent, continu et régulier pour suivre le rythme veineux/lymphatique.","s":5},{"q":"Combien de répétitions par segment en moyenne ?","o":["Un seul passage rapide","De 5 à 10 passages","Environ 100 passages","Aucune répétition, un seul geste lent"],"r":1,"e":"≈ 5-10 passages par segment = suffisant pour induire l'effet recherché sans surcharge tissulaire.","s":5},{"q":"Après un effleurage, on enchaîne typiquement avec :","o":["Un tapotement direct, sans transition","Un pétrissage ou des techniques plus profondes","Une percussion violente sur les masses musculaires","Rien, la séance s'arrêtant là"],"r":1,"e":"Progression classique : effleurage (prépare) → pétrissage (mobilise) → friction ciblée → re-effleurage (récupération).","s":5},{"q":"L'effleurage s'utilise :","o":["Au début et à la fin, ou entre différentes techniques","Uniquement au début, avant toute autre technique","Uniquement à la fin, après toutes les techniques","Au milieu de la séance, entre deux pétrissages"],"r":0,"e":"Du français « effleurer », c'est-à-dire glisser.","s":5},{"q":"Parmi les objectifs thérapeutiques de l'effleurage figure :","o":["Rétablir la mobilité des interfaces tissulaires","Augmenter la force du muscle sous-jacent, en profondeur","Briser les adhérences profondes, par friction","Stimuler le fuseau musculaire, par percussion"],"r":0,"e":"S'y ajoutent les échanges tissulaires, le retour veineux et lymphatique, l'apport sanguin, l'élimination des irritants et le relâchement des fibres.","s":5},{"q":"L'effleurage est indiqué dans les lésions des tissus mous :","o":["En phase subaiguë, pour résorber l'exsudat","En phase aiguë, dès les premières heures","En phase chronique seulement, après six mois","À toutes les phases, sans aucune distinction"],"r":0,"e":"Il sert aussi à préparer le patient et le kiné aux autres techniques et à assurer la continuité entre elles. L'exsudat est inflammatoire.","s":5},{"q":"Parmi les contre-indications de l'effleurage figure :","o":["L'insuffisance cardiaque avec œdème des jambes","La fatigue musculaire après un effort intense","La douleur musculaire d'origine mécanique","Le stress et l'anxiété passagère"],"r":0,"e":"S'y ajoutent les plaies, les régions variqueuses, les œdèmes importants, l'hyperesthésie et les zones trop poilues.","s":5},{"q":"Les régions variqueuses contre-indiquent l'effleurage en raison :","o":["Du risque de lésion des parois veineuses","D'une douleur vive lors du passage des mains","D'un risque infectieux par la peau","D'une hyperesthésie de la zone"],"r":0,"e":"C'est l'une des six contre-indications citées.","s":5},{"q":"L'exécution de l'effleurage commence :","o":["En distal, en allant vers le proximal","En proximal, en allant vers le distal du membre","Au centre de la zone, en rayonnant","Indifféremment, selon le confort"],"r":0,"e":"Ce sens suit celui de la circulation lymphatique et sanguine.","s":5},{"q":"La pression durant l'effleurage doit être :","o":["Uniforme, tout au long du mouvement","Croissante, du début à la fin","Décroissante, du début à la fin","Variable, selon la zone traitée"],"r":0,"e":"Le mouvement est lent et rythmé, pour favoriser le retour des fluides.","s":5},{"q":"Le caractère continu de l'effleurage implique que :","o":["Les mains reviennent toujours au point de départ","Les mains se détachent entre chaque passage","Le mouvement s'interrompt toutes les dix secondes","Les mains changent de zone à chaque passage, sans retour"],"r":0,"e":"Elles restent par ailleurs ajustées à la surface anatomique.","s":5},{"q":"La modalité « montre » ou « horloge » de l'effleurage correspond à :","o":["Des mouvements circulaires","Une alternance des mains","L'usage des pouces","L'usage du dos des doigts"],"r":0,"e":"Les cinq modalités sont deux mains, main après main, pouces, face dorsale des phalanges et horloge.","s":5},{"q":"La modalité aux pouces s'emploie :","o":["Sur les zones petites ou précises","Sur les grandes surfaces du dos","Sur l'abdomen, dans le sens horaire","Pour l'alternance des deux mains"],"r":0,"e":"La modalité « main après main » assure, elle, une alternance continue.","s":5},{"q":"Au membre inférieur, les régions particulières de l'effleurage sont :","o":["Le fascia lata, les jumeaux et le fascia plantaire","Le deltoïde, le biceps et la région thénar","Le quadriceps, la rotule et la patte d'oie","Les ischio-jambiers, le creux poplité et le tendon d'Achille"],"r":0,"e":"Au membre supérieur, ce sont les deltoïdes et la région thénar.","s":5},{"q":"Selon Forman et al. (2014), le massage profond combiné à une résistance excentrique :","o":["Améliore les résultats par rapport à son usage isolé","N'apporte aucun effet supplémentaire mesurable","Est contre-indiqué chez le sportif","Remplace l'étirement dans tous les cas, chez tous les patients"],"r":0,"e":"C'est la technique avancée citée en complément de l'effleurage.","s":5},{"q":"Le pétrissage vient du mot français signifiant :","o":["Glisser","Pétrir","Frapper","Tourner"],"r":1,"e":"Du français PÉTRIR = compression + relâchement des tissus.","s":6},{"q":"Le pétrissage est caractérisé par :","o":["Un glissement léger et continu","Une compression suivie d'un relâchement","Une absence de pression sur la peau","Une vibration fine, uniquement"],"r":1,"e":"COMPRESSION appliquée sur les tissus suivie d'un RELÂCHEMENT.","s":6},{"q":"Le pétrissage s'applique surtout sur :","o":["Les os seuls, par pression transmise","Les tissus superficiels et les muscles","Le seul cartilage articulaire","Les cheveux et le cuir chevelu"],"r":1,"e":"S'applique aux tissus superficiels, tissus musculaires profonds et ligaments. Il atteint aussi le tissu musculaire profond et les ligaments.","s":6},{"q":"Une contre-indication au pétrissage :","o":["Muscle sain","Thrombophlébite","Aucune","Repos"],"r":1,"e":"CI : rupture musculaire aiguë, inflammation aiguë, THROMBOPHLÉBITE, néoplasies, infections bactériennes, modifs du tonus.","s":6},{"q":"Le ROULEMENT s'effectue surtout sur :","o":["Les gros muscles uniquement, avec les deux mains entières","Les petits muscles ou les tissus superficiels","Le tissu osseux, par une pression forte","Aucun tissu en particulier"],"r":1,"e":"Roulement : petits muscles / tissus superficiels avec doigts (toute la main pour gros muscles). On utilise les doigts, les pouces et les index.","s":6},{"q":"Le KNEADING (pétrissage classique) :","o":["Avec glissement, sans étirement","Sans glissement, avec un pli dans la peau","Sans contact, par vibration de l'air","Par vibrations seules, sans compression"],"r":1,"e":"Kneading = SANS glissement, étirement + compression des structures profondes, provoque un PLI dans la peau. Il étire et comprime les structures profondes.","s":6},{"q":"Le sens du kneading est :","o":["Du distal vers le proximal","Du proximal vers le distal","Latéral, de dedans en dehors du membre","Sans direction particulière"],"r":1,"e":"Kneading commence dans la région PROXIMALE et descend vers le distal.","s":6},{"q":"Le WRINGING (essorage) se caractérise par :","o":["Des mouvements vibratoires fins","Des mouvements en huit, un rouleau entre les doigts","Une compression seule, sans mouvement","Un glissement continu, du distal vers le proximal du membre"],"r":1,"e":"Wringing : compression légère, ROULEAU de tissu/muscle entre les doigts, mouvements en forme de 8.","s":6},{"q":"Le SHAKING (vibration) se réalise avec :","o":["Un muscle en étirement maximal","Un muscle mis en raccourcissement","Un muscle relâché complètement","Un os, par sa diaphyse"],"r":1,"e":"Shaking : muscle positionné en RACCOURCISSEMENT, mouvements vibratoires.","s":6},{"q":"Les points de pression (trigger) sont causés par :","o":["Le hasard, sans cause","Un désordre au niveau du fascia","Une fracture osseuse","Un nerf sectionné en amont"],"r":1,"e":"Trigger points : désordre du FASCIA, provoque raideur + sensibilité + douleur irradiée.","s":6},{"q":"La pression sur un point trigger doit être :","o":["Ferme, pendant quelques secondes","Légère et brève, en effleurant","Forte, sans interruption","Inutile, le point cédant tout seul avec le temps"],"r":0,"e":"Pression FERME pendant quelques secondes, avec doigts ou paumes.","s":6},{"q":"Les points trigger peuvent provoquer :","o":["Aucune douleur, seulement une gêne","Une raideur et une douleur irradiée","Un sourire réflexe, par détente","Un gain de force, par stimulation"],"r":1,"e":"Trigger : raideur musculaire + sensibilité + DOULEUR IRRADIÉE. La zone est aussi sensible.","s":6},{"q":"Le pétrissage peut mobiliser :","o":["Aucune contracture, seulement la peau","Les contractures et les tissus sous-cutanés","Les os, par une pression transmise","Le sang seul, sans action sur les tissus"],"r":1,"e":"Objectifs incluent la mobilisation des contractures musculaires, peau et tissus sous-cutanés. La peau est aussi mobilisée.","s":6},{"q":"Le pétrissage favorise :","o":["Le retour veineux et lymphatique","La douleur musculaire réflexe","La paralysie du muscle","Rien de mesurable"],"r":0,"e":"Favorise échanges tissulaires + retour veineux/lymphatique + élimination des irritants chimiques.","s":6},{"q":"Le pistolet de massage :","o":["A des méthodes bien définies, validées par les études","N'a pas de méthode d'application définie","Est interdit en kinésithérapie","Est universel, pour tous les patients"],"r":1,"e":"Pas de méthodes d'application définies. Possibles conflits d'intérêts dans la littérature. La littérature présente des conflits d'intérêts possibles.","s":6},{"q":"Le pétrissage peut augmenter :","o":["Rien de mesurable dans les tissus","La résistance et la longueur du tissu fibreux","La douleur permanente du muscle traité, en profondeur","La rigidité maximale du tissu"],"r":1,"e":"Augmente la RÉSISTANCE du tissu conjonctif et la LONGUEUR/élongation du tissu fibreux. La résistance concerne le tissu conjonctif.","s":6},{"q":"Une inflammation ARTICULAIRE aiguë est :","o":["Indication","Contre-indication","Sans rapport","Indication forte"],"r":1,"e":"Inflammation articulaire aiguë = CONTRE-INDICATION au pétrissage.","s":6},{"q":"Le wringing peut se faire avec :","o":["Uniquement les pouces, sans la paume","Les pouces et la paume des phalanges, ou toute la main","Le coude et l'avant-bras, en appui sur les gros muscles","Les pieds, pour les très grands muscles"],"r":1,"e":"Wringing : pouces + paume des phalanges (toute la main pour gros muscles). Toute la main sert pour les gros muscles.","s":6},{"q":"Le shaking peut être réalisé avec :","o":["Une seule main, quelle que soit la zone","Une main, deux mains ou les mains superposées","Les doigts seuls, sans jamais la paume","Les pieds, pour les grands muscles du dos"],"r":1,"e":"Selon zone et objectifs : une main, deux mains, ou mains superposées.","s":6},{"q":"Les néoplasies sont :","o":["Une indication du pétrissage profond","Une contre-indication au pétrissage","Sans effet sur la technique choisie","Une indication relative"],"r":1,"e":"Maladies néoplasiques = CONTRE-INDICATION au pétrissage (risque de propagation).","s":6},{"q":"Le pétrissage agit principalement sur :","o":["Les os, par une pression transmise","La peau, le tissu sous-cutané et les muscles","Les ligaments seuls, autour des articulations du membre","Les nerfs centraux, par voie réflexe"],"r":1,"e":"Pétrissage = saisir, soulever, presser, mobiliser → cible peau, sous-cutané et masse musculaire.","s":6},{"q":"Le pétrissage roulement (rolling) consiste à :","o":["Frapper la peau avec le bord des mains","Saisir et rouler les tissus entre pouces et doigts","Étirer la peau au maximum, sans jamais la rouler","Aspirer la peau avec une ventouse"],"r":1,"e":"Rolling = rouler le pli cutané entre pouces (en arrière) et doigts (en avant), avancer progressivement.","s":6},{"q":"Le kneading consiste à :","o":["Tapoter la peau, du bout des doigts","Pétrir comme une pâte, les mains alternant","Frapper les tissus avec le poing fermé","Étirer un tendon dans son axe"],"r":1,"e":"Kneading = pétrissage profond bi-manuel alterné, mobilise les masses musculaires importantes.","s":6},{"q":"Le wringing (essorage) consiste à :","o":["Frotter la peau dans un seul sens","Essorer les tissus, les mains tournant en sens opposé","Effleurer la peau, les mains glissant dans le même sens","Tapoter les tissus avec les doigts"],"r":1,"e":"Wringing = deux mains autour d'un segment, mouvement de torsion alternée comme pour essorer un linge.","s":6},{"q":"Le shaking (secouage) provoque :","o":["Une contraction réflexe du muscle secoué","Une décontraction musculaire et un drainage","Une fracture de fatigue de l'os","Aucun effet mesurable sur le muscle"],"r":1,"e":"Shaking = secousses rapides et fines → décontraction réflexe + facilite le drainage.","s":6},{"q":"Un point trigger se traite typiquement par :","o":["Un mouvement bref et rapide","Une compression soutenue, de 30 à 90 secondes","Un massage rapide et superficiel, de 1 à 2 minutes","Un étirement seul, sans compression"],"r":1,"e":"Trigger point = pression maintenue jusqu'à atténuation de la douleur référée (compression ischémique). C'est une compression ischémique.","s":6},{"q":"Une contre-indication du pétrissage profond est :","o":["Une tension musculaire après l'effort","Un hématome récent ou une déchirure musculaire","Un stress important avant un examen ou une compétition","Une migraine sans signe neurologique"],"r":1,"e":"CI = pas de pétrissage profond sur lésion tissulaire fraîche (risque d'aggravation, saignement). L'inflammation aiguë est aussi une contre-indication.","s":6},{"q":"Sur le plan circulatoire local, le pétrissage favorise :","o":["Le sommeil seul, sans effet circulatoire","La vasodilatation et l'oxygénation locales","Une paralysie vasculaire locale","Une fièvre réactionnelle"],"r":1,"e":"Effets : ↑ circulation locale, ↑ apport O₂/nutriments, ↑ élimination métabolites (lactate, etc.). Les déchets métaboliques sont mieux éliminés.","s":6},{"q":"Le rythme du pétrissage est typiquement :","o":["Très lent, presque immobile","Modéré à soutenu, et régulier","Très rapide, presque vibrant","Saccadé, par à-coups"],"r":1,"e":"Rythme soutenu et régulier permet d'entretenir l'effet mécanique et hémodynamique sans crisper le patient.","s":6},{"q":"Avant un pétrissage profond, il faut :","o":["Rien de particulier, on commence directement","Préparer les tissus par un effleurage","Tapoter d'abord la zone, pour l'éveiller","Frictionner d'abord les tendons"],"r":1,"e":"Progression : effleurage (prépare, échauffe) → pétrissage (mobilise) → re-effleurage (récupération).","s":6},{"q":"Le petrissage s'applique généralement sur :","o":["Les tissus superficiels et profonds, et les ligaments","La seule peau, sans atteindre les plans musculaires profonds","Les seuls tendons, près des insertions","Les seules articulations, par mobilisation"],"r":0,"e":"Du français « pétrir », il associe une pression à différents mouvements, avec compression suivie de relâchement.","s":6},{"q":"Parmi les objectifs du petrissage figure :","o":["Augmenter la résistance du tissu conjonctif","Stimuler le fuseau neuromusculaire profond","Briser les cross-links du collagène","Réduire la température locale des tissus"],"r":0,"e":"S'y ajoutent la mobilité et la longueur du tissu fibreux, la mobilité sous-cutanée et la mobilisation des contractures.","s":6},{"q":"Le petrissage vise également :","o":["À faciliter la circulation profonde et superficielle","À immobiliser le segment, pour le protéger durablement","À refroidir les tissus après l'effort","À anesthésier la zone avant un geste"],"r":0,"e":"Il favorise aussi les échanges tissulaires, le retour veineux et lymphatique et l'élimination des irritants chimiques.","s":6},{"q":"Parmi les contre-indications du petrissage figurent :","o":["Les troubles du tonus et les maladies néoplasiques","La fatigue musculaire après l'effort","La contracture musculaire chronique","La douleur chronique du dos, sans aucun signe de gravité"],"r":0,"e":"Rupture musculaire aiguë, inflammation articulaire aiguë, thrombophlébites et infections bactériennes complètent la liste. Rupture musculaire, inflammation articulaire aiguë, thrombophlébites et infections bactériennes complètent la liste.","s":6},{"q":"Le roulement s'applique essentiellement :","o":["Sur les petits muscles ou les tissus superficiels","Sur les gros muscles, avec les deux paumes","Sur les ligaments, autour des articulations","Sur les tendons, au niveau de leurs insertions osseuses"],"r":0,"e":"Il se pratique avec les doigts, ou toute la main pour les gros muscles, les pouces et index des deux mains rapprochant et roulant les structures.","s":6},{"q":"Le kneading commence :","o":["En proximal, puis descend vers le distal","En distal, puis remonte vers le proximal","Au centre de la zone, puis rayonne vers les bords","Indifféremment, selon la zone traitée"],"r":0,"e":"Il se fait sans glissement, par étirement et compression des structures profondes, et provoque un pli dans la peau.","s":6},{"q":"Le wringing se caractérise par :","o":["Un rouleau de tissu entre les doigts, en huit","Une absence de compression, main à plat","Un glissement continu, du distal vers le proximal","Des vibrations fines, sans compression"],"r":0,"e":"Il s'applique sur la peau, les tissus sous-cutanés et les muscles, avec les pouces et la paume des phalanges. La compression est légère.","s":6},{"q":"Lors du shaking, le muscle doit être positionné :","o":["En raccourcissement","En étirement","En position neutre","En contraction"],"r":0,"e":"Les mouvements vibratoires sont émis par la main du kiné, avec une, deux mains ou les mains superposées.","s":6},{"q":"Les trigger points sont causés par :","o":["Un désordre du fascia","Une lésion tendineuse","Une inflammation articulaire","Une compression nerveuse"],"r":0,"e":"Ils peuvent provoquer raideur musculaire, sensibilité et douleur irradiée.","s":6},{"q":"La pression sur un trigger point s'applique :","o":["Avec les doigts, fermement, quelques secondes","Avec un instrument rigide, en appui continu","Par percussion rapide, avec le bord de la main","De façon prolongée, pendant plusieurs minutes sans relâche"],"r":0,"e":"Cette technique complète les quatre modalités du petrissage. On peut aussi utiliser les paumes.","s":6},{"q":"Le kneading se pratique :","o":["Avec une ou deux mains, selon la taille de la zone","Avec les pouces uniquement, sur toute la zone","Avec les poings fermés, sur les masses musculaires","Avec l'avant-bras, en appui sur les gros muscles du dos"],"r":0,"e":"Son absence de glissement le distingue nettement de l'effleurage.","s":6},{"q":"Le petrissage se caractérise fondamentalement par :","o":["Une compression suivie d'un relâchement","Un glissement continu","Une percussion rapide","Une traction maintenue dans l'axe du membre"],"r":0,"e":"C'est ce qui le distingue de l'effleurage, du tapotement et de la friction.","s":6},{"q":"Le tapotement vient du mot français signifiant :","o":["Glisser","Frapper","Pétrir","Tourner"],"r":1,"e":"TAPOTER = frapper. Technique de frappes rapides répétées.","s":7},{"q":"Le tapotement nécessite :","o":["Des mouvements lents et appuyés","Une répétition rapide des mouvements","Une absence totale de mouvement des mains","Une pression continue, sans relâcher"],"r":1,"e":"Tapotement = répétition RAPIDE des mouvements.","s":7},{"q":"Le mécanisme du tapotement (mains en coupe) :","o":["Une pression directe et appuyée sur le muscle, sans air","L'air comprimé crée une onde qui pénètre les tissus","Une compression musculaire profonde","Aucun mécanisme physique particulier"],"r":1,"e":"L'air est comprimé entre la main et la peau → onde de vibration pénétrant les tissus. L'onde est une onde de vibration.","s":7},{"q":"Un objectif du tapotement :","o":["Endormir le patient, par un rythme très lent et monotone","Stimuler les tissus et activer le fuseau musculaire","Augmenter la fatigue musculaire","Bloquer la circulation locale"],"r":1,"e":"Objectifs : stimulation tissulaire, activation du fuseau musculaire, ↑ circulation locale, relaxation, réduction de la fatigue. Il augmente aussi la circulation locale et réduit la fatigue.","s":7},{"q":"Une contre-indication au tapotement :","o":["Un muscle sain, bien détendu","Une élévation de la température, comme la fièvre","Un repos complet après une longue journée de travail","Une détente générale, après le soin"],"r":1,"e":"CI : fièvre, altérations cutanées, thrombose/phlébite, tissus inflammatoires, fractures, protubérances osseuses.","s":7},{"q":"Concernant les fractures, le tapotement est :","o":["Indiqué, pour stimuler la consolidation","Contre-indiqué, même en cas de simple suspicion","Sans effet, la fracture n'étant pas atteinte","Recommandé, avec les mains en coupe"],"r":1,"e":"Fractures OU suspicions de fracture = CI absolue au tapotement.","s":7},{"q":"Le tapotement sur les PROTUBÉRANCES OSSEUSES est :","o":["Indiqué","Contre-indiqué","Sans risque","Recommandé"],"r":1,"e":"Protubérances osseuses = CONTRE-INDICATION (risque traumatique).","s":7},{"q":"Une modalité de tapotement :","o":["Mains en coupe","Glissement","Pression statique","Étirement"],"r":0,"e":"3 modalités : mains en coupe, bord cubital (doigts joints/écartés), bouts des doigts.","s":7},{"q":"Avec les mains en coupe, les bras sont :","o":["Tendus, coudes verrouillés en extension","En abduction, coudes fléchis","Le long du corps, coudes tendus","Loin du patient, épaules en flexion"],"r":1,"e":"Mains en coupe : COUDES FLÉCHIS, bras en abduction.","s":7},{"q":"Le tapotement avec bord cubital se fait avec :","o":["Les pouces seuls, posés à plat sur toute la peau du dos","Le bord cubital de la main, doigts joints ou écartés","Le coude, en appui sur les masses musculaires","Le poing fermé, par sa face dorsale"],"r":1,"e":"Bord CUBITAL (côté petit doigt) de la main, doigts joints ou écartés.","s":7},{"q":"En position de tapotement bord cubital, le poignet est :","o":["En flexion, doigts tendus","En extension, doigts fléchis","Verrouillé, sans mobilité","Indifférent, selon la zone et le patient"],"r":1,"e":"Poignet en EXTENSION, doigts en flexion, MS en abduction, coudes fléchis. Les membres supérieurs sont en abduction, coudes fléchis.","s":7},{"q":"Le tapotement peut activer :","o":["Aucun récepteur particulier","Le fuseau musculaire, de façon mécanique","La douleur, par les nocicepteurs","Le sommeil, par une stimulation lente et monotone"],"r":1,"e":"ACTIVATION MÉCANIQUE du fuseau musculaire (récepteur de la longueur).","s":7},{"q":"Sur des tissus inflammatoires, le tapotement est :","o":["Recommandé","Contre-indiqué","Sans effet","Optionnel"],"r":1,"e":"Tissus inflammatoires = CI (risque d'aggraver l'inflammation).","s":7},{"q":"Le tapotement favorise paradoxalement :","o":["La douleur, par une stimulation excessive","La relaxation musculaire et moins de fatigue","Le coma, par une sidération nerveuse","La fatigue, par une stimulation répétée"],"r":1,"e":"Bien que stimulant, le tapotement favorise la RELAXATION musculaire et réduit la perception de la fatigue.","s":7},{"q":"Les mouvements du tapotement doivent être :","o":["Coordonnés avec le mouvement du poignet","Aléatoires, sans rythme défini","Sans coordination entre les mains","Très lents, avec un appui prolongé sur la peau"],"r":0,"e":"Mouvements RAPIDES et bien COORDONNÉS avec le mouvement du poignet. Ils sont aussi rapides.","s":7},{"q":"En cas de thrombose, le tapotement est :","o":["Indiqué, pour dissoudre le caillot sanguin","Contre-indiqué, par risque d'embolie","Sans effet sur la veine thrombosée","Recommandé, avec les mains en coupe"],"r":1,"e":"Thrombose et phlébite = CI absolues (risque embolique).","s":7},{"q":"Le tapotement augmente :","o":["La circulation locale","La douleur musculaire diffuse","La fatigue du muscle","Rien de mesurable"],"r":0,"e":"Augmentation de la CIRCULATION LOCALE par stimulation tissulaire.","s":7},{"q":"Le tapotement bouts des doigts s'utilise pour :","o":["Les grandes zones, comme le dos entier","Les zones précises et délicates","Les régions osseuses, comme le tibia","Aucune zone particulière"],"r":1,"e":"Bouts des doigts = zones plus précises et délicates.","s":7},{"q":"Le tapotement peut être :","o":["À deux mains uniquement, au même rythme","À une ou deux mains, avec des rythmes et durées variés","Sans aucune variation de rythme ni de durée","Toujours uniforme, avec la même technique et la même main"],"r":1,"e":"À 1 ou 2 mains, avec différentes techniques, rythmes et durées. Les techniques varient aussi.","s":7},{"q":"Sur la peau lésée (solutions de continuité), le tapotement est :","o":["Indiqué","Contre-indiqué","Sans effet","Recommandé"],"r":1,"e":"Altérations de la continuité ou de l'état de la peau = CONTRE-INDICATION.","s":7},{"q":"Le tapotement (percussion) a un effet :","o":["Sédatif, qui endort le muscle","Stimulant, qui augmente le tonus","Antalgique pur, sans aucun effet sur le tonus","Nul, sans effet mesurable"],"r":1,"e":"Tapotement = percussions rythmées → réveil du fuseau musculaire, ↑ tonus, stimulation circulatoire. Il augmente aussi la vigilance.","s":7},{"q":"Le tapotement en mains creuses (cupping) est utilisé :","o":["Sur l'abdomen, pour le transit","Sur le thorax, pour décoller le mucus","Sur les yeux, pour la fatigue","Sur le crâne, pour soulager les maux de tête chroniques"],"r":1,"e":"Cupping (clapping) en kiné respiratoire : mains creuses sur thorax pour mobiliser les sécrétions bronchiques. C'est une technique de kinésithérapie respiratoire.","s":7},{"q":"Le hacking utilise :","o":["La paume entière, mains fermées et poignets bloqués","Le bord cubital des mains, mains bien relâchées","Le pouce seul, en appui ferme","Les ongles, en griffant la peau"],"r":1,"e":"Hacking = percussion avec le bord cubital, poignets souples, mains relâchées, rythme rapide alterné.","s":7},{"q":"Une contre-indication du tapotement est :","o":["Une tension musculaire, sans autre signe","La région rénale, une fracture ou une tumeur","Une hypertension légère et bien contrôlée","Une crampe musculaire passagère"],"r":1,"e":"CI : régions fragiles (reins, sein, os ostéoporotique), trauma récent, néoplasie locale. L'ostéoporose sévère en fait aussi partie.","s":7},{"q":"Le tapotement augmente la trophicité par :","o":["Une vasoconstriction, qui chasse le sang","Une vasodilatation et une activation neuromusculaire","Un refroidissement de la peau, qui stimule la circulation","Un saignement capillaire local"],"r":1,"e":"Percussions rythmées → vasodilatation cutanée et musculaire + stimulation des récepteurs musculaires.","s":7},{"q":"Le rythme typique du tapotement est :","o":["1 frappe par minute, très lente","Rapide et régulier, de 2 à 4 par seconde","Irrégulier, selon le ressenti du patient et du kiné","Continu, sans aucune pause"],"r":1,"e":"Tapotement = fréquence rapide (≈ 2-4 Hz) et régulière, mains alternantes.","s":7},{"q":"La force du tapotement provient :","o":["Du dos, par une flexion du tronc à chaque frappe","Du relâchement du poignet et du rebond","Du coude bloqué en extension","Des doigts crispés et tendus"],"r":1,"e":"Force essentielle = poignet souple + utilisation du rebond, pas de force musculaire des bras.","s":7},{"q":"En sport, le tapotement est utile :","o":["Comme massage de récupération profond","En pré-effort pour stimuler","Comme étirement","Pour endormir"],"r":1,"e":"Pré-effort/échauffement sportif : tapotement bref pour ↑ vigilance et trophicité sans fatiguer.","s":7},{"q":"Tapotement en \"bout de doigts\" sert à :","o":["Les régions épaisses, comme les cuisses et les fesses","Les régions sensibles, comme le visage","La plante des pieds seulement","La région lombaire, en profondeur"],"r":1,"e":"Percussion digitale (bouts de doigts) = douce, adaptée aux zones sensibles : visage, cuir chevelu. Le cuir chevelu en fait aussi partie.","s":7},{"q":"Après un tapotement vigoureux, conclure par :","o":["Un autre tapotement, plus léger","Un effleurage doux, pour normaliser","Une compression forte","Rien, la séance s'arrêtant là"],"r":1,"e":"Effleurage final = transition douce, intégration de la stimulation, retour au calme.","s":7},{"q":"Le tapotement se réalise :","o":["À une ou deux mains, avec des rythmes variés","À deux mains obligatoirement, au même rythme","À une seule main, toujours la dominante","Avec l'avant-bras, en appui sur les gros muscles du dos"],"r":0,"e":"Du français « tapoter », c'est-à-dire frapper. Les techniques et les durées varient aussi.","s":7},{"q":"Le mécanisme physique du tapotement repose sur :","o":["La compression de l'air, qui crée une onde de vibration","Un contact profond et direct sur le muscle","Une traction des tissus, dans l'axe du membre","Un glissement appuyé le long des fibres musculaires profondes"],"r":0,"e":"L'exécution se fait sur la surface cutanée, avec une répétition rapide des mouvements.","s":7},{"q":"Parmi les objectifs du tapotement figure :","o":["L'activation mécanique du fuseau musculaire","La rupture des adhérences fibreuses","L'allongement durable du tissu fibreux cicatriciel","Le drainage lymphatique du membre"],"r":0,"e":"S'y ajoutent la stimulation tissulaire, l'augmentation de la circulation locale, la relaxation musculaire et la réduction de la perception de fatigue.","s":7},{"q":"Parmi les contre-indications du tapotement figurent :","o":["Les protubérances osseuses et les fractures","La fatigue musculaire après l'effort","L'hypotonie musculaire, à stimuler justement par percussion","La contracture musculaire chronique"],"r":0,"e":"Fièvre, altérations cutanées, thrombose, phlébite et tissus inflammatoires complètent la liste. Les suspicions de fracture en font aussi partie.","s":7},{"q":"Pour la modalité mains en coupe, les bras sont :","o":["En abduction, coudes fléchis","En adduction, coudes en extension","Le long du corps, coudes tendus","Tendus, coudes verrouillés"],"r":0,"e":"Les mouvements sont rapides et coordonnés avec le mouvement du poignet.","s":7},{"q":"Pour la modalité bord cubital, la configuration est :","o":["Bras abduits, coudes fléchis, poignet en extension, doigts fléchis","Bras abduits, coudes fléchis, poignet en flexion, doigts tendus","Bras le long du corps, coudes tendus, poignet neutre","Bras abduits, coudes tendus, poignet neutre, doigts tendus"],"r":0,"e":"Les doigts peuvent être joints ou écartés, le mouvement restant rapide.","s":7},{"q":"La modalité bouts des doigts s'emploie :","o":["Sur les zones plus précises et plus délicates","Sur les grandes surfaces, comme le dos entier","Sur les masses musculaires épaisses","Sur le dos et les cuisses, en profondeur"],"r":0,"e":"Il s'agit de petits coups avec l'extrémité des doigts.","s":7},{"q":"Le tapotement est décrit comme une technique :","o":["Stimulante, pour activer un muscle hypotonique","Relaxante uniquement, en fin de séance","Profonde, pour briser les adhérences","Analgésique, pour calmer une douleur aiguë"],"r":0,"e":"Paradoxalement, il peut aussi favoriser la relaxation en fin de séance. On la privilégie en début de séance.","s":7},{"q":"L'exigence technique centrale du tapotement est :","o":["La répétition rapide des mouvements","La lenteur et la régularité du geste","La pression maximale sur les tissus","La durée prolongée de chaque contact cutané"],"r":0,"e":"C'est cette rapidité qui engendre l'onde de vibration.","s":7},{"q":"L'élévation de la température contre-indique le tapotement car :","o":["Elle signe un état fébrile ou inflammatoire","Elle augmente la douleur au contact","Elle réduit l'effet de la percussion","Elle gêne la palpation des reliefs osseux du patient"],"r":0,"e":"Les tissus inflammatoires constituent une contre-indication distincte.","s":7},{"q":"L'effet du tapotement sur la perception de la fatigue est :","o":["Une réduction","Une augmentation","Aucun effet","Une variation imprévisible"],"r":0,"e":"Cet objectif accompagne la relaxation musculaire, malgré le caractère stimulant de la technique.","s":7},{"q":"L'exécution du tapotement se fait :","o":["Sur la surface cutanée","Dans la profondeur","Sur le seul tendon","Sur le périoste osseux"],"r":0,"e":"C'est l'onde de vibration engendrée qui pénètre ensuite dans les tissus.","s":7},{"q":"La friction permet de mobiliser :","o":["La peau seule, en surface","Les masses tissulaires les plus profondes","Les os, par une forte pression transmise","L'air contenu dans les tissus"],"r":1,"e":"La friction agit sur les masses tissulaires PLUS PROFONDES (au-delà des techniques superficielles).","s":8},{"q":"Une structure cible de la friction :","o":["La surface de la peau, l'épiderme seul","Les tendons, les ligaments et les gaines synoviales","Le tissu adipeux, sous la peau","Les os, par une pression appuyée sur le périoste osseux"],"r":1,"e":"Cibles : fibres musculaires profondes, tendons, ligaments, gaines synoviales, fragments de capsule articulaire. Les fibres musculaires profondes et la capsule articulaire en font aussi partie.","s":8},{"q":"Un effet thérapeutique de la friction est :","o":["Aucun effet notable, sinon une rougeur passagère","Un réchauffement local et une analgésie","Un refroidissement des tissus profonds","Un endormissement de la peau"],"r":1,"e":"↑ température locale → effet ANALGÉSIQUE local.","s":8},{"q":"La friction provoque :","o":["La formation de nouvelles adhérences fibreuses","La rupture des cross-links et des adhérences","Aucun effet sur la structure du tissu","Une calcification des tendons"],"r":1,"e":"La friction rompt les CROSS-LINKS (liaisons croisées) et les ADHÉRENCES → libère le glissement tissulaire.","s":8},{"q":"La friction est une action :","o":["Indirecte, par voie réflexe médullaire","Mécanique, sur les tissus et les vaisseaux","Énergétique, par les méridiens du corps","Mentale, par la relation"],"r":1,"e":"Action MÉCANIQUE DIRECTE sur les tissus et les vaisseaux.","s":8},{"q":"La friction favorise :","o":["La rigidité des cicatrices anciennes","L'élasticité des structures contractiles","La fibrose des tendons sollicités","La nécrose des tissus profonds"],"r":1,"e":"Favorise l'ÉLASTICITÉ des structures contractiles (muscles, tendons).","s":8},{"q":"La friction augmente :","o":["L'apport sanguin","La fatigue","La rigidité","Rien"],"r":0,"e":"Augmente l'apport sanguin par stimulation locale.","s":8},{"q":"La friction est utile pour :","o":["L'absence d'adhérence, en prévention chez le sportif","Les cicatrices adhérentes et les tendinopathies","Les plaies ouvertes, pour accélérer la fermeture","Les fractures aiguës, pour la consolidation"],"r":1,"e":"Très utilisée dans les adhérences cicatricielles et les tendinopathies (friction transverse profonde de Cyriax).","s":8},{"q":"La friction est une technique :","o":["Très étendue, sur tout le membre","Très ciblée et locale","Sans précision, sur une zone large et mal définie","Universelle, pour tous les tissus"],"r":1,"e":"Technique CIBLÉE, locale, sur une lésion ou adhérence précise.","s":8},{"q":"Pour briser les adhérences, le mouvement de friction doit être :","o":["Parallèle aux fibres, dans leur axe de traction","Perpendiculaire aux fibres, donc transverse","Absent, la pression restant immobile","Latéral seulement, d'un seul côté"],"r":1,"e":"Mouvements PERPENDICULAIRES aux fibres pour briser efficacement les adhérences.","s":8},{"q":"La friction agit sur les structures :","o":["Superficielles uniquement, comme l'épiderme","Profondes, au-delà de la portée des autres techniques","Aucune, l'effet restant psychologique","Mentales, par la relation de confiance avec le thérapeute"],"r":1,"e":"Friction = structures PROFONDES (fibres musculaires, tendons, ligaments, gaines, capsule).","s":8},{"q":"Une gaine synoviale peut-elle être mobilisée par friction ?","o":["Non, elle est trop profonde","Oui, c'est une structure cible","Inutile, car elle se mobilise seule","Dangereux, par risque de rupture"],"r":1,"e":"Oui — les gaines synoviales font partie des structures cibles de la friction.","s":8},{"q":"L'effet de la friction sur le sang est :","o":["Aucun effet sur la circulation locale","Une hausse de l'apport sanguin local","Une baisse de l'apport sanguin local","Une coagulation locale"],"r":1,"e":"↑ apport sanguin local (action mécanique directe sur les vaisseaux).","s":8},{"q":"La friction transverse profonde a été popularisée par :","o":["Field","Cyriax","Mitchell","Schultz"],"r":1,"e":"Friction TRANSVERSE PROFONDE = méthode de CYRIAX (massage transverse profond).","s":8},{"q":"Combien de structures cibles principales sont mentionnées pour la friction ?","o":["Une seule, le tendon profond du muscle","Trois, tendon, ligament et muscle","Cinq, des fibres musculaires à la capsule","Dix, de la peau jusqu'à l'os sous-jacent"],"r":2,"e":"5 structures cibles : fibres musculaires profondes, tendons, ligaments, gaines synoviales, fragments de capsule articulaire. Fibres musculaires profondes, tendons, ligaments, gaines synoviales et capsule.","s":8},{"q":"L'effet ANALGÉSIQUE de la friction vient de :","o":["L'extension du tendon traité","L'augmentation de la température locale","La diminution de l'apport sanguin","Aucun mécanisme connu à ce jour, l'effet étant placebo"],"r":1,"e":"↑ température locale = effet analgésique (vasodilatation, gating de la douleur).","s":8},{"q":"La friction s'utilise typiquement en :","o":["Phase aiguë post-traumatique, dès le premier jour","Phase chronique, sur adhérences et tendinopathies","Présence de fractures fraîches, pour hâter la consolidation","Aucune phase, la technique étant obsolète"],"r":1,"e":"Indication typique : phase chronique pour briser les adhérences cicatricielles et traiter les tendinopathies. Les cicatrices en font aussi partie.","s":8},{"q":"La friction peut briser :","o":["Les os fragilisés, par la pression répétée","Les liaisons croisées, ou cross-links","Les fibres musculaires saines","Les nerfs superficiels de la peau"],"r":1,"e":"Rupture des CROSS-LINKS (liaisons croisées) responsables des adhérences fibreuses.","s":8},{"q":"En termes de profondeur d'action, la friction est une technique :","o":["De surface","De profondeur","Aérienne","Aucune"],"r":1,"e":"C'est une technique de PROFONDEUR, contrairement à l'effleurage qui est superficiel.","s":8},{"q":"L'objectif fonctionnel ultime de la friction est :","o":["Détruire le tissu cicatriciel, pour le refaire","Rendre mobilité et élasticité, sans adhérences","Endurcir le tissu, pour le protéger","Ne rien faire, en attendant la guérison"],"r":1,"e":"Restauration de la MOBILITÉ tissulaire, ÉLASTICITÉ des structures contractiles, et RUPTURE des adhérences.","s":8},{"q":"La friction de Cyriax cible spécifiquement :","o":["La peau seulement, en surface","Les tendons, ligaments et capsules, avec adhérences","Le muscle profond uniquement, dans sa partie charnue","Les os, au niveau du périoste"],"r":1,"e":"Friction transversale profonde (Cyriax) = traitement de référence des tendinopathies, ligaments, capsules avec adhérences. Il s'agit d'inflammation chronique.","s":8},{"q":"La direction de la friction transversale est :","o":["Parallèle aux fibres du tendon","Perpendiculaire aux fibres du tendon ou du ligament","Aléatoire, selon la sensibilité du patient et la zone","Toujours circulaire, autour du tendon"],"r":1,"e":"Cyriax = perpendiculaire aux fibres pour rompre les adhérences entre fibres et tissus voisins.","s":8},{"q":"La friction se fait :","o":["Avec lubrifiant, les doigts glissant sur la peau","Sans lubrifiant, la peau bougeant avec les doigts","Avec beaucoup d'huile, pour ne pas irriter","Sur la peau qui glisse sous les doigts"],"r":1,"e":"Sans lubrifiant : la peau bouge AVEC le doigt sur la zone profonde sous-jacente.","s":8},{"q":"La durée typique d'une friction Cyriax sur une lésion est :","o":["30 secondes, une seule fois","De 5 à 15 minutes, jusqu'à l'analgésie","Plusieurs heures, jusqu'à la disparition de la lésion","2 jours, en continu sur la lésion"],"r":1,"e":"Friction soutenue 5-15 min jusqu'à obtention d'une analgésie locale (effet inhibiteur des nocicepteurs).","s":8},{"q":"Une contre-indication de la friction profonde est :","o":["Une tendinopathie chronique, sans inflammation","Une inflammation aiguë, un hématome ou une infection","Une cicatrice ancienne, bien fermée","Une fatigue générale du patient"],"r":1,"e":"CI : pas de friction profonde sur tissu en phase aiguë inflammatoire (aggrave). Privilégier après 48-72h. La calcification en fait aussi partie.","s":8},{"q":"La friction circulaire vise plutôt :","o":["Les adhérences linéaires des tendons","Les cicatrices et les zones péri-articulaires","Le rachis entier, des cervicales jusqu'au sacrum","Les organes abdominaux profonds"],"r":1,"e":"Friction circulaire (mouvements rotatifs) = adhérences cicatricielles, zones nodulaires. Les points trigger localisés en font aussi partie.","s":8},{"q":"Après une friction profonde, on conseille :","o":["De rester immobile pendant 24 heures","De mobiliser activement la zone traitée","De plâtrer la zone pendant une semaine complète","De compresser la zone avec une bande"],"r":1,"e":"Mobilisation active post-friction = remodelage tissulaire orienté dans l'axe fonctionnel. On vise un gain d'amplitude.","s":8},{"q":"L'instrument souvent utilisé en friction est :","o":["Le coude, en appui large","Le pouce ou un doigt précis","La paume entière, à plat sur la peau","Le poing fermé, en appui"],"r":1,"e":"Friction = précision : pouce, index ou majeur. Petit point de contact pour focaliser la pression.","s":8},{"q":"L'effet local de la friction :","o":["Une vasoconstriction, avec une pâleur de la peau","Une rougeur locale et une analgésie","Un refroidissement local","Une tachycardie réflexe"],"r":1,"e":"Friction → rougeur (hyperémie), libération de médiateurs, analgésie locale, rupture progressive des adhérences. Les adhérences sont aussi mobilisées.","s":8},{"q":"La friction est typiquement réalisée en position :","o":["Du muscle raccourci, au repos","Du tendon en légère tension ou en position fonctionnelle","Du patient debout, en appui","Sans contact direct, à travers un drap épais posé sur la zone"],"r":1,"e":"Tendon/ligament en tension légère facilite l'accès aux fibres et l'effet de la friction transversale.","s":8},{"q":"Parmi les structures cibles de la friction figurent :","o":["Les gaines synoviales et la capsule articulaire","La peau et l'épiderme superficiel","Le tissu adipeux sous-cutané, dans l'hypoderme profond","Les vaisseaux superficiels de la peau"],"r":0,"e":"Fibres musculaires profondes, tendons et ligaments complètent les cinq structures cibles. Il s'agit de fragments de capsule articulaire.","s":8},{"q":"L'effet analgésique de la friction résulte :","o":["De l'augmentation de la température locale","D'une action nerveuse directe sur le nerf","D'un blocage de la conduction nerveuse","D'une vasoconstriction locale, qui prive le nerf de sang"],"r":0,"e":"Elle augmente aussi l'apport sanguin par une action mécanique directe sur les tissus et vaisseaux.","s":8},{"q":"Les mouvements de la friction sont :","o":["Perpendiculaires aux fibres, pour briser les adhérences","Parallèles aux fibres, pour les allonger","Circulaires, pour masser toute la zone autour de la lésion","Longitudinaux, dans l'axe du membre"],"r":0,"e":"Le contact se fait par le pouce ou l'index, directement sur la structure profonde.","s":8},{"q":"La durée d'application de la friction est :","o":["Limitée, car la technique est intense localement","Prolongée, pendant toute la durée de la séance","Indifférente, selon le temps disponible du kiné","D'au moins 20 minutes, sans pause"],"r":0,"e":"La pression doit être suffisante pour atteindre la profondeur ciblée.","s":8},{"q":"La friction est particulièrement utilisée dans :","o":["Les tendinopathies et les cicatrices adhérentes","Les œdèmes, pour accélérer le drainage lymphatique","Les contractures, pour relâcher le muscle","Les troubles circulatoires des membres"],"r":0,"e":"Elle brise les adhérences fibreuses formées après une lésion ou une immobilisation. Pour les tendinopathies, c'est la friction transverse profonde de Cyriax.","s":8},{"q":"La friction est décrite comme une technique :","o":["Très ciblée et locale","Étendue et globale","Globale et diffuse","Superficielle, limitée à l'épiderme"],"r":0,"e":"Son application porte sur une zone précise, ciblée sur la lésion ou l'adhérence.","s":8},{"q":"Les cross-links, que la friction rompt, désignent :","o":["Des liaisons croisées formant des adhérences","Des fibres musculaires lésées","Des vaisseaux sanguins néoformés","Des terminaisons nerveuses libres de la cicatrice"],"r":0,"e":"C'est l'objectif propre de la friction, qu'aucune autre technique ne revendique.","s":8},{"q":"L'action mécanique directe de la friction porte sur :","o":["Les tissus et les vaisseaux","La peau et les poils","Les nerfs et les os","Les os et leur périoste"],"r":0,"e":"Elle augmente ainsi l'apport sanguin dans la zone traitée.","s":8},{"q":"La friction agit en profondeur pour :","o":["Briser les adhérences fibreuses nées après une lésion","Drainer l'œdème vers les ganglions lymphatiques","Relâcher le muscle en profondeur, par inhibition","Stimuler le fuseau neuromusculaire, par percussion"],"r":0,"e":"C'est l'une des seules techniques ayant cette capacité. Elles se forment aussi après une immobilisation.","s":8},{"q":"Le contact lors de la friction se fait :","o":["Avec le pouce ou l'index, sur la structure profonde","Avec la paume, sur toute la surface du membre","Avec le poing fermé, sur les masses musculaires du dos","Avec l'avant-bras, sur les gros muscles"],"r":0,"e":"La pression doit permettre d'atteindre la profondeur visée.","s":8},{"q":"La position anatomique de référence se définit par :","o":["Allongé sur le dos, bras le long du corps","Debout, regard à l'horizon, paumes vers l'avant","Assis, dos droit, mains posées à plat sur les cuisses","Debout, regard à l'horizon, paumes vers l'arrière"],"r":1,"e":"Position orthostatique, regard à l'horizon, MS le long du corps avec avant-bras en SUPINATION (paumes vers l'AVANT). Les pieds sont parallèles.","s":9},{"q":"Le plan sagittal divise le corps en :","o":["Antérieur/Postérieur","Droit/Gauche","Supérieur/Inférieur","Aucun"],"r":1,"e":"Sagittal = droit/gauche. Frontal = antérieur/postérieur. Transversal = supérieur/inférieur.","s":9},{"q":"Les mouvements d'abduction/adduction se font dans le plan :","o":["Sagittal","Frontal","Transversal","Aucun"],"r":1,"e":"Plan FRONTAL (axe sagittal) = abduction/adduction.","s":9},{"q":"La rotation interne/externe se fait dans le plan :","o":["Sagittal, autour d'un axe frontal","Frontal, autour d'un axe sagittal antéro-postérieur","Transversal, autour d'un axe vertical","Aucun plan anatomique défini"],"r":2,"e":"Plan TRANSVERSAL (horizontal), axe vertical/longitudinal = rotations.","s":9},{"q":"Une diarthrose est :","o":["Une articulation immobile, faite de tissu fibreux","Une articulation semi-mobile, avec un disque de fibrocartilage","Une articulation mobile, avec du liquide synovial","Une fracture articulaire mal consolidée"],"r":2,"e":"Diarthrose = articulation MOBILE de grande amplitude avec bourses synoviales + liquide synovial (ex: épaule, genou).","s":9},{"q":"Une suture crânienne est une :","o":["Une diarthrose mobile","Une synarthrose fibreuse","Une amphiarthrose","Une synoviale"],"r":1,"e":"Suture = synarthrose FIBREUSE, immobile.","s":9},{"q":"L'articulation gléno-humérale est :","o":["Une trochléenne, monoaxiale","Une énarthrose, sphérique et triaxiale","Une arthrodie, plane et glissante, sans axe défini","Une articulation en selle, biaxiale"],"r":1,"e":"Gléno-humérale = ÉNARTHROSE, triaxiale, mouvements amples.","s":9},{"q":"L'articulation trapézo-métacarpienne (pouce) est :","o":["Une énarthrose, sphérique et triaxiale","Une trochoïde, en pivot, monoaxiale","Une épiphysiarthrose en selle, biaxiale","Une arthrodie, plane, sans axe"],"r":2,"e":"Trapézo-métacarpienne = articulation EN SELLE, biaxiale.","s":9},{"q":"L'articulation radio-ulnaire supérieure est :","o":["Une sphérique, triaxiale","Une trochoïde, en pivot et monoaxiale","Une arthrodie plane, sans axe défini, très peu mobile","Une articulation en selle, biaxiale"],"r":1,"e":"Trochoïde = cylindre en pivot, monoaxial → rotation autour d'un seul axe. Elle est cylindrique.","s":9},{"q":"Combien de degrés de liberté possède une énarthrose ?","o":["Un seul, monoaxial","Deux degrés, biaxial","Trois degrés, triaxial","Quatre, sans axe"],"r":2,"e":"Énarthrose = 3 degrés de liberté (tri-axial), mouvements amples dans les 3 plans.","s":9},{"q":"Les mouvements accessoires sont :","o":["Volontaires, amples et mesurables au goniomètre","Involontaires, intra-articulaires et de faible amplitude","Inutiles au mouvement normal de l'articulation saine","Mesurables par goniométrie, comme les autres"],"r":1,"e":"Accessoires = NON volontaires, intra-articulaires, faible amplitude, NON mesurables, mais ESSENTIELS. Ils sont essentiels au mouvement normal.","s":9},{"q":"La règle convexe-concave (surface CONVEXE) :","o":["Un glissement dans le même sens que le mouvement osseux","Un glissement opposé au mouvement physiologique","Aucun glissement, seulement une rotation","Un roulement seul, sans glissement"],"r":1,"e":"Surface CONVEXE → glissement OPPOSÉ au mouvement. Surface concave → glissement DANS LE MÊME sens.","s":9},{"q":"Le roulement (mouvement accessoire) se fait :","o":["Dans le sens opposé au mouvement de l'os","Toujours dans le même sens que le mouvement de l'os","Sans aucune congruence entre les surfaces","Sans direction précise, selon la forme des surfaces en contact"],"r":1,"e":"Le roulement se produit TOUJOURS dans le MÊME sens que le mouvement de l'os. Il produit compression articulaire. Il produit une compression articulaire.","s":9},{"q":"La mobilisation PASSIVE est définie par :","o":["Par la seule contraction du patient","Par une autre personne, sans action du patient","Sans aucun mouvement de l'articulation","Par un mouvement actif libre, sans aide extérieure"],"r":1,"e":"Passive = réalisée par AUTRUI, sans intervention active du patient (force externe seule). C'est une force externe.","s":9},{"q":"Une indication TYPIQUE de mobilisation articulaire (Kisner & Colby) est :","o":["Une fracture aiguë non consolidée","Une hypomobilité articulaire réversible","Une hypermobilité instable de l'épaule","Une maladie oncologique active de l'os traité"],"r":1,"e":"5 indications : douleur/spasmes, HYPOMOBILITÉ réversible, défauts de positionnement, ↓ progressive ROM, immobilité fonctionnelle.","s":9},{"q":"L'immobilisation prolongée provoque :","o":["Un renforcement du cartilage articulaire","Une atrophie du cartilage et des adhérences","Une augmentation de l'amplitude articulaire","Aucun effet, si l'immobilisation dure moins d'un an"],"r":1,"e":"Immobilisation = atrophie cartilage, prolifération fibro-adipeuse, adhérences, contractures, affaiblissement ligamentaire. Elle entraîne aussi des contractures et une prolifération fibro-adipeuse.","s":9},{"q":"Le cartilage articulaire est :","o":["Très vascularisé, nourri par l'os sous-chondral","Avasculaire, nourri par le liquide synovial","Richement innervé, donc très sensible","Constitué d'os spongieux minéralisé"],"r":1,"e":"Le cartilage est AVASCULAIRE → la mobilisation est essentielle pour faire circuler le liquide synovial qui le nourrit.","s":9},{"q":"La mobilisation articulaire physiologique :","o":["Augmente la force musculaire du segment mobilisé","Ne prévient pas l'atrophie du muscle","Augmente l'endurance musculaire","Remplace l'exercice musculaire actif"],"r":1,"e":"LIMITES : la mobilisation NE prévient PAS l'atrophie musculaire, N'AUGMENTE PAS la force ou l'endurance. Elle n'augmente ni la force ni l'endurance.","s":9},{"q":"Une contre-indication ABSOLUE à la mobilisation articulaire est :","o":["Une douleur légère, sans gravité","Une lésion aiguë, une fracture ou une chirurgie","Une hypomobilité chronique, ancienne et stable","Une douleur ancienne, bien tolérée"],"r":1,"e":"Contre-indications : lésions aiguës, fractures, chirurgies (mais mouvements précoces contrôlés possibles avec tolérance).","s":9},{"q":"L'end-feel DUR se rencontre typiquement à :","o":["En fin de flexion passive du coude","En fin d'extension passive du coude","En fin de rotation externe passive de l'épaule","En fin de flexion passive de l'épaule"],"r":1,"e":"End-feel DUR (os contre os) = fin de l'extension passive du COUDE. C'est un contact os contre os.","s":9},{"q":"L'end-feel SOUPLE correspond à :","o":["Un contact direct os contre os","Un rapprochement de tissus mous","Un étirement capsulaire","Une absence de sensation"],"r":1,"e":"Souple = rapprochement de TISSUS MOUS (ex: fin de flexion du coude où biceps et avant-bras se compriment). Par exemple en fin de flexion du coude.","s":9},{"q":"Le grade III dans la graduation Kaltenborn correspond à :","o":["Une petite amplitude, au tout début de la mobilité","Une grande amplitude, sans atteindre la limite","La plus grande amplitude, jusqu'à la limite","Un thrust rapide, au-delà de la limite"],"r":2,"e":"Grade III = plus grande amplitude JUSQU'À la limite — pour étirement, forçage de la résistance des tissus. C'est un étirement.","s":9},{"q":"Le grade V (thrust) se caractérise par :","o":["Un mouvement lent et contrôlé","Un mouvement rapide et bref, hors du contrôle du patient","Un mouvement physiologique, actif, réalisé par le patient seul","Un étirement progressif et maintenu"],"r":1,"e":"Grade V = manipulation thrust : RAPIDE, petite amplitude, à la limite, HORS du contrôle du patient. Il est de petite amplitude, à la limite.","s":9},{"q":"Quelle structure protège l'articulation et contient des nerfs sensitifs ?","o":["Le cartilage hyalin articulaire","La membrane fibreuse, externe, de la capsule","L'os sous-chondral, sous le cartilage articulaire","Le liquide synovial, dans la cavité"],"r":1,"e":"La membrane FIBREUSE (externe) = tissu conjonctif dense, protection. Contient les mécanorécepteurs/nocicepteurs.","s":9},{"q":"La membrane SYNOVIALE :","o":["Est externe, sans rôle sécrétoire","Est interne et sécrète la synovie","Contient les nerfs sensitifs","Est constituée d'os spongieux"],"r":1,"e":"Membrane synoviale = INTERNE, produit le LIQUIDE SYNOVIAL. Peut s'étendre comme une bourse (ex: épaule).","s":9},{"q":"Le grade I de Kaltenborn (mobilisation accessoire) correspond à :","o":["Une forte traction, au-delà de la résistance","Une traction très douce, qui annule la pression articulaire","Une mobilisation maximale et forcée, jusqu'à la butée osseuse","Aucun mouvement, une simple prise"],"r":1,"e":"Grade I = traction antalgique très douce, neutralise la pression articulaire, sans étirement capsulaire.","s":9},{"q":"Le grade III de Kaltenborn :","o":["Une traction sans étirement de la capsule","Une traction au-delà de la résistance, qui étire la capsule","Une compression articulaire, pour stimuler le cartilage hyalin","Aucune traction, une simple prise"],"r":1,"e":"Grade III = traction maximale, étire la capsule → gain d'amplitude. À pratiquer avec précaution. Elle permet un gain d'amplitude.","s":9},{"q":"Le end-feel \"capsulaire\" (ferme) est :","o":["Pathologique, car toujours signe de rétraction capsulaire","Normal en rotation externe de l'épaule","Le signe d'une fracture sous-jacente","Le signe d'une instabilité articulaire"],"r":1,"e":"End-feel ferme/capsulaire = arrêt par tension capsulaire (rotation externe normale de l'épaule). L'arrêt vient de la tension capsulaire.","s":9},{"q":"Un end-feel \"vide\" évoque :","o":["Une fin d'amplitude normale, indolore","Une douleur forte, sans butée physique","Une rigidité capsulaire ancienne","Une hyperlaxité ligamentaire"],"r":1,"e":"End-feel vide = douleur intense sans résistance physique → orientation pathologique (inflammation, néoplasie). Il oriente vers une pathologie, comme une inflammation ou une tumeur.","s":9},{"q":"La règle convexe-concave : si surface convexe mobile sur concave fixe, glissement et roulement vont :","o":["Dans le même sens","Dans des sens opposés","Glissement seul","Roulement seul"],"r":1,"e":"Convexe mobile sur concave fixe → glissement et roulement OPPOSÉS (ex : tête humérale qui monte en abduction).","s":9},{"q":"Le mouvement se définit comme :","o":["Un changement de position, par rapport à un repère","Une contraction musculaire, sans déplacement","Un déplacement du corps entier dans l'espace","Une variation du tonus musculaire, au repos ou à l'effort"],"r":0,"e":"Sans changement de position, le corps est au repos. Il se fait autour d'un axe et dans une direction.","s":9},{"q":"Dans la position anatomique de référence, les pieds sont :","o":["Écartés et parallèles, talons ensemble","Joints, gros orteils au contact","Écartés à la largeur des épaules","En rotation externe, pointes vers l'extérieur"],"r":0,"e":"Les avant-bras sont en supination, paumes vers l'avant, et le regard à l'horizon.","s":9},{"q":"L'axe du plan transversal est :","o":["Longitudinal ou vertical","Frontal ou transversal","Sagittal ou dorsal","Antéro-postérieur ou sagittal, vers l'avant"],"r":0,"e":"Le plan sagittal a un axe frontal, le plan frontal un axe sagittal.","s":9},{"q":"La flexion latérale du tronc se produit dans le plan :","o":["Frontal","Sagittal","Transversal","Oblique"],"r":0,"e":"L'abduction-adduction et l'inversion-éversion s'y produisent également.","s":9},{"q":"L'abduction et l'adduction horizontales se produisent dans le plan :","o":["Transversal","Sagittal","Frontal","Oblique"],"r":0,"e":"La pronation-supination et les rotations interne et externe s'y produisent aussi.","s":9},{"q":"Les syndesmoses et les gomphoses appartiennent aux articulations :","o":["Fibreuses, faites de collagène de type I, sans cavité","Cartilagineuses, avec du cartilage hyalin ou fibreux","Synoviales, avec une cavité et du liquide synovial articulaire","Semi-mobiles, avec un disque intermédiaire"],"r":0,"e":"Cette classification structurelle est reprise de Seeley et al. (2021).","s":9},{"q":"Les articulations synoviales contiennent un cartilage hyalin fait de :","o":["Collagène de type II","Collagène de type I","Élastine de type I","Collagène de types I et III mêlés"],"r":0,"e":"Les articulations fibreuses contiennent, elles, du collagène de type I.","s":9},{"q":"L'articulation occipito-atloïdienne est de type :","o":["Condylienne, donc biaxiale","Trochléenne, donc monoaxiale","Trochoïde, donc monoaxiale","Énarthrose, donc triaxiale"],"r":0,"e":"La radio-carpienne partage ce type ; la trapézo-métacarpienne est en selle.","s":9},{"q":"L'articulation fémoro-patellaire est de type :","o":["Trochléenne, monoaxiale","Arthrodie, sans axe","Condylienne, biaxiale","Énarthrose, triaxiale"],"r":0,"e":"L'huméro-ulnaire partage ce type ; les apophyses articulaires des vertèbres sont des arthrodies.","s":9},{"q":"La membrane fibreuse de la capsule articulaire :","o":["Est dense et protectrice, et contient des ligaments","Produit le liquide synovial, à l'intérieur de la capsule","Forme des bourses autour des tendons","Est dépourvue de tout nerf sensitif"],"r":0,"e":"Elle contient les nerfs sensitifs, mécanorécepteurs et nocicepteurs. C'est du tissu conjonctif dense.","s":9},{"q":"La membrane synoviale peut :","o":["S'étendre en bourse, comme à l'épaule","Contenir des ligaments, comme le genou","Être dépourvue de vaisseaux, comme le cartilage","Produire du cartilage, comme le périoste"],"r":0,"e":"Elle produit le liquide synovial, à l'intérieur de la capsule.","s":9},{"q":"Les articulations à un degré de liberté sont :","o":["Les trochlées et les trochoïdes","Les condyliennes et les selles","Les énarthroses","Les arthrodies"],"r":0,"e":"Deux degrés correspondent aux condyliennes et aux selles, trois aux énarthroses.","s":9},{"q":"Le roulement, parmi les mouvements accessoires :","o":["Va dans le sens du mouvement osseux, avec compression","Va en sens opposé au mouvement de l'os, avec traction","Exige une congruence parfaite des deux surfaces en contact","Est volontaire et contrôlé par le patient"],"r":0,"e":"Le glissement nécessite, lui, une congruence articulaire.","s":9},{"q":"Les mouvements accessoires sont régulés par :","o":["La tension des éléments périarticulaires","Le seul muscle, quelle que soit l'articulation","Le seul ligament, quelle que soit l'articulation","La volonté du patient, qui les commande consciemment"],"r":0,"e":"Le genou est à dominante capsulo-ligamentaire, l'épaule à dominante musculaire par la coiffe. Elle est capsulo-ligamentaire ou musculaire selon l'articulation.","s":9},{"q":"Un déficit d'extensibilité ou une lésion des plans de glissement entraîne :","o":["Une mécanique modifiée, moins d'amplitude, douleur","Une hypermobilité de l'articulation concernée","Une amélioration du glissement des surfaces","Aucune conséquence, ni fonctionnelle ni durable"],"r":0,"e":"C'est ce qui justifie le travail sur les mouvements accessoires.","s":9},{"q":"La règle convexe-concave citée dans ce cours provient de :","o":["Kisner et Colby, 2022","Kaltenborn seul, 1980","Maitland, 1986","Cyriax, en 1982, et ses élèves"],"r":0,"e":"Une surface concave glisse dans le même sens que le mouvement physiologique, une surface convexe en sens opposé.","s":9},{"q":"La mobilisation active-assistée associe :","o":["Une contraction du patient et une force externe","Une force externe seule, sans action du patient","Une contraction seule, sans aide externe","Une relaxation complète du patient"],"r":0,"e":"La mobilisation passive est réalisée par une autre personne, sans intervention active du patient.","s":9},{"q":"La circumduction se définit comme :","o":["Une combinaison de mouvements dans les trois plans","Une rotation pure autour de l'axe longitudinal","Une flexion-extension, dans le seul plan sagittal du corps","Un mouvement accessoire, intra-articulaire"],"r":0,"e":"Elle figure parmi les mouvements physiologiques, mesurables et volontaires. Elle n'est vraiment possible que dans les énarthroses.","s":9},{"q":"Les mouvements accessoires se distinguent des physiologiques par :","o":["Leur caractère intra-articulaire et involontaire","Leur grande amplitude, visible à l'œil nu","Leur mesurabilité au goniomètre","Leur contrôle volontaire, comme tout mouvement actif"],"r":0,"e":"Ils restent essentiels pour que les mouvements physiologiques soient considérés comme normaux. Ils ne sont pas mesurables.","s":9},{"q":"Les symphyses du bassin et des corps vertébraux correspondent à des :","o":["Des amphiarthroses, semi-mobiles","Des synarthroses, totalement immobiles","Des diarthroses, très mobiles","Des articulations fibreuses, fixes"],"r":0,"e":"Les synarthroses, immobiles, comme les sutures crâniennes, et les diarthroses, très mobiles, complètent cette classification fonctionnelle.","s":9},{"q":"L'articulation gléno-humérale est de type :","o":["Une arthrodie, plane","Une énarthrose, sphérique","Une trochlée, en poulie","Une trochoïde, cylindrique, en pivot"],"r":1,"e":"Gléno-humérale = ÉNARTHROSE (sphérique), triaxiale, mouvements amples mais couverture de seulement 25-30%.","s":10},{"q":"L'articulation acromio-claviculaire est :","o":["Une énarthrose, sphérique et triaxiale","Une arthrodie, à surfaces planes","Une articulation en selle","Une trochlée, en poulie"],"r":1,"e":"Acromio-claviculaire = ARTHRODIE (plate).","s":10},{"q":"L'articulation sterno-claviculaire est :","o":["Une énarthrose, sphérique et triaxiale","Une arthrodie, à surfaces planes","Une épiphysiarthrose, en selle","Une trochlée, en poulie"],"r":2,"e":"Sterno-claviculaire = en SELLE (épiphysiarthrose).","s":10},{"q":"La couverture de la cavité glénoïde par la tête humérale est d'environ :","o":["10%","25-30%","50%","80%"],"r":1,"e":"25-30% (Li et al., 2013) — d'où une grande mobilité mais une stabilité réduite. Le bourrelet l'augmente.","s":10},{"q":"Lors de l'abduction d'épaule, la phase 60°-120° implique :","o":["La gléno-humérale seule, sans la scapula","La gléno-humérale et la scapulo-thoracique","L'inclinaison du tronc seule, sans l'épaule","Aucune articulation de la ceinture"],"r":1,"e":"Phase 60°-120° : ajout de l'articulation SCAPULO-THORACIQUE. Phase 120°-180° : inclinaison du côté opposé.","s":10},{"q":"Pourquoi la rotation externe d'épaule est-elle nécessaire en fin de flexion/abduction ?","o":["Pour le confort du patient pendant le geste","Pour éviter le conflit avec l'acromion","Pour augmenter la rotation interne disponible","Sans raison mécanique, par simple habitude du geste"],"r":1,"e":"Rotation externe = évite le CONFLIT entre le tubercule majeur de l'humérus et l'acromion. Le tubercule majeur de l'humérus viendrait buter contre l'acromion.","s":10},{"q":"L'articulation huméro-ulnaire est :","o":["Énarthrose","Trochlée","Trochoïde","Plate"],"r":1,"e":"Huméro-ulnaire = TROCHLÉE, articulation monoaxiale (flexion/extension).","s":10},{"q":"La radio-ulnaire supérieure est :","o":["Une trochlée, pour la flexion du coude","Une trochoïde, pour la pronation et la supination","Une énarthrose, pour tous les mouvements","Une articulation en selle, pour l'opposition"],"r":1,"e":"Radio-ulnaire supérieure = TROCHOÏDE (cylindrique), permet la pronation/supination. Elle est cylindrique.","s":10},{"q":"Amplitude de flexion du coude :","o":["90°","120°","145°","180°"],"r":2,"e":"Flexion du coude ≈ 145°.","s":10},{"q":"Amplitudes pronation/supination de l'avant-bras :","o":["45°/45°","90°/90°","120°/120°","180°/180°"],"r":1,"e":"Pronation 90° / Supination 90°.","s":10},{"q":"L'articulation radio-carpienne (poignet) est de type :","o":["Une énarthrose, sphérique","Une trochoïde, cylindrique en pivot","Une condylienne, elliptique","Une trochlée, en poulie"],"r":2,"e":"Radio-carpienne = CONDYLIENNE, biaxiale (flexion/extension + déviations).","s":10},{"q":"Déviation ulnaire du poignet :","o":["20°","35°","70°","80°"],"r":1,"e":"Déviation ulnaire ≈ 35° ; déviation radiale ≈ 20°.","s":10},{"q":"L'articulation trapézo-métacarpienne du pouce est :","o":["Une énarthrose, sphérique et triaxiale","Une articulation en selle","Une arthrodie, plane","Une trochlée, en poulie"],"r":1,"e":"Trapézo-métacarpienne = articulation EN SELLE, permettant l'opposition du pouce. C'est une épiphysiarthrose, qui permet l'opposition.","s":10},{"q":"La hanche est de type :","o":["Une arthrodie, plane et glissante, sans axe","Une énarthrose, sphérique et triaxiale","Une trochlée, monoaxiale","Une articulation en selle, biaxiale"],"r":1,"e":"Hanche = ÉNARTHROSE sphérique triaxiale. Mais couverture acétabulaire = 70-83% (plus stable que l'épaule).","s":10},{"q":"La couverture acétabulaire (hanche) est d'environ :","o":["20-30%","50%","70-83%","100%"],"r":2,"e":"Couverture acétabulaire = 70-83% (Tannast et al., 2015). Comparée à 25-30% pour la gléno-humérale.","s":10},{"q":"Angle du col fémoral :","o":["90°","125°","180°","60°"],"r":1,"e":"Angle col fémoral = 125° (dissipation des forces).","s":10},{"q":"Flexion ACTIVE de hanche avec extension du genou :","o":["90°, par interférence des ischio-jambiers","140°, limitée par la capsule antérieure","180°, sans aucune limite musculaire","30°, limitée par le psoas raccourci"],"r":0,"e":"Avec EXTENSION du genou : 90° (les ischio-jambiers limitent). Avec FLEXION du genou : 125°. Passive : 140°.","s":10},{"q":"Le genou est composé de :","o":["Une fémoro-patellaire et une fémoro-tibiale","Une seule trochoïde, en pivot","Une seule énarthrose, sphérique","Une seule arthrodie, plane et glissante, sans axe"],"r":0,"e":"Genou = fémoro-patellaire (TROCHLÉE monoaxiale) + fémoro-tibiale (BICONDYLIENNE biaxiale). La fémoro-patellaire est trochléenne, la fémoro-tibiale bicondylienne.","s":10},{"q":"Lors de l'EXTENSION du genou, la jambe effectue automatiquement :","o":["Une rotation interne","Une rotation externe","Aucune rotation, seulement une extension","Une inversion du pied"],"r":1,"e":"Rotation axiale automatique : EXTENSION → rotation EXTERNE. FLEXION → rotation INTERNE.","s":10},{"q":"L'articulation tibio-tarsienne est :","o":["Une trochlée, monoaxiale","Une énarthrose, triaxiale et sphérique","Une articulation en selle","Une arthrodie, plane"],"r":0,"e":"Tibio-tarsienne = TROCHLÉE, monoaxiale (flexion dorsale/plantaire).","s":10},{"q":"Flexion dorsale de la cheville :","o":["20°","45°","70°","90°"],"r":0,"e":"Flexion dorsale ≈ 20° ; flexion plantaire ≈ 45°.","s":10},{"q":"L'inversion et l'éversion du pied se font à :","o":["À la tibio-tarsienne, en flexion","À la sous-talienne, entre talus et calcanéum","Au métatarse, entre les bases des métatarsiens","Au carpe, comme au poignet"],"r":1,"e":"Inversion (35°) / Éversion (20°) = articulation SOUS-TALIENNE (astragalo-calcanéenne).","s":10},{"q":"Le 1er orteil (gros orteil) a une extension de :","o":["20°","45°","90°","120°"],"r":2,"e":"1er orteil : flexion 45°, extension 90° (besoin pour la phase propulsive de la marche).","s":10},{"q":"Une précaution clé lors de mobilisation est :","o":["Aller vite, pour éviter la fatigue","Une tension progressive, sans provoquer de douleur","Forcer le mouvement jusqu'à la butée, pour gagner","Ignorer la pathologie, pour rester neutre"],"r":1,"e":"Tension PROGRESSIVE + éviter la douleur + individualiser l'articulation + éviter les compensations. Il faut aussi individualiser l'articulation et éviter les compensations.","s":10},{"q":"Concernant la tenue du kinésithérapeute, il faut :","o":["Des bijoux et des accessoires libres","Un uniforme, des cheveux attachés et des ongles coupés","Des vêtements amples, pour être à l'aise lors des transferts","Aucune règle particulière"],"r":1,"e":"Uniforme (haut/short), cheveux ATTACHÉS, ongles COUPÉS, sans accessoires, hygiène — sécurité et professionnalisme. On retire les accessoires et l'hygiène est de rigueur.","s":10},{"q":"L'amplitude normale de flexion du genou est ≈ :","o":["60°","90°","135°","180°"],"r":2,"e":"Flexion du genou ≈ 135° (peut atteindre 150-160° en flexion talon-fesse).","s":10},{"q":"L'amplitude d'abduction de l'épaule (gléno-humérale + scapulaire) :","o":["Environ 45°, en gléno-huméral","Environ 90°, en gléno-huméral pur","Environ 180°, en élévation totale","Environ 270°, avec le tronc"],"r":2,"e":"Élévation totale du membre supérieur ≈ 180° (90° gléno-huméral pur + 60° scapulaire + 30° rachidien).","s":10},{"q":"La dorsiflexion (flexion dorsale) de cheville normale est ≈ :","o":["5°","20°","60°","90°"],"r":1,"e":"Flexion dorsale ≈ 20° (genou tendu) / 30° (genou fléchi). Flexion plantaire ≈ 40-50°.","s":10},{"q":"L'opposition du pouce s'effectue à l'articulation :","o":["La métacarpo-phalangienne du pouce","La trapézo-métacarpienne, sellaire","L'interphalangienne proximale de l'index","La radio-carpienne, condylienne"],"r":1,"e":"Trapézo-métacarpienne = articulation sellaire (2 axes) qui permet le mouvement complexe d'opposition.","s":10},{"q":"La rotation externe de hanche (en décubitus dorsal, genou tendu) est ≈ :","o":["10°","45°","90°","180°"],"r":1,"e":"Rotation externe de hanche ≈ 45° (genou fléchi à 90° pour la mesure standard).","s":10},{"q":"Selon Li et al. (2013), la couverture gléno-humérale est de :","o":["25 à 30 %","50 %","70 %","10 %"],"r":0,"e":"D'où une grande mobilité et une moindre stabilité ; le bourrelet glénoïdien augmente la profondeur de la cavité.","s":10},{"q":"Dans les trois phases de l'abduction, la phase de 60 à 120° ajoute :","o":["L'articulation scapulo-thoracique","L'inclinaison controlatérale","La seule gléno-humérale","La sterno-claviculaire"],"r":0,"e":"De 0 à 60°, la gléno-humérale agit seule ; au-delà de 120°, s'ajoute l'inclinaison du côté opposé.","s":10},{"q":"La rotation externe dans les derniers degrés de flexion et d'abduction évite :","o":["Le contact du tubercule majeur et de l'acromion","Une luxation antérieure de la tête humérale","Une tendinite du long biceps dans sa gouttière bicipitale","Une raideur capsulaire postérieure"],"r":0,"e":"C'est un mécanisme protecteur automatique du complexe de l'épaule. Il s'agit du conflit sous-acromial.","s":10},{"q":"L'adduction horizontale de l'épaule atteint :","o":["140°, bras à 90° de flexion","30°, bras à 90° de flexion","90°, bras le long du corps","80°, coude fléchi à 90° et bras abduit"],"r":0,"e":"L'abduction horizontale atteint 30°, la rotation interne 90° et la rotation externe 80°, coude fléchi à 90°.","s":10},{"q":"L'articulation huméro-radiale est de type :","o":["Condylienne","Trochléenne","Trochoïde","Arthrodie"],"r":0,"e":"L'huméro-ulnaire est trochléenne et la radio-ulnaire supérieure trochoïde.","s":10},{"q":"La tête du radius s'articule avec :","o":["Le condyle huméral et la petite cavité sigmoïde","La trochlée humérale et la grande cavité sigmoïde","La grande cavité sigmoïde du cubitus seule","L'olécrane, par sa face antérieure"],"r":0,"e":"La trochlée humérale s'articule avec la grande cavité sigmoïde de l'ulna.","s":10},{"q":"Lors de la flexion du poignet, la répartition entre radio-carpienne et carpe est de :","o":["60/40 %","40/60 %","50/50 %","80/20 %"],"r":0,"e":"En extension, la proportion s'inverse en 40/60 %.","s":10},{"q":"Les articulations intercarpiennes sont :","o":["Des arthrodies, qui permettent un glissement","Des condyliennes, à deux axes","Des trochléennes, en poulie, à un seul axe de rotation","Des énarthroses, à trois axes"],"r":0,"e":"La radio-carpienne est, elle, condylienne.","s":10},{"q":"Les articulations métacarpo-phalangiennes sont :","o":["Condyliennes","Trochléennes","Planes","En selle"],"r":0,"e":"Les interphalangiennes sont trochléennes et les carpo-métacarpiennes planes.","s":10},{"q":"L'abduction du pouce atteint :","o":["40 à 50°","80°","90°","20°"],"r":0,"e":"L'adduction atteint 80° ; la trapézo-métacarpienne est une articulation en selle.","s":10},{"q":"Selon Tannast et al. (2015), la couverture acétabulaire est de :","o":["70 à 83 %","25 à 30 %","50 %","95 %"],"r":0,"e":"Le bourrelet acétabulaire augmente cette couverture d'environ 30 %.","s":10},{"q":"L'angle du col fémoral est de :","o":["125°","135°","110°","145°"],"r":0,"e":"La hanche est une énarthrose triaxiale, associant tête fémorale et acétabulum.","s":10},{"q":"La flexion active de hanche avec extension du genou atteint :","o":["90°, par interférence des ischio-jambiers","125°, limitée par la capsule antérieure","140°, limitée par le contact des tissus","45°, limitée par le psoas raccourci et rétracté"],"r":0,"e":"Avec flexion du genou elle atteint 125°, et 140° en passif.","s":10},{"q":"L'adduction pure de hanche :","o":["N'existe pas seule et se combine à une flexion ou extension","Atteint 45°, comme l'abduction dans le même plan","Se fait dans le plan sagittal, autour d'un axe frontal","Est indépendante de la flexion et de l'extension"],"r":0,"e":"L'abduction atteint 45° et l'adduction 15°.","s":10},{"q":"L'articulation fémoro-patellaire est de type :","o":["Trochléenne, monoaxiale","Condylienne, biaxiale","Arthrodie, plane et glissante","Énarthrose, triaxiale"],"r":0,"e":"Elle complète l'articulation fémoro-tibiale dans le complexe du genou.","s":10},{"q":"La flexion des interphalangiennes proximales des doigts atteint :","o":["100°","90°","80°","120°"],"r":0,"e":"Les métacarpo-phalangiennes fléchissent à 90° et les interphalangiennes distales à 80°.","s":10},{"q":"Les mouvements physiologiques de l'épaule cités selon Kapandji (2019) comprennent :","o":["Flexion, extension, abduction, rotations et circumduction","Flexion et extension seulement, dans le plan sagittal","Les seules rotations, interne et externe, coude fléchi au corps","Les seuls mouvements du plan frontal"],"r":0,"e":"Cette liste couvre les trois plans de l'espace. S'y ajoutent l'hyperextension, l'adduction et les mouvements horizontaux.","s":10},{"q":"L'articulation sterno-claviculaire est de type :","o":["Une épiphysiarthrose, en selle","Une arthrodie, à surfaces planes","Une énarthrose, sphérique","Une trochléenne, en poulie"],"r":0,"e":"L'acromio-claviculaire est une arthrodie et la gléno-humérale une énarthrose.","s":10},{"q":"La pronation et la supination de l'avant-bras se font :","o":["Dans le plan transversal, autour d'un axe vertical","Dans le plan sagittal, autour d'un axe frontal","Dans le plan frontal, autour d'un axe antéro-postérieur","Sans axe défini, par glissement des os"],"r":0,"e":"La flexion du coude atteint 145°, dans le plan sagittal autour d'un axe frontal. Chacune atteint 90°.","s":10},{"q":"Parmi les os du carpe cités dans cette fiche figurent :","o":["Le lunatum, le triquétrum, le grand os et l'unciforme","Le scaphoïde et le pisiforme, seulement","Le trapèze et le trapézoïde, à l'exclusion de tous les autres","Les huit os du carpe, sans distinction"],"r":0,"e":"Le mouvement du poignet associe la radio-carpienne et le glissement des os du carpe.","s":10},{"q":"Combien d'ECTS valent l'UC Stratégies d'évaluation et d'intervention en physiothérapie I ?","o":["4","6","8","12"],"r":2,"e":"8 ECTS pour 216 h de travail total, 120 h de contact.","s":11},{"q":"Combien de domaines thématiques composent l'UC ?","o":["3","4","5","7"],"r":2,"e":"5 domaines : Massage, Mob.Art.Physio, Anatomie palpatoire, PTAM, Corps et conscience.","s":11},{"q":"Quel module a la pondération la PLUS BASSE ?","o":["Massage (25%)","Corps et conscience (10%)","PTAM (15%)","Anatomie palpatoire (25%)"],"r":1,"e":"Corps et conscience = 10% (la plus basse). Massage, Anat. palpatoire et Mob.Art.Physio = 25% chacun.","s":11},{"q":"Quelles techniques de massage sont mentionnées ?","o":["L'acupression, le reiki et la réflexologie","L'effleurage, le pétrissage et la friction","Le massage thaï, et seulement celui-ci","Le kinésio-taping, en bandes élastiques"],"r":1,"e":"Techniques de mobilisation tissulaire : EFFLEURAGE, PÉTRISSAGE, FRICTION.","s":11},{"q":"Note minimale pour valider l'UC par évaluation continue (par module) :","o":["8","10","12","14"],"r":1,"e":"Note minimale = 10/20 dans CHAQUE module pour être dispensé de l'examen final.","s":11},{"q":"Quelle méthodologie d'examen pratique est utilisée ?","o":["Des QCM uniquement, à la fin de chaque semestre","L'OSCE, examen clinique structuré par stations","Une dissertation écrite, en quatre heures","Un exposé oral devant un jury"],"r":1,"e":"OSCE = stations/scénarios pour tester compétences cliniques, communication, raisonnement, compétences pratiques.","s":11},{"q":"Le modèle pédagogique POGIL signifie :","o":["Practical Oriented Group Inquiry Learning","Process Oriented Guided Inquiry Learning","Patient Oriented Group Inquiry Learning","Problem Oriented Guided Inquiry Lecture"],"r":1,"e":"POGIL = Process Oriented Guided Inquiry Learning.","s":11},{"q":"CBL signifie :","o":["Clinical Bedside Learning","Case Based Learning","Care Based Learning","Cognitive Behavioral Learning"],"r":1,"e":"CBL = Case Based Learning, pour rapprocher la théorie de la pratique clinique.","s":11},{"q":"PTAM signifie :","o":["Positionnement, Transferts, Anatomie et Massage","Positionnement, Transferts et Aides à la Marche","Pratiques Théoriques d'Aide à la Mobilité et à la Marche","Prévention, Traitement et Accompagnement Médical"],"r":1,"e":"PTAM = Positionnement, Transferts et Aides à la Marche.","s":11},{"q":"Combien d'heures de pratique et laboratoire (PL) sont prévues ?","o":["30 h","60 h","90 h","120 h"],"r":2,"e":"90 h de PL + 30 h de TP = 120 h de contact total.","s":11},{"q":"L'UC se déroule à quel semestre ?","o":["1er semestre, 1ère année","2e semestre, 1ère année","1er semestre, 2e année","2e semestre, 2e année"],"r":0,"e":"1er semestre, 1ère année de Licence en physiothérapie.","s":11},{"q":"Quel module n'est évalué QUE théoriquement ?","o":["Le module de mobilisation tissulaire","Le module de mobilisation articulaire physiologique","Le module corps et conscience","Le module de positionnements et transferts"],"r":2,"e":"Corps et conscience = théorique uniquement (10% de la note finale). Il pèse 10 % de la note finale.","s":11},{"q":"Quel module n'est évalué QUE pratiquement ?","o":["Massage","Anatomie palpatoire","Corps et conscience","PTAM"],"r":1,"e":"Anatomie palpatoire = uniquement pratique (25%).","s":11},{"q":"Quelle enseignante est la responsable de l'UC ?","o":["Enseignante B","Enseignante A","Enseignante C","Enseignante F"],"r":1,"e":"Enseignante A = enseignante responsable, professeure assistante.","s":11},{"q":"L'enseignante avec le plus grand nombre d'heures (25 h) est :","o":["Enseignante A (20 h)","Enseignante B (15 h)","Enseignante C (25 h)","Enseignante F"],"r":2,"e":"Enseignante C = 25 h (6 TP + 19 PL), maximum des trois enseignantes.","s":11},{"q":"Quel pourcentage d'heures de contact se fait en présence physique ?","o":["50%","75%","100%","0%"],"r":2,"e":"100% en présence (modalité présentielle).","s":11},{"q":"Le total d'heures de travail demandé à l'étudiant est :","o":["120 h","150 h","216 h","300 h"],"r":2,"e":"216 h totales (120 h de contact + travail personnel).","s":11},{"q":"L'effleurage est :","o":["Une mobilisation articulaire passive, en fin d'amplitude","Une technique de massage, ou mobilisation tissulaire","Une aide à la marche, pour le patient","Un transfert, du lit au fauteuil"],"r":1,"e":"L'EFFLEURAGE est une technique de mobilisation tissulaire (massage), avec le pétrissage et la friction.","s":11},{"q":"Pratiquer la palpation fait partie de quel module ?","o":["Massage","Anatomie palpatoire","Corps et conscience","PTAM"],"r":1,"e":"Module ANATOMIE PALPATOIRE = identification et palpation des structures anatomiques.","s":11},{"q":"L'UC vise la maîtrise des techniques de mobilisation des :","o":["Articulations centrales uniquement","Articulations périphériques","Aucune articulation","Os longs uniquement"],"r":1,"e":"Mob.Art.Physio. = techniques de mobilisation des ARTICULATIONS PÉRIPHÉRIQUES.","s":11},{"q":"L'examen OSCE évalue :","o":["Les connaissances livresques seules","La pratique, la communication et le raisonnement clinique","L'endurance physique de l'étudiant, sur plusieurs stations","Aucun critère défini à l'avance"],"r":1,"e":"OSCE = compétences cliniques, communication, raisonnement clinique, compétences pratiques.","s":11},{"q":"Tous les moments d'évaluation sont :","o":["Facultatifs","Obligatoires","Au choix","Annulables"],"r":1,"e":"Tous les moments d'évaluation sont OBLIGATOIRES.","s":11},{"q":"Une absence de validation d'un module entraîne :","o":["L'UC validée quand même, par compensation entre les modules","L'inscription à l'examen final sur tout le contenu","Une compensation automatique avec les autres UC","L'échec définitif à l'UC, sans rattrapage"],"r":1,"e":"Si la note minimale n'est pas atteinte dans chaque module → examen final OBLIGATOIRE sur TOUT le contenu.","s":11},{"q":"Mobilité précoce au lit fait partie de :","o":["Le module de massage et de toucher","Le module des transferts et de la marche","Le module d'anatomie palpatoire du membre","Le module corps et conscience"],"r":1,"e":"PTAM = Positionnement, Transferts et Aides à la Marche — inclut la mobilité précoce au lit. C'est le module PTAM.","s":11},{"q":"Le concept du toucher comme facilitateur de la relation thérapeutique est étudié dans :","o":["Massage","Corps et conscience","Mob.Art.Physio.","PTAM"],"r":1,"e":"Module CORPS ET CONSCIENCE = concept du toucher, interprétation, toucher comme facilitateur de la relation thérapeutique.","s":11},{"q":"Un OSCE évalue principalement :","o":["Les connaissances théoriques seules","Les compétences pratiques, sur stations","Le quotient intellectuel de l'étudiant","La culture générale, médicale ou non"],"r":1,"e":"OSCE (Objective Structured Clinical Examination) = circuit de stations courtes évaluant un geste/compétence précis. Les stations sont standardisées.","s":11},{"q":"L'EAIF I correspond à quelle année de formation ?","o":["La 3ᵉ année, ou L3","La 1ʳᵉ année, ou L1","La 4ᵉ année, ou M1","La 6ᵉ année, ou D1"],"r":1,"e":"EAIF I = unité curriculaire du 1er cycle (L1) en kinésithérapie.","s":11},{"q":"La répartition de la note du module mobilisation articulaire est :","o":["50 % de la note finale","25 % de la note finale","100 % de la note finale","5 % de la note finale"],"r":1,"e":"Mobilisation articulaire = 25 % de la note finale de l'UC EAIF I.","s":11},{"q":"Le module Corps et Conscience pèse :","o":["1 % de la note","10 % de la note","50 %","100 %"],"r":1,"e":"Corps et Conscience = 10 % de la note finale.","s":11},{"q":"Le crédit ECTS de l'UC EAIF I est :","o":["1 ECTS","8 ECTS","30 ECTS","60 ECTS"],"r":1,"e":"EAIF I = 8 ECTS (charge de travail étudiant ≈ 200-240 h, équivalent semestre dense).","s":11},{"q":"L'UC EAIF I comporte au total :","o":["216 heures de travail, dont 120 de contact","120 heures de travail, dont 90 de contact","216 heures de contact, sans travail personnel prévu","90 heures de travail, dont 30 de contact"],"r":0,"e":"La présence aux heures de contact est de 100 %.","s":11},{"q":"Les heures de contact se répartissent en :","o":["30 h théorique-pratique et 90 h pratique et laboratoire","90 h théorique et 30 h pratique et laboratoire","60 h théorique-pratique et 60 h de laboratoire","120 h de pratique et de laboratoire, sans théorie"],"r":0,"e":"La part pratique et laboratoire représente donc les trois quarts des heures de contact.","s":11},{"q":"La responsable de l'UC est :","o":["Enseignante A","Enseignante B","Enseignante C","Enseignante G"],"r":0,"e":"Elle assure 20 heures, réparties en 6 h TP et 14 h PL.","s":11},{"q":"L'enseignante assurant le plus grand nombre d'heures est :","o":["Enseignante C, avec 25 heures","Enseignante A, avec 20 heures","Enseignante B, avec 15 heures","Enseignante G"],"r":0,"e":"Ses 25 heures se répartissent en 6 h TP et 19 h PL.","s":11},{"q":"L'objectif général de l'UC est d'acquérir des compétences :","o":["Dans le domaine des sciences du mouvement","En anatomie descriptive et topographique","En physiologie de l'effort et du repos","En pathologie médicale et chirurgicale"],"r":0,"e":"Cette formulation situe l'UC au cœur de l'identité professionnelle. Ce domaine est au cœur du modèle identitaire de la physiothérapie.","s":11},{"q":"Parmi les compétences ciblées, le cours cite :","o":["Repérer les changements d'alignement postural chez l'alité","Rédiger un article scientifique","Poser un diagnostic médical, avec l'imagerie et la biologie","Prescrire des médicaments antalgiques"],"r":0,"e":"S'y ajoutent massage, mobilisation articulaire, palpation, mobilité précoce, positionnement, transferts, aides à la marche et toucher thérapeutique.","s":11},{"q":"Les cinq domaines thématiques de l'UC sont :","o":["Massage, mobilisation, palpation, transferts et corps","Massage, anatomie, physiologie, pathologie et pratique","Théorie, pratique, laboratoire, stage et évaluation","Évaluation, intervention, prévention, éducation et recherche"],"r":0,"e":"Ils structurent à la fois le contenu et l'évaluation. Mobilisation tissulaire, mobilisation articulaire physiologique, anatomie palpatoire, PTAM, corps et conscience.","s":11},{"q":"Parmi les concepts fondamentaux du contenu programmatique figure :","o":["Les bases neurophysiologiques de la thérapie manuelle","La biomécanique articulaire du rachis","L'anatomie descriptive du membre supérieur","La physiologie de l'effort chez le sportif de haut niveau"],"r":0,"e":"La main comme moyen thérapeutique et l'importance du toucher en font également partie.","s":11},{"q":"L'objectif des modèles pédagogiques employés est :","o":["Rapprocher la théorie de la pratique clinique","Accélérer l'apprentissage des étudiants","Réduire le nombre d'heures de cours en présentiel","Individualiser le parcours de chacun"],"r":0,"e":"Les cours pratiques reposent sur la dynamique de groupe, la démonstration et les simulations entre étudiants.","s":11},{"q":"Les pratiques réflexives des cours théoriques comprennent :","o":["L'analyse de documents et la résolution de problèmes","Les seuls exposés magistraux","Les seuls travaux dirigés, en petits groupes","Les seuls examens écrits de fin de semestre, notés"],"r":0,"e":"Elles s'accompagnent de discussions étudiants-enseignant avec exemples pratiques. Les fiches de travail et les activités de recherche en font partie.","s":11},{"q":"Le module évalué uniquement en pratique est :","o":["L'anatomie palpatoire","Le massage","La mobilisation articulaire","Le PTAM"],"r":0,"e":"Il pèse 25 %, comme le massage et la mobilisation articulaire, évalués en théorique et pratique.","s":11},{"q":"La pondération du module PTAM est de :","o":["15 %","25 %","10 %","30 %"],"r":0,"e":"Massage, anatomie palpatoire et mobilisation articulaire pèsent chacun 25 %.","s":11},{"q":"Parmi les contenus du module PTAM figurent :","o":["Positionnements, transferts et aides à la marche","Le seul positionnement dans le lit","Les seuls transferts, du lit au fauteuil et au sol","Les seules aides à la marche"],"r":0,"e":"C'est le module le plus large en contenu, malgré une pondération de 15 %. Mobilité précoce, types de marche et transport en fauteuil roulant en font aussi partie.","s":11},{"q":"Les techniques de massage citées au programme sont :","o":["Effleurage, pétrissage et friction","Effleurage, tapotement et vibration","Pétrissage et tapotement","Friction, vibration et drainage"],"r":0,"e":"L'examen du patient avant application en fait également partie.","s":11},{"q":"Le module Corps et conscience porte sur :","o":["Le toucher, ses types et son rôle dans la relation","La palpation des structures, osseuses et musculaires","La mobilisation articulaire passive","Le positionnement du patient alité"],"r":0,"e":"C'est le cinquième domaine thématique de l'UC.","s":11},{"q":"Le module d'anatomie palpatoire porte sur :","o":["L'anatomie topographique et la palpation des structures","La mobilisation articulaire physiologique","Le massage et ses techniques","Les transferts et les aides à la marche, en pratique clinique"],"r":0,"e":"Il est évalué uniquement en pratique.","s":11},{"q":"L'UC EAIF I se déroule :","o":["En 1ʳᵉ année, au 1ᵉʳ semestre, en régime obligatoire","En 1ʳᵉ année, au 2ᵉ semestre, en régime optionnel","En 2ᵉ année, au 1ᵉʳ semestre, en régime obligatoire","En option, au choix de l'étudiant, sur toute la licence"],"r":0,"e":"Elle vaut 8 ECTS dans le cycle de licence en physiothérapie. Elle est semestrielle.","s":11},{"q":"Enseignante B assure :","o":["15 heures, soit 8 h de TP et 7 h de PL","20 heures, toutes en TP","25 heures, soit 15 h de TP et 10 h de PL au total","10 heures, toutes en laboratoire"],"r":0,"e":"Elle est professeure coordinatrice, docteure et spécialiste au titre du DL 206/2009.","s":11},{"q":"Le contenu sur la mobilisation articulaire physiologique porte sur :","o":["Les techniques de mobilisation des articulations périphériques","Les mobilisations vertébrales, du rachis cervical au sacrum","Les manipulations à haute vélocité du rachis","Les tractions mécaniques du rachis lombaire"],"r":0,"e":"Effets physiologiques, indications, précautions et contre-indications sont traités dans les concepts fondamentaux.","s":11},{"q":"Les cours pratiques de l'UC reposent notamment sur :","o":["Des simulations entre étudiants","Des exposés magistraux en amphithéâtre","Des stages cliniques dans les services hospitaliers","Des travaux écrits à rendre"],"r":0,"e":"La dynamique de groupe et les moments de démonstration les complètent. Les étudiants y mettent en œuvre les techniques.","s":11},{"q":"Quel est l'objectif PRINCIPAL des positionnements en kinésithérapie ?","o":["Renforcer la musculature du patient alité","Prévenir les altérations liées à l'alitement","Stimuler la croissance osseuse","Améliorer la digestion par le changement de position fréquent"],"r":1,"e":"Les positionnements visent essentiellement la PRÉVENTION des altérations musculo-squelettiques, circulatoires, respiratoires et cutanées. Les altérations sont musculo-squelettiques, circulatoires, respiratoires et cutanées.","s":12},{"q":"À quelle fréquence faut-il changer la position d'un patient alité pour prévenir les escarres ?","o":["Toutes les heures","Toutes les 2 heures","Toutes les 4 heures","Toutes les 6 heures"],"r":1,"e":"La règle est un changement de position TOUTES LES 2 HEURES, ce qui correspond à la durée de pression prolongée (2-3h) qui provoque les lésions.","s":12},{"q":"Une escarre de stade III se caractérise par :","o":["Un érythème non blanchissable sur peau intacte","Une destruction partielle de l'épiderme ou du derme","Une destruction totale de la peau, avec un cratère","Une atteinte musculaire et osseuse, avec ou sans cratère"],"r":2,"e":"Stade III = destruction TOTALE de la peau avec nécrose sous-cutanée et formation de cratère. Le stade IV ajoute l'atteinte musculaire/osseuse. Le tissu sous-cutané est nécrosé.","s":12},{"q":"Quelle zone N'EST PAS typiquement à risque d'escarre en décubitus dorsal ?","o":["Le sacrum, au milieu","Le calcanéum, sous le talon","La tubérosité ischiatique","L'olécrane, au coude"],"r":2,"e":"La tubérosité ischiatique est une zone à risque en position ASSISE, pas en décubitus dorsal.","s":12},{"q":"En décubitus latéral, les membres inférieurs doivent être :","o":["En extension complète, sans coussin entre les genoux","Fléchis, avec un coussin entre les genoux","Croisés, le genou supérieur en avant","Suspendus hors du lit, en traction"],"r":1,"e":"Les MI sont en flexion, avec un coussin entre les genoux pour créer un plan horizontal et éviter les frottements.","s":12},{"q":"Le décubitus ventral est :","o":["La position de référence de tout patient alité","Une position bien tolérée, à proposer à tous","Une position d'exception, généralement mal tolérée","Une position utilisée pour les transferts, en routine"],"r":2,"e":"Le décubitus ventral est une position d'EXCEPTION utilisée dans des situations spécifiques (chirurgie, insuffisance respiratoire grave) et généralement mal tolérée.","s":12},{"q":"En décubitus dorsal, le membre supérieur du patient totalement dépendant doit être placé :","o":["Le long du corps en rotation interne","En légère abduction et rotation externe","Au-dessus de la tête","Croisé sur la poitrine"],"r":1,"e":"Le MS est placé en LÉGÈRE ABDUCTION et ROTATION EXTERNE pour respecter l'alignement physiologique.","s":12},{"q":"Combien de temps de pression continue suffit pour provoquer une escarre ?","o":["30 minutes","1 heure","2 à 3 heures","12 heures"],"r":2,"e":"Une pression prolongée de 2 à 3 HEURES suffit à créer une lésion par défaut d'irrigation.","s":12},{"q":"Quel principe FONDAMENTAL régit la mobilité précoce ?","o":["Aller le plus vite possible, pour gagner du temps","Ne pas traîner le patient ni tirer sur les articulations","Toujours utiliser la force maximale, pour sécuriser le geste","Ignorer les capacités du patient, pour standardiser"],"r":1,"e":"Principes-clés : NE PAS TRAÎNER, NE PAS TIRER sur les articulations, éviter les amplitudes extrêmes, favoriser l'alignement.","s":12},{"q":"Lors du roulement avec assistance, où sont placées les mains du kinésithérapeute ?","o":["Aux pieds et à la tête, aux deux extrémités","Sur la ceinture scapulaire et la ceinture pelvienne","Sur les deux genoux, pour faire basculer le bassin d'un bloc","Aux poignets, pour tirer le patient vers soi"],"r":1,"e":"Une main soutient la CEINTURE SCAPULAIRE, l'autre la CEINTURE PELVIENNE pour effectuer le roulement EN BLOC.","s":12},{"q":"Quelle est une cause typique d'escarre ?","o":["Un exercice physique intense et prolongé","Un stress mécanique sur les reliefs osseux","Une bonne hydratation de la peau","Un massage régulier des points d'appui"],"r":1,"e":"Les escarres résultent du stress mécanique sur les zones osseuses saillantes lors d'une pression prolongée.","s":12},{"q":"Le stade I d'une escarre se caractérise par :","o":["Une nécrose musculaire, sous une peau encore intacte","Un cratère profond, avec nécrose sous-cutanée","Un érythème non blanchissable sur peau intacte","Une perte totale de la peau, sans cratère"],"r":2,"e":"Stade I = érythème NON BLANCHISSABLE sur peau encore INTACTE, premier signe d'alerte.","s":12},{"q":"En décubitus latéral du patient totalement dépendant, la main du côté inférieur doit être :","o":["Suspendue dans le vide, hors du lit","Glissée sous la fesse du même côté","Appuyée sur l'oreiller de la tête","Croisée sur la poitrine, coude fléchi à angle droit"],"r":2,"e":"La main inférieure latérale est appuyée sur l'oreiller de la tête, l'épaule étant légèrement avancée.","s":12},{"q":"Parmi ces facteurs de risque d'escarre, lequel est CHRONIQUE ?","o":["Mouvement excessif","Diabète","Activité sportive","Bonne nutrition"],"r":1,"e":"Le diabète est une affection chronique compromettant l'irrigation vasculaire ET la sensibilité, double facteur de risque.","s":12},{"q":"L'option 1 du décubitus latéral côté affecté place le coude en :","o":["Extension","Flexion","Rotation interne","Pronation"],"r":1,"e":"Option 1 = coude en FLEXION. Option 2 = coude en EXTENSION.","s":12},{"q":"Quel matériel est utilisé en prévention des escarres ?","o":["Un lit articulé et du matériel anti-escarres","Un bandage compressif des membres","Une attelle plâtrée, posée sur les deux jambes","Une ceinture lombaire rigide"],"r":0,"e":"Les lits articulés et le matériel anti-escarres (matelas, coussins spéciaux) font partie des mesures préventives.","s":12},{"q":"La mobilité précoce vise à promouvoir :","o":["La dépendance complète","L'image corporelle et l'autonomie","L'immobilisation prolongée","L'utilisation exclusive de machines"],"r":1,"e":"Mobilité précoce = développement de l'image corporelle, schémas moteurs normaux, autonomie et indépendance.","s":12},{"q":"En décubitus ventral, quelle zone est typiquement à risque de pression ?","o":["Sacrum","Tubérosité ischiatique","Rotule","Olécrane"],"r":2,"e":"Zones à risque en décubitus ventral : visage/oreille/front, épaule, épine iliaque, ROTULE.","s":12},{"q":"Pourquoi éviter le poids des vêtements au niveau tibio-tarsien en décubitus dorsal ?","o":["Pour une question de mode et de confort du patient","Pour éviter une flexion plantaire forcée","Pour faciliter le transfert du lit","Pour faciliter le lavage des draps"],"r":1,"e":"Le poids des draps/vêtements peut forcer une flexion plantaire (pied tombant). Il faut préserver une position neutre, talons non appuyés. On préserve la position neutre, talons non appuyés.","s":12},{"q":"Un patient en fauteuil roulant prolongé est principalement à risque d'escarre :","o":["Au front et au nez, par appui sur la tablette du fauteuil","À l'épaule, par appui sur le dossier","À la tubérosité ischiatique et à la région sacrée","Aux orteils, par appui sur les repose-pieds"],"r":2,"e":"Position assise prolongée = zones à risque : tubérosité ischiatique, région sacrée, région poplitée, métatarses.","s":12},{"q":"L'autocontrôle au miroir est utile pour :","o":["Se coiffer avant les soins","Inspecter les zones de pression difficiles à voir","Vérifier sa posture assise au fauteuil","Se maquiller, pour retrouver une bonne image de soi"],"r":1,"e":"Le miroir permet à un patient autonome (paraplégique p.ex.) d'INSPECTER les zones de pression non visibles directement.","s":12},{"q":"Lors d'un transfert ou d'une mobilité précoce, il faut TOUJOURS :","o":["Forcer le mouvement, pour gagner du temps","Attendre la réponse motrice du patient","Faire le geste seul, sans le patient","Aller vite, pour ne pas fatiguer le patient alité"],"r":1,"e":"L'aide dépend des capacités du patient — il faut TOUJOURS attendre sa réponse motrice avant d'agir.","s":12},{"q":"Quelle structure cutanée est principalement touchée au stade II d'une escarre ?","o":["Le muscle, sous l'hypoderme","L'os, par sa face corticale profonde","L'épiderme ou le derme","Le périoste, autour de l'os"],"r":2,"e":"Stade II = destruction partielle, atteinte de l'ÉPIDERME et/ou du DERME (plaie, peau rouge œdémateuse douloureuse).","s":12},{"q":"Combien d'options de positionnement existe-t-il pour le décubitus latéral du côté affecté ?","o":["1","2","3","4"],"r":2,"e":"Il existe 3 OPTIONS (variantes) pour le décubitus latéral du côté affecté selon la position du coude et des MS.","s":12},{"q":"L'incontinence urinaire/fécale est un facteur de risque d'escarre parce que :","o":["Elle augmente la mobilité du patient au lit","L'urine et les selles irritent et macèrent la peau","Elle améliore la circulation cutanée par l'humidité de la peau","Elle réduit la friction de la peau sur les draps"],"r":1,"e":"L'urine et les selles macèrent la peau et l'irritent, fragilisant la barrière cutanée et favorisant les escarres.","s":12},{"q":"Le stade 1 d'escarre se caractérise par :","o":["Une plaie profonde, avec un cratère souvent infecté","Un érythème qui ne blanchit pas à la pression","Une nécrose sous-cutanée étendue","Un os exposé au fond de la plaie"],"r":1,"e":"Stade 1 : érythème non blanchissant à la pression, peau intacte. Premier signal d'alerte. La peau reste intacte.","s":12},{"q":"Les zones les plus à risque d'escarre en décubitus dorsal sont :","o":["Les coudes seulement, en appui sur le matelas du lit","Les talons, le sacrum, l'occiput et les omoplates","Les genoux et les rotules, en avant","Les mains, les doigts et les poignets"],"r":1,"e":"DD : talons (++), sacrum, occiput, omoplates, coudes — zones de pression osseuses.","s":12},{"q":"En semi-Fowler, l'inclinaison du tronc est généralement :","o":["10°","45° à 60°","90° (assis)","-30°"],"r":1,"e":"Semi-Fowler ≈ 45-60° → travail respiratoire, alimentation, observation, mais ↑ pression sacrée.","s":12},{"q":"La fréquence recommandée de changement de position au lit est :","o":["1 fois/jour","Toutes les 2 à 3 heures","Toutes les 30 min","Jamais"],"r":1,"e":"Changement toutes les 2-3 h → prévention escarres (réduit la pression continue sur les mêmes zones).","s":12},{"q":"Pour prévenir l'équin chez un patient alité, on installe :","o":["Un poids de 2 kg posé sur les pieds","Un cale-pieds qui maintient la cheville à 90°","Les pieds laissés en flexion plantaire libre","Rien, le pied se replaçant seul pendant le sommeil de la nuit"],"r":1,"e":"Cale-pieds ou attelle pour maintenir la cheville à 90° → évite la rétraction du triceps sural (pied tombant).","s":12},{"q":"Parmi les objectifs fonctionnels des positionnements, le cours cite :","o":["Donner une notion du corps dans son ensemble","Prévenir les altérations cutanées","Prévenir les modifications circulatoires","Prévenir les altérations respiratoires"],"r":0,"e":"Les objectifs préventifs concernent l'amplitude articulaire, la circulation, la respiration et la peau.","s":12},{"q":"Les positionnements de base :","o":["Peuvent être modifiés et adaptés aux besoins de chacun","Sont figés une fois pour toutes, quel que soit le patient","Sont universels et identiques pour tous","Ne dépendent pas de l'état du patient"],"r":0,"e":"Ils doivent s'adapter à la progression du patient.","s":12},{"q":"Parmi les facteurs de risque d'escarre liés à une mauvaise irrigation, le cours cite :","o":["Le diabète et les maladies vasculaires","L'incontinence urinaire et fécale chronique","Les affections mentales et cognitives","L'âge avancé, à lui seul"],"r":0,"e":"Les troubles sensitifs du diabète, de l'AVC et des neuropathies périphériques constituent un autre facteur.","s":12},{"q":"L'incontinence urinaire et fécale est un facteur de risque d'escarre car :","o":["Elle expose la peau à des fluides irritants","Elle réduit la mobilité au lit","Elle altère l'état nutritionnel","Elle diminue la sensibilité cutanée du bassin"],"r":0,"e":"Le contact avec sueur, sang, urine et selles figure parmi les causes d'escarre.","s":12},{"q":"Le mécanisme de l'escarre associe :","o":["Contact, pression et frottement, par défaut d'irrigation","La seule pression, quelle qu'en soit la durée","Le seul frottement des draps sur la peau","La seule irritation cutanée, par la sueur et l'urine du patient"],"r":0,"e":"Une pression prolongée de 2 à 3 heures sur les zones osseuses saillantes suffit. L'irritation cutanée peut aussi intervenir.","s":12},{"q":"Le frottement à l'origine des escarres provient notamment :","o":["Des plis des vêtements et des draps","Des coussins mal placés","Du matelas, trop ferme ou trop mou pour le patient","Des mobilisations passives"],"r":0,"e":"C'est pourquoi les soins vestimentaires font partie des mesures de prévention.","s":12},{"q":"Le stade II d'escarre se caractérise par :","o":["Une destruction partielle, avec une plaie rouge","Un érythème non blanchissable sur une peau encore intacte","Un cratère, avec une nécrose sous-cutanée","Une lésion musculaire ou osseuse"],"r":0,"e":"Le stade III forme un cratère susceptible d'infection et le stade IV atteint muscles, os ou structures de soutien. Elle touche l'épiderme et/ou le derme ; la peau est œdémateuse et douloureuse.","s":12},{"q":"Parmi les affections chroniques favorisant les escarres par troubles sensitifs, le cours cite :","o":["Le diabète, l'AVC et la neuropathie périphérique","L'arthrose, la polyarthrite rhumatoïde et l'ostéoporose","L'insuffisance cardiaque et l'HTA","L'asthme et la bronchite chronique"],"r":0,"e":"L'incapacité à mobiliser ses segments, comme dans la paraplégie ou la sclérose en plaques, constitue un autre facteur.","s":12},{"q":"Parmi les objectifs des positionnements, le cours cite la stimulation :","o":["Sensorielle et proprioceptive","Motrice et volontaire","Cognitive et mnésique","Circulatoire seule, par le changement de position"],"r":0,"e":"S'y ajoutent le confort, la fonction et la notion du corps dans son ensemble.","s":12},{"q":"L'autocontrôle dans la prévention des escarres se fait :","o":["À l'aide d'un miroir","Par palpation","Par photographie","Par un soignant"],"r":0,"e":"Il figure parmi les huit mesures de prévention, avec les changements toutes les 2 heures.","s":12},{"q":"En décubitus dorsal, les membres supérieurs sont placés :","o":["Sur coussin, en légère abduction et rotation externe","Sans coussin, en adduction contre le tronc","Sur coussin, en rotation interne et coude fléchi","Sans coussin, le long du corps, paumes en bas"],"r":0,"e":"Les membres inférieurs sont légèrement abductés et le tibio-tarsien en position neutre, talons non appuyés.","s":12},{"q":"Chez un patient partiellement dépendant en décubitus dorsal, les procédures sont :","o":["Similaires, avec plus d'attention à la symétrie","Radicalement différentes, avec un matériel spécifique","Réalisées sans aucun coussin","Limitées au seul tronc du patient"],"r":0,"e":"L'alignement tête-tronc-membres et la protection des protubérances osseuses restent la base. L'alignement reste aussi essentiel.","s":12},{"q":"Parmi les signes d'escarre, le cours cite :","o":["Une rougeur qui s'aggrave, puis des ulcères et des cratères","Un prurit diffus, sans lésion visible","Une desquamation fine, sans rougeur","Une pâleur persistante, avec un refroidissement de la zone d'appui"],"r":0,"e":"Les endroits les plus courants sont le sacrum, le calcanéum, le coude et le grand trochanter. Des plaies apparaissent aussi.","s":12},{"q":"L'éducation dans les objectifs fonctionnels concerne :","o":["Les patients et les soignants","Les seuls patients, sans les soignants","Les seuls soignants","La seule famille du patient"],"r":0,"e":"Elle s'inscrit dans la mission de prévention du kinésithérapeute face aux effets de l'alitement.","s":12},{"q":"L'escarre se définit comme :","o":["Une mort cellulaire locale, le tissu étant comprimé contre l'os","Une infection cutanée, d'origine bactérienne, sur un point d'appui","Une brûlure, liée au frottement prolongé","Une dermatose, d'origine allergique"],"r":0,"e":"La durée de compression est un élément constitutif de la définition. Le tissu est comprimé entre une protubérance osseuse et une surface dure.","s":12},{"q":"Parmi le matériel de prévention des escarres, le cours cite :","o":["Les lits articulés et le matériel anti-escarres","Les seuls coussins, sous les genoux","Les seuls matelas, à mémoire de forme","Les orthèses de posture, portées jour et nuit sans pause"],"r":0,"e":"Alimentation et hygiène adéquates complètent le dispositif.","s":12},{"q":"Les objectifs préventifs du positionnement concernent le système musculo-squelettique par :","o":["La prévention des pertes d'amplitude","Le renforcement des muscles du tronc","L'étirement des muscles raccourcis","La stabilisation des articulations"],"r":0,"e":"Trois autres systèmes sont visés : circulatoire, respiratoire et cutané. Il s'agit de l'amplitude articulaire.","s":12},{"q":"Parmi les objectifs fonctionnels, le cours cite :","o":["Permettre une mobilisation adéquate dans différentes positions","La seule verticalisation, le plus tôt possible après tout alitement","Le seul confort du patient au lit","La seule éducation de la famille"],"r":0,"e":"Faciliter le lever précoce, l'indépendance fonctionnelle et le mouvement normal complètent ces objectifs.","s":12},{"q":"La mission générale du kinésithérapeute dans ce cours est :","o":["La prévention des altérations liées à l'alitement","Une mission curative, centrée sur la guérison des lésions","Une mission d'évaluation, sans intervention","Une mission d'éducation, à l'exclusion du reste"],"r":0,"e":"Elle se décline en objectifs préventifs et fonctionnels.","s":12},{"q":"Les zones de pression en décubitus dorsal comprennent :","o":["Nuque, épineuses, omoplates, coudes, sacrum et talons","Oreille, épaule, côtes, trochanter et malléole externe","Front, épaules, épines iliaques et rotules","Ischions, sacrum, creux poplités et métatarses"],"r":0,"e":"Chaque position a ses zones propres, à connaître pour adapter la protection. Il s'agit de l'épine de l'omoplate, de l'olécrane, de la zone fessière et du calcanéum.","s":12},{"q":"Quelle région de la colonne vertébrale est la plus exposée aux lésions lors des transferts ?","o":["Cervicale","Dorsale","Lombaire","Sacrée"],"r":2,"e":"Colonne lombaire = +++ (très élevé). Cervicale = ++, épaules = +.","s":13},{"q":"Le noyau pulpeux du disque intervertébral contient :","o":["50% d'eau","70% d'eau","88% d'eau","100% d'eau"],"r":2,"e":"Le noyau pulpeux est une substance GÉLATINEUSE contenant 88% d'H2O.","s":13},{"q":"Quelle charge maximale un disque intervertébral peut-il supporter ?","o":["200 kg","400 kg","600 kg","1000 kg"],"r":2,"e":"Le disque peut supporter une force allant jusqu'à 600 kg.","s":13},{"q":"La charge sur L3/L4 en position neutre est d'environ :","o":["50 kg","86 kg","150 kg","300 kg"],"r":1,"e":"Position neutre : 86 kg sur L3/L4 (par le seul poids du corps).","s":13},{"q":"Soulever 20 kg avec le TRONC FLÉCHI et JAMBES TENDUES génère sur L3/L4 une charge de :","o":["86 kg","140 kg","210 kg","327 kg"],"r":3,"e":"327 kg — c'est la pire technique. Avec les jambes FLÉCHIES, on tombe à 210 kg.","s":13},{"q":"Quel est le bon principe biomécanique pour soulever une charge ?","o":["Tronc en flexion, jambes tendues","Tronc droit, jambes fléchies","Bras tendus à la verticale","Position assise"],"r":1,"e":"Garder le TRONC DROIT et fléchir les JAMBES (utiliser la force des MI) réduit considérablement la charge lombaire.","s":13},{"q":"Quelle commande verbale est recommandée lors d'un transfert en équipe ?","o":["Plusieurs commandes, données par chaque transporteur","Une seule commande, comme « 1, 2, 3 »","Chaque transporteur compte jusqu'à 3, pour lui seul","Aucune commande, chacun suivant le rythme des autres"],"r":1,"e":"Une SEULE commande, claire, par le chef d'équipe : '1, 2, 3...' pour synchroniser le mouvement.","s":13},{"q":"Concernant les contacts manuels, lequel est CORRECT ?","o":["Soutenir le segment par le dessus","Appuyer avec la pulpe des doigts sur le segment","Une main en coupe, qui épouse le segment","Garder des mains moites, pour mieux glisser"],"r":2,"e":"Main en COUPE pour épouser le segment ; jamais par le dessus, pas de pression des doigts, éviter les mains moites.","s":13},{"q":"Le transfert australienne se fait avec :","o":["Un seul transporteur, face au patient","Deux transporteurs, face au trajet","Trois transporteurs, de profil","Quatre transporteurs, deux de chaque côté du patient"],"r":1,"e":"Australienne = 2 transporteurs FACE AU TRAJET, sensiblement de même taille.","s":13},{"q":"Combien de transporteurs sont nécessaires pour un patient en GRANDE dépendance ?","o":["1","2","3 ou 4","Aucun"],"r":2,"e":"3/4 transporteurs sont utilisés pour les patients en grande dépendance (ex: lésion vertébro-médullaire).","s":13},{"q":"Quel facilitateur peut être utilisé lors d'un transfert à 1 transporteur ?","o":["Une ceinture ou une planche de transfert","Un marteau réflexe, pour tester le tonus avant","Des béquilles, posées contre le lit","Aucun matériel, à 1 seul transporteur"],"r":0,"e":"Ceinture de transfert et planche de transfert (slide board) facilitent les transferts à 1 transporteur.","s":13},{"q":"Avant un transfert, il faut TOUJOURS :","o":["Démarrer sans prévenir, pour surprendre le patient","Vérifier les freins du fauteuil et les fixations","Forcer le patient à se lever seul, pour tester sa force","Faire vite, pour limiter la fatigue"],"r":1,"e":"Vérifier stabilité ET fixations : FREINS, pieds, roues. Sécurité avant tout.","s":13},{"q":"L'objectif d'informer le patient avant le transfert est :","o":["Lui faire peur, pour qu'il reste bien immobile au lit","Réduire l'anxiété et améliorer la coordination","Le distraire pendant le transfert","Rien de particulier, par simple politesse"],"r":1,"e":"Informer = améliore la COORDINATION, RÉDUIT L'ANXIÉTÉ/peur, augmente la synchronisation.","s":13},{"q":"Qui dirige la manœuvre lors d'un transfert d'équipe ?","o":["Le patient","Le chef d'équipe","Le médecin","Personne en particulier"],"r":1,"e":"Le CHEF D'ÉQUIPE dirige la manœuvre — tous doivent connaître la stratégie.","s":13},{"q":"Concernant la POSITION du transporteur, quel élément est crucial ?","o":["Se tenir loin de la charge, bras tendus","Se tenir près, avec une base large et des leviers courts","Garder les bras tendus et les genoux verrouillés","Garder les pieds joints, pour être bien stable pendant le geste"],"r":1,"e":"Être proche de la charge (leviers courts), base d'appui large, MI semi-fléchis pour utiliser leur force. Les membres inférieurs sont semi-fléchis.","s":13},{"q":"Un transfert australienne PEUT être utilisé pour :","o":["Les seules courtes distances, du lit au fauteuil voisin","Les patients comateux, totalement dépendants","Les longs trajets, les escaliers et le lit","Les patients en réanimation, intubés"],"r":2,"e":"Australienne : longues distances, escaliers, ajustement dans le lit, passage au sol. Elle sert aussi au réajustement dans le lit et au passage au sol.","s":13},{"q":"Quel est l'ordre correct des phases d'un transfert ?","o":["Action, puis évaluation, puis stratégie et information","Évaluation, stratégie, risques, puis exécution","Exécution directe, sans préparation","Information, puis action immédiate"],"r":1,"e":"Évaluation du patient → choix du transfert → préparation/minimisation des risques → exécution avec communication. Les risques sont minimisés avant l'exécution.","s":13},{"q":"Le rôle PRINCIPAL du kinésithérapeute lors d'un transfert est :","o":["Exécuter seul, sans impliquer l'entourage du patient","Évaluer, informer, exécuter et former l'entourage","Donner les médicaments avant le transfert","Conduire le fauteuil roulant du patient"],"r":1,"e":"Évaluer le degré fonctionnel, choisir le transfert, informer, exécuter correctement et FORMER les professionnels/proches. Il choisit aussi le type de transfert.","s":13},{"q":"Le patient est-il capable de saisir, tirer ou pousser avec ses mains ? Cette question relève :","o":["Des erreurs les plus fréquentes","Des facteurs à prendre en compte","Du matériel à préparer","De l'épidémiologie des chutes"],"r":1,"e":"Évaluer les capacités MOTRICES du patient (saisir, tirer, pousser) fait partie des facteurs à analyser.","s":13},{"q":"Une mauvaise évaluation du POIDS du patient est :","o":["Une erreur sans conséquence pratique","Une erreur classique, qui compromet le transfert","Une stratégie volontaire, pour limiter le nombre de porteurs","Un facilitateur du transfert"],"r":1,"e":"C'est une des erreurs les plus communes ; mène à un nombre insuffisant de transporteurs et risque de blessure.","s":13},{"q":"Le transfert avec PLANCHE de transfert s'utilise pour :","o":["Un patient totalement dépendant, inerte","Un patient partiellement dépendant, qui peut participer","Un patient comateux, transféré sans aucune aide matérielle","Tous les patients, sans distinction de leur dépendance"],"r":1,"e":"La planche aide à glisser le patient partiellement dépendant entre 2 surfaces de même niveau (lit-FR).","s":13},{"q":"Pour un transfert lit-fauteuil avec 1 transporteur, le fauteuil doit être :","o":["Loin du lit, à au moins 2 mètres","À 45° du lit, freiné, accoudoir et pédale retirés","Devant le lit, face au patient, freins desserrés et pédales en place","Sur les roues libres, sans frein"],"r":1,"e":"Fauteuil à ~45° du lit, FREINÉ, accoudoir et pédale du côté transfert retirés/relevés. L'accoudoir et la pédale sont retirés du côté du transfert.","s":13},{"q":"Combien d'aides faut-il pour monter un escalier avec un fauteuil roulant ?","o":["1 aide seulement","Toujours 4","2 ou 3 aides","Aucune"],"r":2,"e":"2 ou 3 aides : la 1ère contrôle aux poignées (DOS aux escaliers), les autres tirent les grandes roues marche par marche.","s":13},{"q":"Lors d'un transfert, le poids doit être :","o":["Réparti équitablement entre les transporteurs","Porté par une seule personne, la plus forte","Maintenu longtemps, pour bien stabiliser","Tenu loin du corps, bras tendus"],"r":0,"e":"Répartition ÉQUITABLE du poids entre tous les éléments impliqués (transporteurs ET patient si possible). Le patient participe si possible.","s":13},{"q":"Quel élément du fauteuil roulant doit TOUJOURS être bloqué avant transfert ?","o":["Les poignées","Les freins","Le dossier","Les jantes"],"r":1,"e":"Vérifier les FREINS = priorité de sécurité ; aussi pieds et roues stables.","s":13},{"q":"Lors d'un transfert, la règle ergonomique principale est :","o":["Pencher le dos en avant, jambes tendues","Dos droit, genoux fléchis et charge près du corps","Soulever d'une seule main, l'autre restant libre pour l'appui","Tourner le tronc en torsion pour gagner du temps"],"r":1,"e":"Dos neutre, genoux fléchis (force des MI), charge près du corps, pas de rotation rachis sous charge.","s":13},{"q":"Avant un transfert, on doit toujours :","o":["Tirer brutalement le patient, pour gagner du temps","Évaluer le patient et sécuriser l'environnement","Pousser le patient sans le prévenir","Le faire sans prévenir, pour éviter l'appréhension"],"r":1,"e":"Sécurité = bilan rapide + briefing du patient + dégagement des obstacles + frein FR + sol sec. On évalue équilibre, force, douleur et compréhension.","s":13},{"q":"Le transfert australien est utilisé pour :","o":["Un patient autonome, qui se déplace seul","Un patient couché, entre deux surfaces à plat","Un patient debout, qui marche avec une aide","La marche, avec deux aides techniques"],"r":1,"e":"Transfert australien (drap glissé) = patient couché entre 2 surfaces de même hauteur, plusieurs aidants. Plusieurs aidants utilisent un drap glissé.","s":13},{"q":"Le \"transfert siège\" (chaise) implique :","o":["Un patient qui marche seul, sans aide","Un patient assis, déplacé d'un siège à l'autre","Un patient debout, soutenu sous les deux bras","Un patient suspendu à un lève-personne"],"r":1,"e":"Patient assis + 2 aidants (devant/derrière) = bloc soulevé puis transféré. Il est déplacé en bloc.","s":13},{"q":"Le verbe \"Prêt? Un, deux, trois...\" est essentiel car :","o":["C'est surtout pour le moral du patient","Elle synchronise les aidants et évite les blessures","Il n'y a aucune raison particulière","C'est une obligation légale, écrite dans le code"],"r":1,"e":"Synchronisation = sécurité : tous les aidants soulèvent en même temps, évite déséquilibre et lésions dorsales. Elle garantit la sécurité du patient.","s":13},{"q":"Le transfert se définit comme la mobilisation d'un patient d'un point A à un point B, qui doit :","o":["Être sûre et respecter l'alignement du patient et des porteurs","Être rapide avant tout, quel que soit l'alignement","Être réalisée par une seule personne, pour mieux la coordonner","Éviter tout contact avec le patient"],"r":0,"e":"Le poids doit être équitablement réparti entre tous les éléments impliqués.","s":13},{"q":"L'information préalable lors d'un transfert doit être donnée :","o":["Au patient et à l'équipe, qui connaissent le processus","Au seul patient, pour le rassurer","À la seule équipe, pour la coordonner","Au seul chef d'équipe, qui dirige ensuite la manœuvre seul"],"r":0,"e":"Elle améliore la coordination, réduit l'anxiété et augmente la synchronisation.","s":13},{"q":"Le risque de lésion lors des transferts est le plus élevé :","o":["À la colonne lombaire","À la colonne cervicale","Aux épaules","Aux genoux"],"r":0,"e":"La cervicale présente un risque élevé et les épaules un risque modéré.","s":13},{"q":"Le noyau pulpeux contient :","o":["88 % d'eau, en substance gélatineuse","50 % d'eau, en substance fibreuse dense","65 % d'eau, en cartilage hyalin","30 % d'eau, en tissu osseux"],"r":0,"e":"Sa forme est approximativement sphérique, comme une petite bille intercalée entre deux plans.","s":13},{"q":"La capacité de charge d'un disque intervertébral atteint :","o":["600 kg","300 kg","150 kg","1 000 kg"],"r":0,"e":"Chaque disque n'a qu'une petite amplitude, mais la somme des micro-mouvements permet une grande amplitude globale.","s":13},{"q":"En position neutre, la charge sur L3/L4 est de :","o":["86 kg","114 kg","140 kg","210 kg"],"r":0,"e":"Elle atteint 114 kg en flexion de 20° comme en rotation de 45°.","s":13},{"q":"Porter 20 kg en flexion du tronc avec les jambes tendues induit une charge sur L3/L4 de :","o":["327 kg","210 kg","140 kg","122 kg"],"r":0,"e":"Avec les jambes fléchies, la charge tombe à 210 kg : fléchir les jambes divise la charge par environ 1,5.","s":13},{"q":"Porter 20 kg répartis plutôt qu'en charge unique fait passer la charge lombaire de :","o":["140 kg à 122 kg","210 kg à 140 kg","327 kg à 210 kg","114 kg à 86 kg"],"r":0,"e":"La répartition de la charge est donc un levier de prévention à part entière.","s":13},{"q":"L'évaluation du patient avant transfert porte notamment sur :","o":["Le caractère spastique ou flasque de la pathologie","Le seul poids du patient, sans autre critère","La seule taille du patient, comparée à celle du transporteur","Le seul âge du patient, en années"],"r":0,"e":"S'y ajoutent le degré de dépendance et les conditions actuelles, alité ou positionné.","s":13},{"q":"La position du transporteur prend en compte :","o":["Centre de gravité, base, leviers, appuis et force","La seule force musculaire du transporteur","La seule taille du transporteur, debout","Le seul équilibre du transporteur, debout et chargé"],"r":0,"e":"C'est le point E des procédures de transfert. Les leviers doivent être les plus courts possible.","s":13},{"q":"Concernant les contacts manuels, les doigts :","o":["Ne doivent pas exercer de pression sur le segment","Doivent serrer fermement, pour sécuriser","Doivent s'enfoncer dans les tissus, pour bien tenir le segment","Doivent rester écartés, sans contact"],"r":0,"e":"La main se place en coupe pour épouser le segment, et les mains ne soutiennent jamais par le dessus.","s":13},{"q":"Les commandes lors d'un transfert doivent être :","o":["Uniques et explicites, avec un décompte « 1, 2, 3 »","Multiples, une pour chacun des 3 transporteurs","Implicites, chacun devinant le moment","Silencieuses, par simple signe de tête"],"r":0,"e":"Le chef d'équipe dirige la manœuvre et tous connaissent la stratégie.","s":13},{"q":"Parmi les facteurs à prendre en compte avant un transfert, le cours cite :","o":["Les limitations cognitives, auditives et visuelles","Le seul état de conscience, vigilant ou non","La seule douleur ressentie par le patient","Le seul matériel disponible dans la chambre du patient"],"r":0,"e":"S'y ajoutent la capacité à coopérer, le matériel sensible, les modifications du tonus, la capacité à saisir, l'absence de douleur et l'intégrité cutanée. Les limitations linguistiques en font aussi partie.","s":13},{"q":"La vérification de l'équipement avant transfert porte sur :","o":["La stabilité et les fixations, freins et roues","Le seul freinage du fauteuil, avant le départ","La seule hauteur de la table, réglée au trochanter","Le seul emplacement de l'équipement dans la pièce"],"r":0,"e":"Il faut aussi préparer l'espace et vérifier la hauteur des surfaces. Les pieds sont aussi vérifiés.","s":13},{"q":"L'attitude du transporteur doit transmettre :","o":["Sécurité et confiance","Neutralité et réserve","Distance et froideur","Autorité et fermeté, sans discussion"],"r":0,"e":"L'historique des transferts précédents aide à adapter cette communication.","s":13},{"q":"Les courbures physiologiques de la colonne observées en vue latérale sont :","o":["Lordoses cervicale et lombaire, cyphoses dorsale et sacrée","Deux lordoses seulement, cervicale et lombaire, sans cyphose","Deux cyphoses seulement, dorsale et sacrée","Une seule courbure, en C, de la nuque au sacrum"],"r":0,"e":"La colonne s'observe en vue postérieure et en vue latérale.","s":13},{"q":"La leçon-clé de la biomécanique des transferts est :","o":["Utiliser la force des jambes plutôt que celle du tronc","Utiliser la force du dos, qui est plus puissante que les jambes","Porter la charge au plus près, sans fléchir les genoux","Travailler seul, pour éviter les désynchronisations"],"r":0,"e":"Cela divise la charge lombaire par environ 1,5.","s":13},{"q":"La sélection du transfert porte sur :","o":["Le type de transfert, les porteurs, le site et le trajet","Le seul nombre de transporteurs nécessaires, selon le poids","Le seul itinéraire, du lit au fauteuil","Le seul matériel, comme la planche"],"r":0,"e":"Elle suit l'évaluation du patient dans les procédures de transfert.","s":13},{"q":"Il faut éviter les mains moites lors des contacts manuels car :","o":["Elles nuisent à la qualité du contact et au confort","Elles sont sales et transmettent des germes au patient","Elles glissent sur les vêtements du patient","Elles refroidissent la peau du patient"],"r":0,"e":"Le tronc doit par ailleurs être bien soutenu et stabilisé.","s":13},{"q":"L'emplacement de l'équipement doit assurer un trajet :","o":["Court, facile, sûr et fonctionnel","Le plus court possible","Le plus direct, même s'il passe par des obstacles","Sans obstacle, et rien d'autre"],"r":0,"e":"Cela concerne la position du matelas, de la chaise et du fauteuil roulant.","s":13},{"q":"Quelle aide à la marche offre la plus grande base d'appui ?","o":["Canne","Béquille canadienne","Déambulateur","Béquille axillaire"],"r":2,"e":"Le DÉAMBULATEUR offre la plus grande base d'appui quadrangulaire.","s":14},{"q":"Pour régler une aide à la marche, la poignée doit être au niveau de :","o":["L'épaule","Le coude en extension","Le grand trochanter","Le genou"],"r":2,"e":"Poignée AU NIVEAU DU GRAND TROCHANTER pour permettre ~25° de flexion du coude.","s":14},{"q":"L'angle correct de flexion du coude avec une aide à la marche est :","o":["0° (coude tendu)","Environ 25°","45°","90°"],"r":1,"e":"Légère flexion d'environ 25° pour absorber les chocs et propulser efficacement.","s":14},{"q":"Une canne unilatérale doit être placée du côté :","o":["Du membre blessé, pour le soulager","Du membre sain, opposé à la lésion","Indifféremment, selon la main dominante du patient","Toujours à droite, par convention"],"r":1,"e":"TOUJOURS du côté CONTROLATÉRAL à la dysfonction → réduit ~60% la charge sur la hanche atteinte. Elle réduit d'environ 60 % la charge sur la hanche atteinte.","s":14},{"q":"La sangle d'avant-bras d'une béquille canadienne se place à :","o":["Au poignet, à 2 cm de la main","À environ 5 cm sous le coude","À l'épaule, à 10 cm sous l'aisselle","Au milieu de l'avant-bras, à 15 cm"],"r":1,"e":"Sangle à 5 cm SOUS le coude pour bonne maîtrise sans gêne.","s":14},{"q":"Pour une béquille axillaire, le support thoracique doit :","o":["Toucher l'aisselle, pour bien tenir","Être 10 cm sous l'aisselle, contre la cage thoracique","Être appuyé contre l'épaule, à 2 cm au-dessus de l'aisselle","Être placé au coude, sous le bras"],"r":1,"e":"Le support doit être ~10 cm sous l'aisselle pour ÉVITER la compression des structures axillaires (nerf, vaisseaux).","s":14},{"q":"L'embout d'une béquille doit être placé :","o":["Sous le pied, au contact direct du talon","Derrière le pied, à 10 cm du talon","À 10 ou 15 cm devant et en dehors des pieds","Loin du corps, à plus de 50 cm"],"r":2,"e":"Embout 10/15 cm DEVANT et à L'EXTÉRIEUR des pointes des pieds = base d'appui optimale.","s":14},{"q":"Quel type de marche s'utilise quand l'appui sur le MI blessé est INTERDIT ?","o":["4 points","3 points","3 points modifiée","2 points"],"r":1,"e":"Marche à 3 POINTS : le MI blessé ne touche PAS le sol (charge nulle).","s":14},{"q":"La marche à 3 points modifiée diffère de la marche à 3 points par :","o":["Le nombre d'aides techniques utilisées","Une charge partielle permise sur le membre blessé","L'utilisation d'un fauteuil roulant en relais de la marche","La présence d'un assistant à côté du patient"],"r":1,"e":"3 points modifiée = appui PARTIEL autorisé sur le MI blessé (avance simultanée aides + MI blessé).","s":14},{"q":"Pour monter des escaliers avec béquilles, on commence par :","o":["Le MI blessé en premier","Le MI sain en premier","Les béquilles en premier","Sauter"],"r":1,"e":"MONTÉE : le MI SAIN monte en premier (le bon monte au paradis), puis aides + MI blessé.","s":14},{"q":"Pour descendre des escaliers avec béquilles :","o":["Le membre sain descend en premier, puis les aides","Les aides et le membre blessé descendent en premier","Le patient descend en sautant sur le membre sain, aides levées","Aucune règle, selon le confort du patient"],"r":1,"e":"DESCENTE : aides + MI BLESSÉ descendent en premier (le mauvais descend en enfer), puis MI sain.","s":14},{"q":"La marche pendulaire s'effectue avec :","o":["Une canne simple, du côté sain","Un déambulateur à roulettes","Deux béquilles canadiennes et des orthèses","Aucune aide technique, avec un appui du thérapeute"],"r":2,"e":"Marche pendulaire : 2 béquilles canadiennes + orthèses MI, MS forts requis (population LMS). Les orthèses sont aux membres inférieurs.","s":14},{"q":"Différence entre marche semi-pendulaire et pendulaire :","o":["Aucune différence, ce sont des synonymes","En pendulaire, les jambes dépassent la ligne des aides","La vitesse de marche, seulement","Le nombre de béquilles utilisées, une ou deux selon le cas"],"r":1,"e":"Semi-pendulaire (swing-to) : MI jusqu'à la ligne. Pendulaire (swing-through) : MI AU-DELÀ de la ligne. En semi-pendulaire, les jambes atteignent seulement la ligne des aides.","s":14},{"q":"Le standing-frame a pour bénéfice :","o":["Aucun effet sur l'os ni sur le tonus","Une hausse de la spasticité, par mise en charge prolongée","Une moindre perte osseuse et une baisse de la spasticité","Une impossibilité de verticaliser le patient"],"r":2,"e":"Standing-frame : limite la diminution de densité osseuse, diminue la spasticité, évite les altérations articulaires.","s":14},{"q":"Une orthèse genou-tibia-pied stabilise :","o":["La hanche en flexion, pour faciliter la position assise","Le genou en extension et la cheville en dorsiflexion","Le tronc, par une ceinture lombaire","L'épaule, par une écharpe de maintien"],"r":1,"e":"KAFO : genou EN EXTENSION + cheville en légère flexion dorsale (5-10°). La flexion dorsale est de 5 à 10°.","s":14},{"q":"Diamètre des grandes roues du fauteuil roulant :","o":["20 cm","40 cm","61 cm","100 cm"],"r":2,"e":"Grandes roues : 61 cm de diamètre. Roues libres (avant) : ~20 cm.","s":14},{"q":"Un patient TÉTRAPLÉGIQUE a besoin d'un dossier :","o":["Bas pour liberté de mouvement","Haut pour meilleur soutien du tronc","Indifférent","Inexistant"],"r":1,"e":"Tétraplégique = contrôle du tronc compromis → dossier HAUT. Paraplégique avec contrôle du tronc → dossier BAS.","s":14},{"q":"L'assise d'un fauteuil roulant doit permettre un angle de :","o":["45° hanche/genou","60° hanche/genou","90° hanche/genou","120° hanche/genou"],"r":2,"e":"Angle de 90° aux hanches ET aux genoux, profondeur à 5-7 cm de la région poplitée.","s":14},{"q":"Le dispositif anti-chute d'un fauteuil roulant sert à :","o":["Décorer le fauteuil, pour le rendre bien visible","Prévenir la bascule arrière et aider à lever l'avant","Freiner le fauteuil dans les pentes","Propulser le fauteuil sur terrain plat"],"r":1,"e":"Prévient les chutes arrière (FR en wheelie) ET facilite le soulèvement avant pour les trottoirs.","s":14},{"q":"Pour MONTER des escaliers en fauteuil roulant avec 2/3 aides, le 1er transporteur est :","o":["Face aux escaliers, aux grandes roues","Dos aux escaliers, tenant les poignées","À côté du fauteuil, à la roue","Devant le patient, aux repose-pieds"],"r":1,"e":"MONTÉE : 1er transporteur DOS AUX ESCALIERS aux poignées, fait les commandes. Les autres tirent les grandes roues. Il donne aussi les commandes.","s":14},{"q":"Pour DESCENDRE en fauteuil roulant avec 2/3 aides, le 1er transporteur est :","o":["Dos aux escaliers, aux poignées","Face à l'escalier, aux poignées","Sur les côtés, aux grandes roues du fauteuil","Derrière les autres aidants"],"r":1,"e":"DESCENTE : 1er transporteur FACE à l'escalier aux poignées ; les autres aux jantes propulsives.","s":14},{"q":"Une marche à 4 points est caractérisée par :","o":["L'avance simultanée d'une aide et du membre opposé","Des mouvements alternés, un élément après l'autre","L'absence de transfert de poids, d'un pied à l'autre","L'absence de toute séquence précise"],"r":1,"e":"Marche à 4 points : mouvements alternés successifs, très stable, contact constant avec le sol. Aide droite, membre gauche, aide gauche, membre droit.","s":14},{"q":"Pour la marche à 2 points, l'avance se fait :","o":["Un seul élément à la fois, dans l'ordre","Une aide et le membre opposé ensemble, puis l'inverse","Les deux aides ensemble, puis les deux jambes","Sans aucune coordination entre les aides et les jambes du patient"],"r":1,"e":"Marche à 2 points : avance SIMULTANÉE croisée (aide gauche + MI droit), reproduit le pas physiologique. Aide gauche et membre droit avancent ensemble, puis aide droite et membre gauche.","s":14},{"q":"Quelle aide est INTERDITE en unilatéral le plus souvent ?","o":["Canne","Trépied","Béquille axillaire","Béquille canadienne"],"r":2,"e":"L'usage UNILATÉRAL des béquilles axillaires n'est PAS courant (rare).","s":14},{"q":"Le standing-frame est destiné aux patients :","o":["Aux patients autonomes à la marche","Aux patients dépendants pour la station debout","Aux sportifs en récupération","Aux personnes sans pathologie, en prévention du vieillissement"],"r":1,"e":"Patients DÉPENDANTS pour l'orthostatisme (LMS, neuro) — maintien vertical sans aide tierce.","s":14},{"q":"La canne anglaise (béquille axillaire) doit prendre appui :","o":["Sous l'aisselle, en appui prolongé","Sur la poignée, l'avant-bras dans l'appui-bras","Sur l'épaule, par un coussin placé au-dessus de l'aisselle","Sur la nuque, par une sangle"],"r":1,"e":"Aucun appui axillaire prolongé (risque de paralysie du n. radial) ! La force passe par la poignée et l'avant-bras. Un appui axillaire prolongé risque une paralysie radiale.","s":14},{"q":"La canne simple se tient :","o":["Du côté lésé, pour le décharger directement","Du côté sain, opposé à la lésion","Au choix du patient, sans règle","Devant le patient, à deux mains"],"r":1,"e":"Côté sain : la canne et le MI atteint avancent ensemble → décharge du côté lésé.","s":14},{"q":"La marche en 3 points convient à :","o":["Une boiterie minime, sans douleur","Un appui interdit sur un membre, avec deux béquilles","Un patient autonome, sans restriction","Aucun patient, la technique ayant été abandonnée en pratique"],"r":1,"e":"3 points : les 2 béquilles + le MI sain avancent, MI atteint reste en suspension (sans appui). Par exemple après une fracture.","s":14},{"q":"La marche pendulaire est utilisée par :","o":["Tous les patients, quelle que soit leur pathologie de départ","Les patients paraplégiques, avec deux béquilles","Les patients autonomes, sans orthèse","Les enfants, en rééducation ludique"],"r":1,"e":"Pendulaire : 2 béquilles en avant puis les 2 MI passent en bloc devant les béquilles (paraplégie incomplète). Les deux membres inférieurs passent en bloc devant les béquilles.","s":14},{"q":"Hauteur correcte du déambulateur :","o":["Sous l'aisselle, bras tendus","Au grand trochanter, coude un peu fléchi","Au ras du sol, pour plus de stabilité","Au niveau de l'épaule, coudes tendus"],"r":1,"e":"Hauteur = grand trochanter ; coude fléchi 20-30° en appui pour ne pas voûter le dos. Le coude est fléchi de 20 à 30°.","s":14},{"q":"Le fauteuil roulant est présenté comme :","o":["Un outil d'autonomie et d'intégration sociale","Une aide à la marche parmi d'autres","Un dispositif temporaire, en attente de la reprise de marche","Un équipement médical passif, sans rôle social"],"r":0,"e":"Cette distinction conceptuelle est explicite dans le cours. Ce n'est pas une aide à la marche.","s":14},{"q":"Le déambulateur peut être articulé afin :","o":["De faciliter la dissociation des ceintures","D'alléger son poids pour le transport en voiture","D'améliorer le freinage sur les pentes","De se ranger plus facilement"],"r":0,"e":"Sa base quadrangulaire reste la plus grande de toutes les aides.","s":14},{"q":"Pour les trépieds et pyramides, la concavité de la poignée est tournée :","o":["Vers le patient","Vers l'extérieur","Vers l'avant","Vers le sol"],"r":0,"e":"Ils s'utilisent en bilatéral ou en unilatéral, du côté opposé à la dysfonction.","s":14},{"q":"Selon Laufer (2003), les trépieds :","o":["Réduisent le balancement postural des hémiplégiques","Augmentent la vitesse de marche des hémiplégiques","Diminuent la douleur à l'appui sur le membre atteint du patient","Améliorent l'endurance de marche"],"r":0,"e":"Buurke (2005) montre que la canne active les extenseurs du tronc et le tibial antérieur.","s":14},{"q":"Le danger de l'appui axillaire sur une béquille est :","o":["La compression des nerfs et des vaisseaux axillaires","Une luxation antérieure de l'épaule","Une fracture de côte, par appui répété","Une douleur cervicale, par élévation durable de l'épaule"],"r":0,"e":"Le support thoracique se place environ 10 cm en dessous de l'aisselle.","s":14},{"q":"Les barres parallèles permettent également :","o":["L'entraînement aux transferts assis-debout","La marche en extérieur, sur des terrains variés","L'entraînement à la propulsion du fauteuil","Le travail de la force du membre supérieur"],"r":0,"e":"Elles offrent une excellente sécurité pour démarrer l'entraînement à la marche.","s":14},{"q":"Parmi les bénéfices du standing frame, le cours cite :","o":["Moins de perte osseuse et une spasticité réduite","Une augmentation de la force musculaire","Une amélioration de l'endurance cardiaque","Une réduction de la douleur chronique, en position debout"],"r":0,"e":"Il augmente aussi l'indépendance, la fonctionnalité et l'estime de soi, et évite les modifications de mobilité articulaire. La perte concerne la densité osseuse.","s":14},{"q":"Les orthèses permettent :","o":["De stabiliser les articulations non contrôlées","D'augmenter la force des muscles","De réduire la douleur articulaire de façon durable, par appui","De remplacer la marche par un autre mode"],"r":0,"e":"Elles rendent la marche possible en cas de lésion médullaire. Il s'agit des membres inférieurs, que le patient ne contrôle pas volontairement.","s":14},{"q":"La marche à 4 points est indiquée pour :","o":["Une marche très stable, chez un patient faible ou instable","Un appui interdit sur le membre blessé, après chirurgie","Un appui partiel sur le membre blessé","Un patient autonome, sans trouble de l'équilibre"],"r":0,"e":"Les aides se placent à environ 15 cm devant chaque pied, au même niveau.","s":14},{"q":"La marche à 3 points est indiquée quand :","o":["L'appui est interdit sur le membre inférieur blessé","L'appui est partiel, sur le membre blessé","L'appui est complet, sur les deux membres","L'équilibre est fragile, chez un patient très âgé"],"r":0,"e":"Le membre blessé effectue un pas sans toucher le sol. Par exemple après une opération récente.","s":14},{"q":"La marche à 3 points modifiée se distingue par :","o":["Un appui partiel, le poids étant réparti sur trois éléments","Un appui nul, le membre blessé restant en l'air","Un appui complet, sans aucune restriction sur le membre blessé","L'absence d'aides, le patient marchant seul"],"r":0,"e":"C'est la transition entre l'appui interdit et la reprise d'appui complet. Le poids se répartit entre aides, membre sain et membre blessé.","s":14},{"q":"L'assise du fauteuil roulant se règle à une profondeur de :","o":["5 à 7 cm de la région poplitée","Au contact du creux poplité","10 cm","15 cm"],"r":0,"e":"Elle doit permettre un angle de 90° aux hanches et aux genoux.","s":14},{"q":"Le dossier du fauteuil roulant se règle à :","o":["À 10 cm de l'aisselle","Au niveau des épaules","Au niveau du bassin, à 5 cm des crêtes","Sans repère, selon le confort"],"r":0,"e":"Un dossier haut convient à la tétraplégie et un dossier bas à la paraplégie.","s":14},{"q":"Les jantes propulsives se situent :","o":["À l'extérieur des grandes roues, pour la propulsion","À l'intérieur des grandes roues, pour la propulsion","Sur les roues libres avant, pour le transporteur qui pousse","Sur le châssis, sous l'assise"],"r":0,"e":"Les grandes roues mesurent 61 cm et les roues libres environ 20 cm.","s":14},{"q":"Les accoudoirs du fauteuil roulant sont :","o":["Amovibles, pour reposer les bras et faire des push-ups","Fixes, sans aucune possibilité de les retirer lors des transferts","Sans réglage possible, quelle que soit la taille","Purement décoratifs, sans fonction"],"r":0,"e":"Leur amovibilité est essentielle lors des transferts latéraux. Le coude est fléchi à 90°.","s":14},{"q":"Le réglage commun à toutes les aides à la marche est :","o":["Poignée au grand trochanter, coudes fléchis d'environ 25°","Poignée au niveau du coude, bras tendus le long du corps","Poignée au niveau de la hanche, coude tendu à 0°","Hauteur libre, selon la préférence du patient"],"r":0,"e":"L'embout se place 10 à 15 cm devant et à l'extérieur des pointes des pieds.","s":14},{"q":"La sangle d'avant-bras de la béquille canadienne se place :","o":["5 cm sous le coude","10 cm sous le coude","Au niveau du poignet","Au pli du coude"],"r":0,"e":"La béquille se compose d'une poignée, d'une sangle d'avant-bras et d'un embout caoutchouc.","s":14},{"q":"Selon Bateni & Maki (2005), l'aide controlatérale réduit la charge coxo-fémorale d'environ :","o":["60 %","30 %","80 %","40 %"],"r":0,"e":"C'est pourquoi la canne se place du côté opposé à la dysfonction.","s":14},{"q":"Le châssis du fauteuil roulant peut être :","o":["Articulé en X et pliable, ou rigide","Uniquement rigide, en une pièce","Uniquement pliable, en accordéon vertical","Télescopique, en largeur"],"r":0,"e":"Les freins assurent l'immobilisation et la stabilisation du fauteuil.","s":14},{"q":"L'orthèse KAFO stabilise la cheville en :","o":["Une flexion dorsale de 5 à 10°","Une flexion plantaire de 15 à 20°","Une position neutre, à 0°","Une inversion de 10°"],"r":0,"e":"Elle stabilise le genou en extension ; l'HKAFO y ajoute la stabilisation latérale du bassin.","s":14},{"q":"Les principes directeurs du positionnement incluent :","o":["Être inconfortables, pour bien stimuler l'éveil","Donner la notion du corps dans son ensemble","Limiter la mobilité du patient au lit","Éviter toute stimulation sensorielle"],"r":1,"e":"Le positionnement doit être confortable, fonctionnel, donner une notion du corps dans son ensemble, et offrir une stimulation sensorielle/proprioceptive.","s":15},{"q":"Lors d'un ajustement dans le lit à 2 personnes, le lit doit être à hauteur :","o":["Du genou des soignants","Du grand trochanter des soignants","Du nombril des soignants debout","Du coude des soignants"],"r":1,"e":"Lit à hauteur du grand trochanter du kiné/assistant pour utiliser leur biomécanique.","s":15},{"q":"Pour rouler un patient avec assistance, les mains du kiné sont sur :","o":["La tête et les pieds du patient","Les ceintures scapulaire et pelvienne","Les deux genoux fléchis du patient","Les deux poignets du patient"],"r":1,"e":"Ceinture scapulaire + ceinture pelvienne pour un roulement EN BLOC.","s":15},{"q":"Au transfert australienne, l'épaule du transporteur s'appuie :","o":["Dans le creux de l'aisselle du patient","Contre la cage thoracique, sous l'aisselle","Sur la tête du patient, pour la soutenir","Sur le bassin du patient, au niveau de la crête iliaque"],"r":1,"e":"Épaule contre la cage thoracique SOUS l'aisselle. Ne jamais exercer de pression dans l'aisselle (compression nerveuse/vasculaire). Jamais de pression dans l'aisselle.","s":15},{"q":"Combien d'options de positionnement existent pour le décubitus latéral côté affecté ?","o":["1","2","3","4"],"r":2,"e":"3 options : coude en flexion, coude en extension, MS libres.","s":15},{"q":"Quel transfert s'utilise pour la GRANDE dépendance (lit↔lit) ?","o":["1 transporteur","Siège à 2","3 ou 4 transporteurs","Aucun"],"r":2,"e":"Grande dépendance = 3/4 transporteurs (ex: lésion vertébro-médullaire).","s":15},{"q":"Lors d'un transfert à 4 transporteurs, le 4e a pour rôle :","o":["Tenir les pieds, en bout de lit, et donner le rythme","Soutenir le bassin, avec le 2ᵉ transporteur","Tracter seulement la tête, en suivant le mouvement","Donner les commandes, sans toucher le patient"],"r":2,"e":"Le 4e transporteur tire EXCLUSIVEMENT la tête, suivant le mouvement.","s":15},{"q":"Le transfert australienne convient pour :","o":["Les seules courtes distances, du lit au fauteuil","Les longs trajets, les escaliers et le lit","Les patients comateux, totalement dépendants","Aucun cas, la technique étant dangereuse"],"r":1,"e":"Australienne : longues distances, escaliers, ajustement dans le lit, passage au sol. Elle sert aussi au réajustement dans le lit et au passage au sol.","s":15},{"q":"Pour le transfert à 2 transporteurs (classique lit↔chaise), le 1er transporteur :","o":["Tient les deux jambes, sous les genoux et les chevilles","Se place derrière, en prise croisée aux avant-bras","Se tient devant le patient, face à lui","Tient la tête du patient, à deux mains"],"r":1,"e":"1er transporteur DERRIÈRE le patient, prise CROISÉE au niveau des avant-bras. Le 2e soutient les MI.","s":15},{"q":"L'angle entre les 2 surfaces lors d'un transfert à 1 transporteur est :","o":["0° (parallèles)","45°","90°","180°"],"r":1,"e":"Surfaces à 45° pour le transfert à 1 transporteur (destination plus basse si possible).","s":15},{"q":"La planche de transfert est utilisée pour :","o":["Un patient totalement dépendant, inerte","Un patient qui peut glisser à l'aide de ses bras","Un patient en coma, transféré par quatre soignants","Personne, la planche étant trop dangereuse"],"r":1,"e":"Planche de transfert : patient qui peut utiliser ses MS pour glisser d'une surface à l'autre.","s":15},{"q":"Sur le côté affecté en décubitus latéral, dans l'OPTION 2, le coude est :","o":["En flexion","En extension","En rotation","Libre"],"r":1,"e":"Option 1 = flexion ; Option 2 = EXTENSION ; Option 3 = MS libres.","s":15},{"q":"Quelle est la zone la plus à risque d'escarre en décubitus dorsal ?","o":["L'oreille, le trochanter et la malléole externe","Le sacrum, le calcanéum et l'occiput","Le pubis et l'épine iliaque antérieure","Le coude, en face antérieure"],"r":1,"e":"Zones-clés en décubitus dorsal : sacrum, calcanéum, occiput, olécrane, épine omoplate.","s":15},{"q":"Le décubitus ventral est utilisé en cas de :","o":["Le repos normal et habituel de tout patient alité","Une détresse respiratoire, des escarres postérieures","La simple préférence du patient, sans indication","Les soins quotidiens d'hygiène et de change"],"r":1,"e":"Position d'exception : insuffisance respiratoire grave, escarres postérieures, postopératoire, raccourcissement des fléchisseurs de hanche. Le postopératoire en fait aussi partie.","s":15},{"q":"Pour ajuster le lit à 1 personne, le patient fait :","o":["Rien, il reste totalement passif","Un pont, genoux fléchis et pieds appuyés","Une rotation complète sur le côté, bras croisés sur le thorax","Un saut vers la tête du lit"],"r":1,"e":"Le patient fléchit les MI (pieds appuyés) et fait un PONT pendant que le kiné applique une pression vers les pieds. Le kiné pousse vers les pieds.","s":15},{"q":"Lors du transfert, les commandes doivent être :","o":["Multiples et complexes","Claires, explicites et uniques","Silencieuses, par simple regard","Inutiles, chacun suivant son propre rythme"],"r":1,"e":"Commandes claires et explicites, UNE seule commande (ex: 1,2,3) pour synchroniser.","s":15},{"q":"Avant un transfert avec FR, il faut :","o":["Laisser les freins libres, pour ajuster","Freiner, retirer l'accoudoir et relever la pédale côté transfert","Laisser l'accoudoir en place, pour l'appui","Ne rien faire de particulier, le fauteuil étant stable par nature"],"r":1,"e":"FR FREINÉ, accoudoir retiré et pédale relevée côté transfert pour libérer l'accès.","s":15},{"q":"Le rôle du chef d'équipe lors d'un transfert à 3/4 personnes est de :","o":["Soutenir les pieds, en bout de lit","Soutenir la tête et la nuque","Pousser le lit d'arrivée vers le patient, pour réduire l'écart","Observer, sans toucher le patient"],"r":1,"e":"Le chef d'équipe soutient la TÊTE-COU (occiput + 2 premières vertèbres cervicales) et donne les commandes. Il soutient l'occiput et les deux premières cervicales et donne les commandes.","s":15},{"q":"Pour s'asseoir avec assistance, le patient doit d'abord :","o":["Se redresser d'un coup","Rouler sur le côté, au bord du lit","S'allonger sur le ventre","Tirer sur les bras du kiné, pour se redresser seul"],"r":1,"e":"Rouler sur le côté et rester au bord du lit, puis croiser les MS sous la poitrine.","s":15},{"q":"Concernant les contacts manuels, ils ne doivent jamais :","o":["Être en coupe","Soutenir par le dessus","Épouser le segment","Transmettre confort"],"r":1,"e":"Les mains ne soutiennent JAMAIS par le dessus, ni avec pression des doigts.","s":15},{"q":"Au transfert siège (2 transporteurs), les transporteurs sont :","o":["Côte à côte, face au trajet","Face à face, de profil par rapport au chemin","L'un derrière l'autre, face au chemin à parcourir","Dos à dos, de profil au chemin"],"r":1,"e":"Face à face, de PROFIL au chemin. Saisie sous les cuisses (avant-bras/poignet).","s":15},{"q":"La prévention des escarres est :","o":["Du ressort exclusif du médecin","Une intervention multidisciplinaire intégrée","Réservée aux infirmiers, à l'exclusion des autres soignants","Inutile, si le patient est jeune"],"r":1,"e":"Équipe MULTIDISCIPLINAIRE intégrée avec objectifs communs.","s":15},{"q":"Pour rouler SANS assistance, le patient :","o":["Met les bras en adduction, jambes tendues","Écarte les bras, fléchit les jambes, joint les mains","Garde les bras le long du corps, jambes tendues","Saute sur le côté, d'un seul élan"],"r":1,"e":"MS en abduction + MI fléchis + paumes jointes = roulement autonome.","s":15},{"q":"Pour la position debout avec assistance, le kiné :","o":["Tire sur les bras du patient vers l'avant","Soutient bras et genoux, et transfère le poids vers l'avant","Soulève le patient par les aisselles","Reste passif, à côté du patient, sans contact pendant le lever"],"r":1,"e":"Kiné soutient MS (selon dysfonction), genoux (face latérale externe), et transfère le poids VERS L'AVANT pour le redressement. Il soutient les genoux par leur face latérale externe.","s":15},{"q":"Le transfert à 3 transporteurs Lit↔Lit débute par :","o":["Soulever directement le patient, sans le déplacer au préalable","Amener le patient au bord du lit, mains placées","Tourner le patient sur le côté, vers les porteurs","Glisser une planche sous le patient"],"r":1,"e":"On amène d'abord le patient AU BORD du lit. MS des transporteurs aux 3 niveaux (cou, pelvis, MI), avant-bras fléchis et proches du tronc. Les membres supérieurs des transporteurs se placent au cou, au bassin et aux membres inférieurs.","s":15},{"q":"Pour faire passer un patient du décubitus dorsal au latéral, on :","o":["Tirer sur le bras seul, vers soi","Croiser jambe et bras, puis tourner en bloc","Pousser sur les pieds, vers la tête du lit","Lever la tête uniquement, puis attendre"],"r":1,"e":"Mobilité au lit DD→DL = bras opposé en travers, MI opposé fléchi, rotation en bloc tronc/bassin. On croise la jambe et le bras opposés.","s":15},{"q":"Le drap de glissement (slide sheet) sert à :","o":["Couvrir le lit, comme un drap ordinaire","Réduire les frictions lors des déplacements au lit","Décorer la chambre, avec des couleurs vives et apaisantes","Chauffer le lit avant le coucher"],"r":1,"e":"Slide sheet → ↓ friction → patient déplacé plus facilement → ↓ effort soignant et ↓ risque escarre/cisaillement.","s":15},{"q":"Le rehaussement au lit s'effectue idéalement à :","o":["Un seul aidant, sans matériel","Deux aidants synchronisés","Aucun aidant, le patient seul","Cinq aidants, autour du lit, avec un lève-personne"],"r":1,"e":"2 aidants synchronisés + slide sheet = méthode sûre pour rehausser un patient sans force excessive. On utilise aussi un drap de glissement.","s":15},{"q":"Le coussin de positionnement :","o":["Sert à décorer le lit et la chambre","Prévient les appuis, aligne et évite les rétractions","Provoque des escarres par la pression","Limite tous les mouvements du patient, pour plus de sécurité au lit"],"r":1,"e":"Coussins = répartir les pressions + maintenir alignement neutre + prévenir rétractions (équin, rotation hanche).","s":15},{"q":"En décubitus latéral, on stabilise par :","o":["Rien, le patient tenant seul sur le côté","Un coussin dans le dos et un entre les genoux","Une charge posée sur la tête, pour la fixer","Les pieds en extension maximale"],"r":1,"e":"DL : coussin dorsal (anti-bascule) + coussin entre genoux (alignement hanche, ↓ pression interne).","s":15},{"q":"Les techniques de positionnement et de mobilité visent à préserver :","o":["Le schéma corporel, la mobilité et l'intégrité cutanée","La seule intégrité cutanée, au point d'appui","La seule mobilité articulaire, sans souci de la peau fragile","Le seul schéma corporel du patient alité"],"r":0,"e":"Elles préviennent aussi les complications cardiorespiratoires et circulatoires. La conscience du mouvement en fait aussi partie.","s":15},{"q":"Parmi les objectifs du positionnement figure :","o":["Former le patient et ses proches ou soignants","La seule prévention des escarres","Le seul confort du patient","La seule mobilisation passive, plusieurs fois par jour au lit"],"r":0,"e":"S'y ajoutent la prévention des altérations, la facilitation du schéma de mouvement et du lever précoce.","s":15},{"q":"Les principes directeurs du positionnement imposent une norme :","o":["Adaptable selon l'état du patient","Rigide, identique pour tous","Universelle, sans adaptation","Fixée par un protocole écrit, à respecter sans exception"],"r":0,"e":"Les positionnements doivent être confortables, fonctionnels, offrir une stimulation sensorielle et proprioceptive et donner une notion du corps dans son ensemble.","s":15},{"q":"En position assise, les zones à risque d'escarre sont :","o":["Épine de l'omoplate, ischions, sacrum et métatarses","Occiput, sacrum et talons, en appui sur le dos","Trochanter, malléole et oreille, sur le côté","Rotule, épine iliaque et visage, en avant"],"r":0,"e":"Chaque décubitus a ses zones propres, à connaître pour la prévention. La région poplitée est aussi à risque.","s":15},{"q":"La prévention des escarres relève :","o":["D'une équipe multidisciplinaire","Du seul kinésithérapeute","Du seul infirmier de service","Du seul patient, informé par une brochure"],"r":0,"e":"Elle associe autocontrôle, changements toutes les 2 heures, positionnements, mobilisations, matériel, alimentation, hygiène et soins vestimentaires.","s":15},{"q":"En décubitus dorsal chez un patient totalement dépendant, il faut éviter :","o":["Le poids des vêtements sur la cheville","Les coussins sous les membres, qui gênent la circulation","L'abduction des membres supérieurs","La rotation externe des épaules"],"r":0,"e":"Les membres supérieurs sont en légère abduction et rotation externe sur coussin. La cheville reste en position neutre, talons non appuyés.","s":15},{"q":"Chez le patient partiellement dépendant en décubitus dorsal, l'attention porte sur :","o":["La symétrie et l'alignement entre segments","Le seul confort du patient","Les seuls points d'appui osseux","La seule respiration, par la position semi-assise du patient"],"r":0,"e":"Les procédures restent par ailleurs similaires à celles du patient totalement dépendant.","s":15},{"q":"En décubitus latéral, l'épaule inférieure doit être :","o":["Avancée, avec la main posée sur l'oreiller","Reculée, sous le dos du patient","Placée sous le tronc, bras tendu","En rotation interne, main sous la hanche"],"r":0,"e":"Le membre supérieur supérieur repose à l'horizontale sur un coussin, main fonctionnelle.","s":15},{"q":"Sur le côté non affecté en décubitus latéral :","o":["La jambe du dessus fléchie sur coussin, cheville neutre","Les membres restent tendus, sans coussin","Aucun coussin n'est utilisé entre les membres","La cheville du dessus est placée en équin, sans aucun soutien"],"r":0,"e":"Trois options existent pour le positionnement du côté affecté, selon la position du coude et des membres supérieurs.","s":15},{"q":"Parmi les principes de sécurité de la mobilité précoce figure :","o":["Optimiser sa biomécanique, par son poids","Utiliser sa force, en tirant sur les bras","Travailler seul, sans demander d'aide","Accélérer le mouvement"],"r":0,"e":"Il faut aussi ne pas traîner, ne pas forcer sur les articulations, éviter les amplitudes extrêmes, favoriser l'alignement, permettre la participation et demander de l'aide. On utilise son positionnement et son poids du corps.","s":15},{"q":"Pour ajuster le lit à deux personnes, il ne faut pas :","o":["Tirer par la ceinture scapulaire ni traîner le drap","Utiliser le drap pour faire glisser le patient","Régler la hauteur du lit au grand trochanter","Mettre les segments du lit au même niveau"],"r":0,"e":"Le lit se règle à hauteur du grand trochanter des soignants, segments au même niveau.","s":15},{"q":"Pour ajuster le lit à une personne, le patient :","o":["Fait le pont, genoux fléchis, pendant que le kiné pousse","Est tiré par les épaules vers la tête du lit, sans aider","Reste passif, le kiné faisant tout","Se retourne sur le ventre"],"r":0,"e":"Il se déplace ainsi progressivement vers la tête de lit. Le kiné exerce une pression vers les pieds.","s":15},{"q":"Pour s'asseoir avec assistance, le membre supérieur distal du kiné :","o":["Sort les jambes du lit, créant le mouvement pendulaire","Soutient la tête et contrôle la ceinture scapulaire du patient","Contrôle la ceinture scapulaire, par l'épaule","Reste libre, prêt à rattraper le patient"],"r":0,"e":"Le membre supérieur proximal soutient la tête et contrôle la ceinture scapulaire.","s":15},{"q":"Pour la position debout avec assistance, le kiné soutient les genoux :","o":["Par leur face latérale externe","Par le creux poplité","Par la face antérieure, sous la rotule","Par la rotule, à pleine main"],"r":0,"e":"Il soutient aussi le membre supérieur selon le dysfonctionnement, avant le transfert de poids vers l'avant et le redressement.","s":15},{"q":"Parmi les points de minimisation des risques lors d'un transfert figure :","o":["Vérifier la stabilité et les fixations","Contrôler les seuls freins du fauteuil","Régler la seule hauteur du lit, au niveau du trochanter","Choisir le seul itinéraire du transfert"],"r":0,"e":"S'y ajoutent la préparation de l'espace, l'analyse du levage, la hauteur des surfaces, la localisation des aides et l'historique des transferts. Freins, pieds et roues tournées vers l'avant.","s":15},{"q":"La stratégie d'un transfert définit :","o":["Les porteurs, le lieu, le type et l'itinéraire","La seule pathologie du patient, spastique ou flasque","Le seul matériel à utiliser","Le seul horaire du transfert"],"r":0,"e":"Elle suit l'évaluation du type de pathologie, du degré de dépendance et des conditions d'alitement. Il s'agit du nombre de transporteurs.","s":15},{"q":"Le décubitus ventral est réservé à des situations spécifiques telles que :","o":["L'insuffisance respiratoire et les escarres postérieures","Toute immobilisation prolongée, quelle qu'en soit la cause","La prévention systématique des escarres","Le seul confort du patient"],"r":0,"e":"Il est généralement mal toléré par le patient. S'y ajoutent le postopératoire et le raccourcissement des fléchisseurs de hanche.","s":15},{"q":"Pour rouler avec assistance, le roulement doit se faire :","o":["En bloc, une main à chaque ceinture","Segment par segment, de la tête aux pieds","Par traction sur le bras du patient","Par poussée du bassin, puis des épaules, dans cet ordre précis"],"r":0,"e":"Le patient a les membres inférieurs fléchis et les pieds appuyés. Les ceintures sont scapulaire et pelvienne.","s":15},{"q":"Pour se lever sans assistance depuis la position assise, le patient :","o":["Mains au bord du lit, nez vers les pieds, puis il se redresse","Tire sur la barrière du lit, bras tendus, en se penchant en arrière","Pousse sur les bras seuls, le dos droit","Se penche en arrière, puis pousse sur les talons"],"r":0,"e":"Le mouvement vers l'avant amène le centre de gravité au-dessus des appuis.","s":15},{"q":"En décubitus latéral, le coussin entre les genoux sert à :","o":["Maintenir les jambes fléchies dans un bon alignement","Surélever le bassin, pour soulager le sacrum","Protéger le trochanter du dessous, en appui","Faciliter le roulement du patient vers l'avant"],"r":0,"e":"Un coussin dos-lit peut s'y ajouter si nécessaire, et le tibio-tarsien supérieur reste en position neutre.","s":15},{"q":"Le déambulateur offre une base d'appui :","o":["Triangulaire, comme celle du trépied de marche","Quadrangulaire, la plus grande de toutes","Linéaire, comme celle des cannes","Aucune base, il roule"],"r":1,"e":"Base d'appui QUADRANGULAIRE, la plus grande de toutes les aides à la marche.","s":16},{"q":"Le réglage standard de toutes les aides à la marche place la poignée :","o":["À l'épaule, coude tendu à 0°","Au grand trochanter, coude fléchi d'environ 25°","Au niveau du coude, avant-bras à l'horizontale, à 90°","Au genou, coude tendu et bras le long du corps"],"r":1,"e":"Poignée au GRAND TROCHANTER avec FLEXION COUDE ~25°. Règle commune à toutes les aides.","s":16},{"q":"Quelle différence existe entre un trépied et une pyramide ?","o":["Aucune différence, ce sont 2 noms pour une même aide","Le trépied a 3 points d'appui, la pyramide en a 4","La pyramide est plus petite et plus légère","Le trépied est en bois, la pyramide en métal"],"r":1,"e":"Trépied = 3 points d'appui en caoutchouc ; Pyramide = 4 points d'appui.","s":16},{"q":"Pour un trépied/pyramide, la concavité de la poignée doit être :","o":["Tournée vers l'extérieur","Tournée vers le patient","Vers le haut","Indifférent"],"r":1,"e":"Concavité de la poignée TOURNÉE VERS LE PATIENT, points d'appui vers l'extérieur.","s":16},{"q":"La sangle d'avant-bras d'une béquille canadienne se place :","o":["Au poignet, à 2 cm de la main","À 5 cm sous le coude","À l'épaule, à 10 cm","Sur la main, au dos"],"r":1,"e":"Sangle d'avant-bras à 5 cm sous le coude pour bon contrôle sans gêne.","s":16},{"q":"L'embout d'une aide à la marche se positionne :","o":["Sous le pied, au contact direct du talon et des orteils","Derrière le pied, à 10 cm du talon","À 10 ou 15 cm devant et en dehors des pieds","À côté du genou, à 20 cm"],"r":2,"e":"10/15 cm DEVANT et à L'EXTÉRIEUR des pointes des pieds pour une base optimale.","s":16},{"q":"L'utilisation controlatérale d'une aide à la marche réduit la charge coxo-fémorale d'environ :","o":["10%","30%","60%","90%"],"r":2,"e":"Bateni & Maki (2005) : environ −60% de charge sur l'articulation coxo-fémorale du côté dysfonction.","s":16},{"q":"Le support thoracique de la béquille axillaire doit se trouver :","o":["Dans le creux de l'aisselle, en appui direct","À 10 cm sous l'aisselle, contre le thorax","À l'épaule, à 5 cm au-dessus de l'aisselle","Au coude, à 20 cm sous l'aisselle"],"r":1,"e":"~10 cm SOUS l'aisselle, sur la cage thoracique latérale, pour éviter la compression axillaire.","s":16},{"q":"La canne s'utilise du côté :","o":["Du membre blessé","Opposé à la dysfonction","Indifférent","Toujours à droite"],"r":1,"e":"Côté OPPOSÉ à la dysfonction pour répartir la charge.","s":16},{"q":"Diamètre des grandes roues du fauteuil roulant :","o":["20 cm","40 cm","61 cm","100 cm"],"r":2,"e":"Grandes roues : 61 cm. Roues libres (avant) : ~20 cm.","s":16},{"q":"L'assise d'un FR doit permettre un angle hanche/genou de :","o":["45°","60°","90°","120°"],"r":2,"e":"Angle de 90° aux hanches ET aux genoux, profondeur 5-7 cm de la région poplitée.","s":16},{"q":"Un patient TÉTRAPLÉGIQUE a besoin d'un dossier :","o":["Bas, pour libérer les mouvements du tronc","Haut, pour un meilleur soutien du tronc","Absent, pour travailler l'équilibre assis du tronc","Inclinable seulement, sans hauteur fixe"],"r":1,"e":"Tétra = contrôle tronc compromis → dossier HAUT. Para avec contrôle tronc → dossier BAS.","s":16},{"q":"Le dispositif anti-chute du FR sert à :","o":["Freiner le fauteuil dans les pentes raides","Éviter la bascule arrière du fauteuil","Décorer et signaler le fauteuil","Propulser le fauteuil en avant"],"r":1,"e":"Prévient les chutes vers l'arrière (FR en wheelie) ET facilite le soulèvement de l'avant pour monter un trottoir. Il facilite aussi le soulèvement de l'avant aux trottoirs.","s":16},{"q":"Une orthèse KAFO stabilise le genou en :","o":["En flexion à 90°, pour la position assise","En extension, avec la cheville en flexion dorsale","En rotation interne, pied tourné en dedans","Dans aucune position fixe, l'orthèse restant libre au genou"],"r":1,"e":"KAFO = genou EN EXTENSION + cheville en légère flexion dorsale (5-10°). La flexion dorsale est de 5 à 10°.","s":16},{"q":"Bénéfices du standing-frame :","o":["Une hausse de la spasticité, par mise en charge","Moins de perte osseuse et de spasticité","Une baisse de l'estime de soi, par dépendance au matériel","Aucun bénéfice démontré à ce jour"],"r":1,"e":"Standing-frame : ↓ perte densité osseuse, ↓ spasticité, ↑ indépendance/fonctionnalité/estime de soi. L'estime de soi augmente aussi.","s":16},{"q":"Marche à 3 points : la charge sur le MI blessé est :","o":["Totale, le membre portant tout le poids","Partielle, le membre touchant le sol légèrement","Nulle, le membre ne touchant pas le sol","Variable, selon la douleur du jour"],"r":2,"e":"Marche à 3 points = charge NULLE sur le MI blessé (ne touche PAS le sol).","s":16},{"q":"Marche à 3 points MODIFIÉS : la charge sur le MI blessé est :","o":["Nulle, le membre restant en l'air","Partielle, avec un appui autorisé","Totale, sans aucune restriction","Variable selon le moment du pas"],"r":1,"e":"3 points modifiés = charge PARTIELLE autorisée sur le MI blessé.","s":16},{"q":"Le pourcentage de patients avec lésion médullaire capables de marcher est d'environ :","o":["10%","25%","50%","90%"],"r":2,"e":"Harvey (2008) : environ 50% des personnes avec lésion médullaire sont capables de marcher.","s":16},{"q":"La marche pendulaire (swing-through) se distingue de la semi-pendulaire (swing-to) par :","o":["Aucune différence, ce sont deux noms d'une même marche","Les jambes dépassent la ligne des aides","L'utilisation d'une seule béquille","L'absence d'orthèses aux jambes"],"r":1,"e":"Pendulaire (swing-THROUGH) : les MI DÉPASSENT la ligne des aides. Semi (swing-TO) : MI s'arrêtent à la ligne.","s":16},{"q":"Pour monter un trottoir avec déambulateur, on commence par :","o":["Le membre blessé, en premier, avant le déambulateur","Le déambulateur, puis le membre sain","Un saut à pieds joints, déambulateur levé","Les deux jambes, le déambulateur en dernier"],"r":1,"e":"Déambulateur sur trottoir → MI SAIN monte → puis MI blessé. Le membre blessé suit en dernier.","s":16},{"q":"Pour MONTER un escalier en FR avec 2/3 aides, le 1er transporteur est :","o":["Face aux escaliers, aux grandes roues","Dos aux escaliers, tenant les poignées","À côté du fauteuil, à la roue","Devant le patient, aux repose-pieds"],"r":1,"e":"MONTÉE : 1er DOS aux escaliers aux poignées + commandes ; les autres aux mains courantes. Il donne les commandes ; les autres sont aux mains courantes.","s":16},{"q":"Pour DESCENDRE un escalier en FR avec 2/3 aides :","o":["Le 1ᵉʳ transporteur dos aux escaliers, aux poignées","Le 1ᵉʳ face à l'escalier, aux poignées, les autres aux jantes","Les transporteurs sur le côté, aux grandes roues, sans commande","Aucune règle, selon la place disponible"],"r":1,"e":"DESCENTE : 1er FACE à l'escalier aux poignées ; 2e/3e aux jantes propulsives.","s":16},{"q":"Marche à 2 points : avance simultanée de :","o":["Les deux aides, puis les deux pieds","Une aide et le pied opposé, puis l'inverse","Tous les éléments en même temps, en un seul bloc","Une seule aide, du côté sain"],"r":1,"e":"Marche à 2 points : avance simultanée CROISÉE (aide gauche + MI droit), proche du pas physiologique.","s":16},{"q":"L'utilisation d'une canne chez l'hémiparésique :","o":["Elle augmente le travail musculaire du membre inférieur","Elle réduit le travail du membre inférieur et active le tronc","Elle n'a aucun effet mesurable sur le travail musculaire du patient","Elle bloque la marche, par appui excessif"],"r":1,"e":"Buurke et al. (2005) : la canne réduit le travail musculaire du MI et active les extenseurs du tronc + tibial antérieur. Elle active les extenseurs du tronc et le tibial antérieur.","s":16},{"q":"La règle générale pour escaliers avec une aide unilatérale :","o":["L'aide du côté blessé, la rampe du même côté","L'aide du côté sain, la rampe de l'autre main","L'aide tenue au milieu, à deux mains","Aucune aide, la rampe seule"],"r":1,"e":"Aide TOUJOURS du côté du MI SAIN, rampe (si disponible) avec la main opposée.","s":16},{"q":"Un fauteuil roulant manuel adapté doit avoir :","o":["Un siège quelconque, pourvu qu'il soit rembourré","Une assise adaptée en largeur et en profondeur","Des roues plates, pour plus de stabilité","Un dossier haut, quel que soit le patient"],"r":1,"e":"Largeur trop grande = bascule latérale ; trop étroite = points de pression. Profondeur = 2-3 doigts derrière le creux poplité. Largeur des hanches plus 2 à 3 cm ; profondeur à 2 ou 3 doigts du creux poplité.","s":16},{"q":"L'angle du repose-pied du FR :","o":["Il doit être à 0°, jambes tendues","Il doit placer hanche et genou à environ 90°","Il doit être très en arrière, sous l'assise","Il doit laisser les pieds pendre librement"],"r":1,"e":"Pieds reposés → hanche et genou ≈ 90°, alignement neutre, prévention œdème et ↓ pression ischiatique.","s":16},{"q":"Sur un terrain accidenté (graviers), le déambulateur :","o":["Il convient parfaitement, quel que soit le sol","Il peut être instable, d'où des aides plus stables","Il roule mieux que sur un sol lisse","Il est inutile, le patient devant rester à l'intérieur"],"r":1,"e":"Roulettes/embouts peuvent glisser/coincer → préférer des aides plus stables ou un accompagnement physique. Un cadre lesté ou une aide humaine sont préférables.","s":16},{"q":"L'orthèse anti-équin sert à :","o":["Renforcer le mollet par un effort résistant","Tenir la cheville à 90° pour permettre la marche","Bloquer le genou en extension pendant la marche, en appui","Allonger le tibia de 2 cm chez l'enfant"],"r":1,"e":"Releveur (AFO) → empêche la chute du pied à la phase oscillante (atteinte du fibulaire commun, hémiplégie). Il corrige le pied tombant.","s":16},{"q":"En descente d'escalier avec béquilles, on commence par :","o":["Le membre sain, en premier","Les béquilles et le membre atteint","La tête en bas, en avant","Un saut, pieds joints, marche par marche"],"r":1,"e":"Descente : les béquilles + le MI atteint vont en premier (le sain reste en haut). Montée : MI sain en premier.","s":16},{"q":"Selon Bateni & Maki (2005), l'augmentation de la base d'appui :","o":["Garde le centre de gravité dans la base plus longtemps","Accélère la marche, à pas plus longs","Réduit nettement la dépense énergétique de la marche","Augmente la longueur du pas à chaque cycle"],"r":0,"e":"C'est ce qui justifie la hiérarchie des aides, du déambulateur à la canne. Sur une plus grande partie du cycle de marche.","s":16},{"q":"Le déambulateur articulé présente l'intérêt :","o":["De faciliter la dissociation des ceintures","D'être plus léger que les modèles fixes","D'être plus stable sur les sols en pente","De se plier plus facilement"],"r":0,"e":"Sa base d'appui quadrangulaire reste la plus grande de toutes les aides.","s":16},{"q":"Le trépied et la pyramide permettent une utilisation unilatérale :","o":["En tournant simplement la poignée","En changeant les embouts","En les raccourcissant d'un cran","Ce n'est pas possible du tout"],"r":0,"e":"La concavité de la poignée se tourne vers le patient et les points d'appui vers l'extérieur.","s":16},{"q":"Les béquilles canadiennes existent en variantes pour :","o":["Les arthritiques, qui ne peuvent charger poignet ni main","Les enfants, avec une taille réduite","Les sportifs, avec un alliage léger pour la compétition","Les personnes âgées, avec une poignée chauffante"],"r":0,"e":"Leurs sangles peuvent être fixes ou articulées, fermées ou ouvertes. Les doigts ne peuvent pas non plus être chargés.","s":16},{"q":"Le support thoracique de la béquille axillaire ne doit pas toucher l'aisselle afin :","o":["D'éviter de comprimer les nerfs et vaisseaux axillaires","De réduire la douleur à l'épaule, en cas d'appui prolongé","D'améliorer l'équilibre en marche","De faciliter la propulsion du corps"],"r":0,"e":"Il se place environ 10 cm en dessous, contre la cage thoracique en latéral.","s":16},{"q":"Selon Buurke et al. (2005), la canne chez l'hémiparésique :","o":["Réduit le travail du membre inférieur et active le tronc","Augmente le travail musculaire du membre inférieur","N'a aucun effet mesurable sur le travail musculaire du patient","Diminue l'équilibre en position debout"],"r":0,"e":"Laufer (2003) montre de son côté que le trépied réduit le balancement postural chez l'hémiplégique. Elle active les extenseurs du tronc et le tibial antérieur.","s":16},{"q":"Les barres parallèles sont idéales pour :","o":["Démarrer la marche, avec une sécurité maximale","Les longs déplacements en extérieur, en ville","L'usage quotidien à domicile","La marche sur terrain irrégulier"],"r":0,"e":"Elles permettent aussi l'entraînement aux transferts assis-debout.","s":16},{"q":"Le dossier du fauteuil roulant se règle :","o":["À 10 cm sous l'aisselle, près de l'angle de l'omoplate","Au niveau des épaules, pour soutenir la tête","Au niveau des crêtes iliaques, à 20 cm sous l'omoplate","Sans repère précis, selon le confort"],"r":0,"e":"Sa hauteur dépend du contrôle du tronc : haut pour la tétraplégie, bas pour la paraplégie. Soit 2,5 à 5 cm de l'angle inférieur de l'omoplate.","s":16},{"q":"Les roues libres du fauteuil roulant :","o":["Mesurent environ 20 cm et assurent le braquage","Mesurent 61 cm et portent les jantes","Assurent la propulsion par le patient, à l'arrière","Portent les jantes propulsives et les freins"],"r":0,"e":"Les grandes roues, de 61 cm, portent les jantes propulsives utilisées par le patient.","s":16},{"q":"L'orthèse KAFO stabilise :","o":["Le genou en extension et la cheville en flexion dorsale","Le genou en flexion et la cheville en équin","La hanche en extension et le bassin en rétroversion marquée","Le bassin, par une ceinture pelvienne"],"r":0,"e":"Elle comporte souvent deux barres longitudinales et des supports de cuisse, jambe et pied, parfois articulés pour permettre la flexion assise. La flexion dorsale est de 5 à 10°.","s":16},{"q":"L'orthèse HKAFO ajoute :","o":["La stabilisation latérale du bassin en appui","La stabilisation du pied en éversion","Une articulation libre au genou","Un appui thoracique sous les deux aisselles"],"r":0,"e":"Les orthèses permettent la marche aux patients vertébro-médullaires. Elle est essentielle en phase d'appui.","s":16},{"q":"Selon Holland & Holland (2006), le standing-frame :","o":["Augmente l'indépendance et l'estime de soi","Diminue la spasticité des membres inférieurs","Limite la perte de densité osseuse","Améliore la circulation des jambes"],"r":0,"e":"Goktepe et al. (2008) documentent la limitation de la perte de densité minérale osseuse et Harvey (2008) la diminution de spasticité. La fonctionnalité augmente aussi.","s":16},{"q":"Dans la marche à quatre points, les aides se placent :","o":["À 15 cm devant et en dehors de chaque pied","Au contact direct des pieds, à leur bord externe","À 30 cm devant, dans l'axe des pieds","Derrière les pieds, à 10 cm"],"r":0,"e":"La séquence alterne aide droite, membre gauche, aide gauche, membre droit. Elles sont au même niveau.","s":16},{"q":"Dans la marche à trois points, le poids est réparti :","o":["Entre les aides et le membre inférieur sain","Entre les deux membres inférieurs, également","Sur le membre lésé, en appui partiel léger","Sur les seules aides, membres levés"],"r":0,"e":"Les aides avancent simultanément, le membre lésé ne prenant aucun appui.","s":16},{"q":"La profondeur de l'assise d'un fauteuil roulant se règle :","o":["À 5 à 7 cm de la région poplitée","Au contact du creux poplité","À 15 cm","Sans repère"],"r":0,"e":"L'assise doit permettre un angle de 90° aux hanches et aux genoux.","s":16},{"q":"La protection latérale du fauteuil roulant se place :","o":["À environ 2 à 3 cm des hanches","Au contact direct des hanches, sans espace","À 10 cm des hanches","Sans réglage possible"],"r":0,"e":"Les accoudoirs permettent, eux, le repos des membres supérieurs coude à 90° et les push-ups.","s":16},{"q":"Le châssis du fauteuil roulant peut être :","o":["Articulé en X, donc pliable, ou rigide","Uniquement pliable, en accordéon","Uniquement rigide, en une seule pièce","Télescopique, en largeur"],"r":0,"e":"Les dispositifs anti-chute préviennent les chutes arrière et facilitent le soulèvement avant aux trottoirs.","s":16},{"q":"Selon Youdas (2005), les béquilles axillaires sont :","o":["Plus efficaces pour contrôler l'appui partiel","Moins efficaces que les cannes pour l'appui partiel","Équivalentes aux cannes simples","Contre-indiquées en appui partiel"],"r":0,"e":"Leur usage unilatéral est par ailleurs peu fréquent. Il s'agit du transfert partiel du poids.","s":16},{"q":"Selon Bateni & Maki (2005), l'aide controlatérale réduit la charge coxo-fémorale de :","o":["60 %","30 %","80 %","20 %"],"r":0,"e":"C'est ce qui justifie l'usage du côté opposé à la dysfonction.","s":16},{"q":"Les repose-pieds du fauteuil roulant se règlent :","o":["Cheville en position neutre, à environ 5 cm du sol","Pieds au contact du sol, pour un appui plus stable","À 15 cm du sol, avec les genoux tendus","En flexion plantaire, les pieds pendants"],"r":0,"e":"Ils peuvent être fixes ou amovibles, ce qui conditionne les transferts.","s":16}]};
